def _v21027_file_last_bot_version(default=""):
    try:
        import re as _re
        from pathlib import Path as _Path
        vals = _re.findall(r'^\s*BOT_VERSION\s*=\s*[\'\"]([^\'\"]+)', _Path(__file__).read_text(encoding='utf-8', errors='ignore'), flags=_re.M)
        return vals[-1] if vals else (default or globals().get('BOT_VERSION', ''))
    except Exception:
        return default or globals().get('BOT_VERSION', '')

def _v21027_send_raw_telegram(text: str) -> bool:
    try:
        token = os.getenv('TELEGRAM_TOKEN') or globals().get('TELEGRAM_TOKEN')
        chat_id = os.getenv('CHAT_ID') or globals().get('CHAT_ID')
        if not token or not chat_id:
            return False
        import urllib.parse as _urlparse
        import urllib.request as _urlrequest
        body = _urlparse.urlencode({'chat_id': str(chat_id), 'text': str(text)[:3800]}).encode('utf-8')
        req = _urlrequest.Request(f'https://api.telegram.org/bot{token}/sendMessage', data=body)
        _urlrequest.urlopen(req, timeout=6).read()
        return True
    except Exception:
        return False

def _v21027_startup_excepthook(exc_type, exc, tb):
    try:
        import traceback as _traceback
        import time as _time
        from pathlib import Path as _Path
        version = _v21027_file_last_bot_version(globals().get('BOT_VERSION', ''))
        short = ''.join(_traceback.format_exception_only(exc_type, exc)).strip()
        trace_tail = ''.join(_traceback.format_exception(exc_type, exc, tb))[-2400:]
        key = f"{exc_type.__name__}:{str(exc)[:120]}"
        stamp = _Path('/tmp/tradingbot_startup_crash_notify.stamp')
        now = int(_time.time())
        allow = True
        try:
            if stamp.exists():
                old = stamp.read_text(encoding='utf-8', errors='ignore').split('|', 1)
                if len(old) == 2 and old[1] == key and now - int(old[0] or '0') < 180:
                    allow = False
            stamp.write_text(f"{now}|{key}", encoding='utf-8')
        except Exception:
            pass
        if allow:
            _v21027_send_raw_telegram(
                "🚨 코인봇 시작 실패 감지\n"
                f"- 버전: {version}\n"
                f"- 오류: {short}\n"
                "- 위치: 텔레그램 수신 시작 전/부팅 중\n"
                "- 조치: /errorlog 불가 시 서버 journalctl 확인\n\n"
                f"{trace_tail}"
            )
    finally:
        try:
            sys.__excepthook__(exc_type, exc, tb)
        except Exception:
            pass

sys.excepthook = _v21027_startup_excepthook
try:
    if hasattr(threading, 'excepthook'):
        def _v21027_thread_excepthook(args):
            try:
                _v21027_startup_excepthook(args.exc_type, args.exc_value, args.exc_traceback)
            except Exception:
                pass
        threading.excepthook = _v21027_thread_excepthook
except Exception:
    pass

