def compute_rebreakout_display_score(raw_score: float, prep_score: float, attempts: int, success_attempts: int, failed_attempts: int) -> float:
    raw_score = safe_float(raw_score, 0)
    prep_score = safe_float(prep_score, raw_score)
    attempts = int(safe_float(attempts, 0))
    success_attempts = int(safe_float(success_attempts, 0))
    failed_attempts = int(safe_float(failed_attempts, 0))
    if attempts <= 0:
        return prep_score
    display = raw_score
    if success_attempts >= 1:
        display += 0.55 + max(success_attempts - 1, 0) * 0.18
        if failed_attempts == 0:
            display = max(display, 0.45 + max(min(prep_score, 1.40), 0) * 0.25)
    if failed_attempts >= 1:
        display -= 0.45 * failed_attempts
        if success_attempts == 0:
            display = min(display, max(prep_score * 0.30, 0.15))
    if success_attempts <= 0 and failed_attempts <= 0:
        display = max(display, prep_score * 0.85)
    return round(display, 2)
def format_rebreakout_stat_text(item_or_row: dict, compact: bool = False) -> str:
    item_or_row = item_or_row if isinstance(item_or_row, dict) else {}
    raw_score = safe_float(item_or_row.get("rebreakout_raw_score", item_or_row.get("rebreakout_score", 0)), 0)
    re_score = safe_float(item_or_row.get("rebreakout_score", raw_score), raw_score)
    prep_score = safe_float(item_or_row.get("rebreakout_prep_score", re_score), re_score)
    attempts = int(safe_float(item_or_row.get("rebreakout_attempts", 0), 0))
    success_attempts = int(safe_float(item_or_row.get("rebreakout_success_attempts", 0), 0))
    failed_attempts = int(safe_float(item_or_row.get("rebreakout_failures", 0), 0))
    success_rate = safe_float(item_or_row.get("rebreakout_success_rate", 0), 0) * 100.0
    if attempts <= 0:
        prep_label = "준비 약함"
        if prep_score >= 1.00:
            prep_label = "곧 재시도 가능"
        elif prep_score >= 0.45:
            prep_label = "재돌파 준비중"
        elif prep_score >= 0.15:
            prep_label = "아직 시도 전"
        return f"고점 다시도전 힘 {prep_score:.2f}({prep_label})"
    if success_attempts <= 0 and failed_attempts <= 0:
        return f"고점 다시도전 힘 {re_score:.2f}(확인중)"
    return f"고점 다시도전 힘 {re_score:.2f}({success_rate:.0f}% / 성공 {success_attempts}회 / 실패 {failed_attempts}회)"
def get_recovery_profile_snapshot(item_or_row: dict) -> dict:
    item_or_row = item_or_row if isinstance(item_or_row, dict) else {}
    score = safe_float(item_or_row.get("recovery_quality_score", 0), 0)
    dwell = int(safe_float(item_or_row.get("low_zone_stay_bars", 0), 0))
    reclaim = int(safe_float(item_or_row.get("low_zone_reclaim_count", 0), 0))
    defense = safe_float(item_or_row.get("low_zone_defense_score", 0), 0)
    persist = safe_float(item_or_row.get("turnover_persistence_score", 0), 0)
    ratio3 = safe_float(item_or_row.get("turnover_sustain_ratio_3v10", 0), 0)
    ratio5 = safe_float(item_or_row.get("turnover_sustain_ratio_5v20", 0), 0)
    snap = ensure_pre_alert_snapshot(item_or_row) if isinstance(item_or_row, dict) else {}
    from_low = safe_float(snap.get("from_30m_low_pct", item_or_row.get("from_30m_low_pct", 0)), 0)
    high_gap_pct = get_effective_high_gap_pct(item_or_row) if isinstance(item_or_row, dict) else safe_float(item_or_row.get("high_gap_pct", 999), 999)
    turnover_5m = safe_float(item_or_row.get("turnover_5m", item_or_row.get("turnover_recent_5m", 0)), 0)
    promising = bool(
        score >= 1.10
        and high_gap_pct >= 1.00
        and (dwell >= 2 or reclaim >= 1)
        and (persist >= 0.70 or ratio3 >= 1.15 or turnover_5m >= 750000)
        and from_low <= 2.20
    )
    strong = bool(
        score >= 1.45
        and high_gap_pct >= 1.15
        and (dwell >= 3 or reclaim >= 1)
        and (persist >= 0.95 or ratio3 >= 1.30)
        and from_low <= 1.90
    )
    return {
        "recovery_quality_score": score,
        "low_zone_stay_bars": dwell,
        "low_zone_reclaim_count": reclaim,
        "low_zone_defense_score": defense,
        "turnover_persistence_score": persist,
        "turnover_sustain_ratio_3v10": ratio3,
        "turnover_sustain_ratio_5v20": ratio5,
        "recovery_profile_promising": promising,
        "recovery_profile_strong": strong,
    }
def is_low_structure_unverified_v245(item_or_row: dict) -> bool:
    """v2.5.245: 저점방어 0점과 정밀차트 미검증을 분리한다."""
    try:
        row = item_or_row if isinstance(item_or_row, dict) else {}
        route = str(row.get("low_structure_route_v244", "") or "").strip()
        if route and route not in {"저점 구조 확인중", ""}:
            return False
        low_keys = [
            "low_defense_v2_score", "low_structure_score_v2", "low_zone_defense_score",
            "recovery_quality_score", "low_rising_score_v2", "low_recent_reclaim_bars_v244",
            "low_zone_stay_bars", "low_zone_reclaim_count", "turnover_persistence_score",
        ]
        for key in low_keys:
            if abs(safe_float(row.get(key, 0), 0)) > 0.0001:
                return False
        chart_keys = ["candle_body_ratio_1", "body_ratio_1", "close_position_ratio_1", "close_pos_1", "upper_wick_pct_1", "lower_wick_pct_1"]
        has_chart_value = any(abs(safe_float(row.get(k, 0), 0)) > 0.0001 for k in chart_keys)
        source = str(row.get("precision_chart_source", row.get("current_candle_source", row.get("source", ""))) or "").lower()
        sample = int(safe_float(row.get("sample_candles_1m", row.get("minute1_candles", row.get("snapshot_rows", 0))), 0))
        if (not has_chart_value) and (sample <= 3 or "snapshot" in source or "realtime_snapshot" in source or "light_snapshot" in source):
            return True
        return False
    except Exception:
        return False
def low_defense_structure_route_is_good_v248(row: dict) -> bool:
    try:
        route = get_low_structure_route_label_v244(row if isinstance(row, dict) else {}) if 'get_low_structure_route_label_v244' in globals() else ""
        return route in {"저점높임 재출발형", "저점방어 재출발형", "저점방어 관찰형"}
    except Exception:
        return False
def assess_low_defense_quality_v248(row: dict) -> dict:
    """v2.5.248: 저점방어 구조와 최종 승격 품질을 분리한다."""
    try:
        row = row if isinstance(row, dict) else {}
        if not bool(globals().get("LOW_DEFENSE_QUALITY_V248_ON", True)):
            return {"enabled": False}
        route = get_low_structure_route_label_v244(row) if 'get_low_structure_route_label_v244' in globals() else ""
        if route not in {"저점높임 재출발형", "저점방어 재출발형", "저점방어 관찰형"}:
            return {"enabled": True, "route": route, "has_structure": False, "promote_ok": False, "label": route or "저점 구조 확인중"}
        reasons = []
        money_code = money_status_code_for_row(row) if 'money_status_code_for_row' in globals() else "unknown"
        if money_code in {"actual_zero", "tiny", "thin"}:
            reasons.append("돈얇음")
        sustain = classify_money_sustain_for_row(row) if 'classify_money_sustain_for_row' in globals() else {}
        sustain_label = str((sustain or {}).get("label", row.get("money_sustain_label", "")) or "")
        buy = safe_float(row.get("ws_trade_buy_ratio_60s", 0), 0)
        cnt = int(safe_float(row.get("ws_trade_count_60s", 0), 0))
        if "매도우세" in sustain_label or (cnt >= 5 and 0 < buy <= safe_float(globals().get("LOW_DEFENSE_V248_SELL_HEAVY_BUY_RATIO_MAX", 45.0), 45.0)):
            reasons.append("매도우세")
        try:
            weak_candle = is_current_candle_weak_for_label_v244(row) if 'is_current_candle_weak_for_label_v244' in globals() else False
        except Exception:
            weak_candle = False
        candle_label = str(row.get("current_candle_label", row.get("current_candle_code", "")) or "")
        if weak_candle or "밀림" in candle_label or "위꼬리" in candle_label:
            reasons.append("현재봉 밀림")
        high_gap = safe_float(row.get("below_30m_high_pct", row.get("below_high", 999)), 999)
        from_low = safe_float(row.get("from_low", row.get("from_30m_low_pct", 0)), 0)
        if 0 <= high_gap <= safe_float(globals().get("LOW_DEFENSE_V248_NEAR_HIGH_BLOCK_GAP", 0.20), 0.20) and from_low >= 0.80:
            reasons.append("고점 바로 앞")
        dedup = []
        for r in reasons:
            if r and r not in dedup:
                dedup.append(r)
        blocked = bool(dedup)
        if blocked:
            label = f"{route} / 승격금지({', '.join(dedup[:3])})"
            short = "저점방어 구조 있음 / " + "·".join(dedup[:3]) + "으로 매수 후보 아님"
            quality = "structure_only_blocked"
        else:
            label = route
            short = f"{route} / 돈·현재봉 확인 통과"
            quality = "promote_ok"
        return {"enabled": True, "route": route, "has_structure": True, "promote_ok": not blocked, "blocked": blocked, "block_reasons": dedup, "block_reason_text": "·".join(dedup), "quality": quality, "label": label, "short": short}
    except Exception as e:
        return {"enabled": True, "error": str(e)[:80], "promote_ok": False, "label": "저점방어 품질 확인중"}
def apply_low_defense_quality_v248(row: dict) -> dict:
    try:
        if not isinstance(row, dict):
            return row
        q = assess_low_defense_quality_v248(row)
        if not isinstance(q, dict) or not q.get("enabled", True):
            return row
        if q.get("has_structure", False):
            row["low_defense_quality_v248"] = str(q.get("quality", ""))
            row["low_defense_final_label_v248"] = str(q.get("label", ""))
            row["low_defense_quality_short_v248"] = str(q.get("short", ""))
            row["low_defense_promote_ok_v248"] = bool(q.get("promote_ok", False))
            row["low_defense_block_reasons_v248"] = list(q.get("block_reasons", []) or [])
            row["low_defense_block_reason_text_v248"] = str(q.get("block_reason_text", ""))
        return row
    except Exception:
        return row
def classify_high_rebreakout_hold_v248(row: dict) -> dict:
    """v2.5.248: 고점 바로 앞 후보를 재돌파 유지/추격위험/관찰로 분리."""
    try:
        row = row if isinstance(row, dict) else {}
        if not bool(globals().get("HIGH_REBREAKOUT_V248_ON", True)):
            return {"enabled": False}
        gap = safe_float(row.get("below_30m_high_pct", row.get("below_high", 999)), 999)
        if gap >= 900:
            return {"enabled": True, "label": "고점거리 확인중", "code": "unknown", "score": 0.0}
        buy = safe_float(row.get("ws_trade_buy_ratio_60s", 0), 0)
        cnt = int(safe_float(row.get("ws_trade_count_60s", 0), 0))
        amount = safe_float(row.get("ws_trade_amount_60s", 0), 0)
        live = safe_float(row.get("current_candle_live_score", 0), 0)
        pressure = safe_float(row.get("current_candle_pressure_score", 0), 0)
        follow = safe_float(row.get("current_candle_follow_score", 0), 0)
        current_chg = safe_float(row.get("current_candle_change_pct", row.get("change_1", 0)), 0)
        try:
            weak = is_current_candle_weak_for_label_v244(row) if 'is_current_candle_weak_for_label_v244' in globals() else False
        except Exception:
            weak = False
        near_gap = safe_float(globals().get("HIGH_REBREAKOUT_V248_NEAR_GAP_PCT", 0.35), 0.35)
        hold_gap = safe_float(globals().get("HIGH_REBREAKOUT_V248_HOLD_GAP_PCT", 0.20), 0.20)
        good_buy = safe_float(globals().get("HIGH_REBREAKOUT_V248_GOOD_BUY_RATIO", 60.0), 60.0)
        score = 0.0
        if 0 <= gap <= near_gap: score += 1.0
        if 0 <= gap <= hold_gap: score += 0.6
        if cnt >= 5 and buy >= good_buy: score += 1.0
        if amount >= 1_000_000: score += 0.5
        if live >= 2.0 or follow >= 1.2 or current_chg >= 0.35: score += 0.8
        if weak or pressure >= 1.2 or (cnt >= 5 and 0 < buy <= 45): score -= 1.2
        if gap <= near_gap and score >= 2.2:
            label, code = "고점 재돌파 유지 확인", "rebreak_hold"
        elif gap <= near_gap and score >= 1.0:
            label, code = "고점 재접근 관찰", "near_high_watch"
        elif gap <= near_gap:
            label, code = "고점 앞 밀림/추격금지", "near_high_reject"
        else:
            label, code = "고점 여유 확인", "not_near_high"
        return {"enabled": True, "label": label, "code": code, "score": round(score, 2), "gap": gap, "buy_ratio": buy, "trade_count": cnt}
    except Exception as e:
        return {"enabled": True, "label": "고점 재돌파 확인중", "code": "error", "error": str(e)[:80]}
def apply_high_rebreakout_hold_v248(row: dict) -> dict:
    try:
        if not isinstance(row, dict):
            return row
        h = classify_high_rebreakout_hold_v248(row)
        if not isinstance(h, dict) or not h.get("enabled", True):
            return row
        row["high_rebreakout_v248_label"] = str(h.get("label", ""))
        row["high_rebreakout_v248_code"] = str(h.get("code", ""))
        row["high_rebreakout_v248_score"] = safe_float(h.get("score", 0), 0)
        row["high_rebreakout_v248_gap"] = safe_float(h.get("gap", 999), 999)
        return row
    except Exception:
        return row
def _dedupe_reason_bits_v251(bits) -> list:
    out = []
    try:
        for b in bits or []:
            b = str(b or "").strip()
            if b and b not in out:
                out.append(b)
    except Exception:
        pass
    return out
def build_final_candidate_display_context_v251(row: dict) -> dict:
    """v2.5.251 판단통합 정리판.
    rank_short / rank_watch / review_watch / trace_detail의 결론이 서로 흔들리지 않게
    돈흐름·현재봉·저점방어·고점재돌파 결과를 하나의 표시용 결론으로 합친다.
    """
    try:
        row = row if isinstance(row, dict) else {}
        reasons = []
        money_code = money_status_code_for_row(row) if 'money_status_code_for_row' in globals() else "unknown"
        try:
            sustain = classify_money_sustain_for_row(row) if 'classify_money_sustain_for_row' in globals() else {}
        except Exception:
            sustain = {}
        sustain_label = str(row.get("money_sustain_label", "") or (sustain or {}).get("label", "") or "")
        buy = safe_float(row.get("ws_trade_buy_ratio_60s", 0), 0)
        cnt = int(safe_float(row.get("ws_trade_count_60s", 0), 0))
        score = safe_float(row.get("snapshot_rank_score", row.get("lite_score", 0)), 0)
        strongest = _row_strongest_rank_move(row) if '_row_strongest_rank_move' in globals() else max(
            safe_float(row.get("change_1", 0), 0), safe_float(row.get("change_3", 0), 0),
            safe_float(row.get("change_5", 0), 0), safe_float(row.get("change_30", 0), 0)
        )
        high = classify_high_rebreakout_hold_v248(row) if 'classify_high_rebreakout_hold_v248' in globals() else {}
        high_label = str((high or {}).get("label", row.get("high_rebreakout_v248_label", "")) or "")
        high_code = str((high or {}).get("code", row.get("high_rebreakout_v248_code", "")) or "")
        low_route = get_low_structure_route_label_v244(row) if 'get_low_structure_route_label_v244' in globals() else ""
        low_q = assess_low_defense_quality_v248(row) if 'assess_low_defense_quality_v248' in globals() else {}
        low_has = bool((low_q or {}).get("has_structure", False))
        low_blocked = bool((low_q or {}).get("blocked", False))
        low_ok = bool((low_q or {}).get("promote_ok", False)) if low_has else False
        if low_blocked:
            reasons += list((low_q or {}).get("block_reasons", []) or [])
        weak_candle = is_current_candle_weak_for_label_v244(row) if 'is_current_candle_weak_for_label_v244' in globals() else False
        flash_limited = is_money_or_candle_flash_watch_limited_v244(row) if 'is_money_or_candle_flash_watch_limited_v244' in globals() else False
        if money_code in {"actual_zero", "tiny"}:
            reasons.append("실제돈작음")
        elif money_code == "thin":
            reasons.append("돈얇음")
        if "매도우세" in sustain_label or (cnt >= 5 and 0 < buy <= 45):
            reasons.append("매도우세")
        if weak_candle:
            reasons.append("현재봉 밀림")
        if high_code == "near_high_reject":
            reasons.append("고점근처 재돌파 유지 미확인")
        elif high_code == "near_high_watch" and low_has and not low_ok:
            reasons.append("고점근처 확인 필요")
        reasons = _dedupe_reason_bits_v251(reasons)
        if money_code in {"actual_zero", "tiny"} and score < 9.0 and strongest < 1.20:
            main = "돈 약함 확인"; state = "실제돈작음 / 복기 우선"; action = "복기용 기록"; watch_action = "빠른하향"
        elif flash_limited or ("반짝" in sustain_label or "식는" in sustain_label or (cnt >= 5 and 0 < buy <= 45)):
            main = "반짝형 관찰"; state = "반짝형 관찰"; action = "반짝형 관찰"; watch_action = "관찰만"
        elif weak_candle:
            main = "위꼬리/현재봉 밀림"; state = "위꼬리/현재봉 밀림"; action = "반짝형 관찰"; watch_action = "관찰만"
        elif low_has and low_blocked:
            main = "저점방어 구조만 확인"; state = "저점방어 구조 있음/승격금지"; action = "복기용 기록"; watch_action = "승격금지"
        elif low_has and low_ok:
            label = str((low_q or {}).get("label", "") or low_route)
            main = label; state = label; action = "정밀검토 대기" if label != "저점방어 관찰형" else "복기용 기록"; watch_action = "내부감시"
        elif high_code == "rebreak_hold":
            main = "고점 재돌파 유지 확인"; state = "고점 재돌파 유지 확인"; action = "정밀검토 대기"; watch_action = "내부감시"
        elif high_code == "near_high_reject":
            main = "고점 앞 밀림/추격금지"; state = "고점 앞 밀림/추격금지"; action = "복기용 기록"; watch_action = "승격금지"
        else:
            base_state = str(row.get("chart_lifecycle_label", row.get("rank_watch_chart_state", row.get("primary_reason", ""))) or "").strip()
            base_action = str(row.get("rank_watch_action", row.get("primary_reason", "")) or "").strip()
            main = base_state or base_action or "상태 확인중"; state = base_state or main; action = base_action or main; watch_action = "확인중"
        if not reasons and low_has and low_blocked:
            text = str((low_q or {}).get("block_reason_text", "") or "").strip()
            reasons = _dedupe_reason_bits_v251(text.replace(",", "·").split("·")) if text else []
        reason_text = "·".join(reasons)
        one_liner = ""
        if reason_text:
            if watch_action == "승격금지" or "승격금지" in state:
                one_liner = f"구조는 있지만 {reason_text} 때문에 승격 금지"
            elif watch_action == "빠른하향":
                one_liner = f"{reason_text}이라 내부감시 슬롯 오래 먹이지 않음"
            else:
                one_liner = reason_text
        return {
            "main_label": main, "state_label": state, "action_label": action, "watch_action": watch_action,
            "block_reasons": reasons, "block_reason_text": reason_text, "one_liner": one_liner,
            "money_code": money_code, "high_label": high_label, "high_code": high_code,
            "low_route": low_route, "low_has_structure": low_has, "low_promote_ok": low_ok,
        }
    except Exception as e:
        return {"main_label": "상태 확인중", "state_label": "상태 확인중", "action_label": "상태 확인중", "block_reason_text": "", "error": str(e)[:80]}
def apply_final_candidate_display_context_v251(row: dict) -> dict:
    try:
        if not isinstance(row, dict):
            return row
        ctx = build_final_candidate_display_context_v251(row)
        if not isinstance(ctx, dict):
            return row
        row["final_candidate_main_label_v251"] = str(ctx.get("main_label", "") or "")
        row["final_candidate_state_v251"] = str(ctx.get("state_label", "") or "")
        row["final_candidate_action_v251"] = str(ctx.get("action_label", "") or "")
        row["final_candidate_watch_action_v251"] = str(ctx.get("watch_action", "") or "")
        row["final_candidate_block_reason_text_v251"] = str(ctx.get("block_reason_text", "") or "")
        row["final_candidate_one_liner_v251"] = str(ctx.get("one_liner", "") or "")
        row["final_candidate_high_label_v251"] = str(ctx.get("high_label", "") or "")
        row["final_candidate_low_route_v251"] = str(ctx.get("low_route", "") or "")
        main = row["final_candidate_main_label_v251"]
        state = row["final_candidate_state_v251"]
        action = row["final_candidate_action_v251"]
        if state:
            row["chart_lifecycle_label"] = state
            row["rank_watch_chart_state"] = state
        if action:
            row["rank_watch_action"] = action
            row["primary_reason"] = main or action
            row["label_text"] = main or action
        if row.get("final_candidate_one_liner_v251"):
            row["one_liner"] = row["final_candidate_one_liner_v251"]
        return row
    except Exception:
        return row
def format_recovery_profile_text(item_or_row: dict, compact: bool = False) -> str:
    if is_low_structure_unverified_v245(item_or_row):
        return "저점방어 판단보류(정밀 1분봉 미검증) / 저점체류 확인전·재확인 확인전 / 돈이 계속 붙는 힘 확인전"
    prof = get_recovery_profile_snapshot(item_or_row)
    score = safe_float(prof.get("recovery_quality_score", 0), 0)
    dwell = int(prof.get("low_zone_stay_bars", 0))
    reclaim = int(prof.get("low_zone_reclaim_count", 0))
    persist = safe_float(prof.get("turnover_persistence_score", 0), 0)
    low_v2_label = str((item_or_row or {}).get("low_structure_summary_v2", (item_or_row or {}).get("low_defense_v2_label", "")) or "").strip()
    low_v2_score = safe_float((item_or_row or {}).get("low_defense_v2_score", 0), 0)
    if low_v2_label and low_v2_score > 0:
        low_text = f"{low_v2_label} {low_v2_score:.2f}"
    else:
        low_text = f"저점 버틴 힘 {score:.2f}"
    if compact:
        return f"{low_text} / 저점체류 {dwell}봉·재확인 {reclaim}회 / 돈이 계속 붙는 힘 {persist:.2f}"
    return f"{low_text} / 저점체류 {dwell}봉·재확인 {reclaim}회 / 돈이 계속 붙는 힘 {persist:.2f}"
def is_recovery_profile_promising(item: dict) -> bool:
    return bool(get_recovery_profile_snapshot(item).get("recovery_profile_promising", False))
def is_chart_current_candle_uninformative(item: dict) -> bool:
    body1 = safe_float(item.get("candle_body_ratio_1", 0), 0)
    close1 = safe_float(item.get("close_position_ratio_1", 0), 0)
    upper1 = safe_float(item.get("upper_wick_pct_1", 0), 0)
    lower1 = safe_float(item.get("lower_wick_pct_1", 0), 0)
    body3 = safe_float(item.get("candle_body_ratio_3", 0), 0)
    body5 = safe_float(item.get("candle_body_ratio_5", 0), 0)
    close3 = safe_float(item.get("close_position_ratio_3", 0), 0)
    if body1 <= 0.01 and upper1 <= 0.01 and lower1 <= 0.01 and close1 <= 0.01:
        if body3 >= 0.18 or body5 >= 0.18 or close3 >= 0.18:
            return True
    return False
def format_turnover_flash_label(score: float) -> str:
    score = safe_float(score, 0)
    if score <= -6.0:
        return "반짝형 강함"
    if score <= -1.2:
        return "반짝형 약함"
    if score >= 2.5:
        return "지속형 우세"
    if score >= 0.8:
        return "지속형 보통"
    return "반짝/지속 비슷"
def format_prebreakout_simple_label(item: dict) -> str:
    item = item if isinstance(item, dict) else {}
    score = safe_float(item.get("prebreakout_ready_score", 0), 0)
    hold = int(safe_float(item.get("prebreakout_hold_near_high_bars", 0), 0))
    pullback = safe_float(item.get("prebreakout_pullback_depth_pct", 0), 0)
    reaccel = safe_float(item.get("prebreakout_volume_reaccel_score", 0), 0)
    if score >= 2.60 and reaccel >= 0.05:
        return "고점 전 준비 좋음"
    if score >= 1.35 or (hold >= 2 and 0 < pullback <= 1.8 and reaccel > -0.10):
        return "고점 전 준비 보통"
    if score <= -0.4 or pullback >= 3.0 or reaccel <= -0.25:
        return "고점 전 힘 약함"
    return "고점 전 준비 약함"
def format_htf_position_simple_text(item: dict) -> str:
    item = item if isinstance(item, dict) else {}
    bits = []
    htf_pos = str(item.get("htf_box_position_label", "") or "").strip()
    daily_pos = str(item.get("daily_box_position_label", "") or "").strip()
    rebound_day = int(safe_float(item.get("daily_rebound_day", 0), 0))
    htf_higher_low = bool(item.get("htf_higher_low_3", False))
    if htf_pos:
        bits.append(htf_pos)
    if htf_higher_low:
        bits.append("4시간 저점 높임")
    if daily_pos:
        bits.append(daily_pos)
    if rebound_day in {1, 2, 3}:
        bits.append(f"일봉 반등 {rebound_day}일차")
    return " / ".join(bits)
def _format_chart_pct_text(value: float, precision: int = 0) -> str:
    value = safe_float(value, 0)
    abs_v = abs(value)
    if abs_v < 0.05:
        return "0.0%"
    if abs_v < 1.0:
        return f"{value:.1f}%"
    if precision > 0:
        return f"{value:.{precision}f}%"
    return f"{value:.0f}%"
def _is_chart_flat_cluster(body3: float, body5: float, close3: float, close5: float, upper5: float, lower5: float) -> bool:
    return (
        abs(body3) < 0.12
        and abs(body5) < 0.18
        and abs(close3) < 5.0
        and abs(close5) < 5.0
        and abs(upper5) < 0.05
        and abs(lower5) < 0.05
    )
def format_chart_quant_summary_text(item: dict, compact: bool = False) -> str:
    ensure_roadmap_context(item)
    body1 = safe_float(item.get("candle_body_ratio_1", item.get("body_ratio_1", 0)), 0) * 100.0
    body3 = safe_float(item.get("candle_body_ratio_3", item.get("body_ratio_3", 0)), 0) * 100.0
    body5 = safe_float(item.get("candle_body_ratio_5", item.get("body_ratio_5", 0)), 0) * 100.0
    upper1 = safe_float(item.get("upper_wick_pct_1", 0), 0)
    upper3 = safe_float(item.get("upper_wick_pct_3", 0), 0)
    upper5 = safe_float(item.get("upper_wick_pct_5", 0), 0)
    lower1 = safe_float(item.get("lower_wick_pct_1", 0), 0)
    lower3 = safe_float(item.get("lower_wick_pct_3", 0), 0)
    lower5 = safe_float(item.get("lower_wick_pct_5", 0), 0)
    close1 = safe_float(item.get("close_position_ratio_1", item.get("close_pos_1", 0)), 0) * 100.0
    close3 = safe_float(item.get("close_position_ratio_3", item.get("close_pos_3", 0)), 0) * 100.0
    close5 = safe_float(item.get("close_position_ratio_5", item.get("close_pos_5", 0)), 0) * 100.0
    bull_streak = int(safe_float(item.get("bullish_streak_5", 0), 0))
    bear_streak = int(safe_float(item.get("bearish_streak_5", 0), 0))
    strong_bulls = int(safe_float(item.get("strong_bullish_count_5", 0), 0))
    pullback = safe_float(item.get("pullback_pct_18", 0), 0)
    recovery = safe_float(item.get("recovery_from_low_pct", 0), 0)
    recovery_speed = safe_float(item.get("recovery_speed_pct", 0), 0)
    pullback_bars = int(safe_float(item.get("pullback_duration_bars", 0), 0))
    comp_score = safe_float(item.get("compression_score", 0), 0)
    re_text = format_rebreakout_stat_text(item, compact=compact)
    hold_score = safe_float(item.get("breakout_hold_score", 0), 0)
    hold_bars = int(safe_float(item.get("hold_near_high_bars", 0), 0))
    quant_label = str(item.get("chart_quant_label", "차트 수치 확인중") or "차트 수치 확인중")
    turnover_keep_5 = int(safe_float(item.get("turnover_keep_bars_5", 0), 0))
    turnover_keep_10 = int(safe_float(item.get("turnover_keep_bars_10", 0), 0))
    turnover_flash = safe_float(item.get("turnover_flash_score", 0), 0)
    current_candle_uninformative = is_chart_current_candle_uninformative(item)
    if current_candle_uninformative:
        candle_1_text = "현재봉 거의 안 움직임"
        close_1_text = "현재봉 진행중"
        wick_1_text = "현재봉 진행중"
        lower_1_text = "현재봉 진행중"
    else:
        candle_1_text = "거의 안 움직임" if abs(body1) < 0.05 else _format_chart_pct_text(body1)
        close_1_text = "횡보" if abs(close1) < 0.05 else _format_chart_pct_text(close1)
        wick_1_text = f"{upper1:.2f}%"
        lower_1_text = f"{lower1:.2f}%"
    candle_3_text = "거의 안 움직임" if abs(body3) < 0.05 else _format_chart_pct_text(body3)
    candle_5_text = "거의 안 움직임" if abs(body5) < 0.05 else _format_chart_pct_text(body5)
    close_3_text = "횡보" if abs(close3) < 0.05 else _format_chart_pct_text(close3)
    close_5_text = "횡보" if abs(close5) < 0.05 else _format_chart_pct_text(close5)
    recent_flat_cluster = _is_chart_flat_cluster(body3, body5, close3, close5, upper5, lower5)
    if recent_flat_cluster:
        candle_3_text = "거의 안 움직임"
        candle_5_text = "거의 안 움직임"
        close_3_text = "횡보"
        close_5_text = "횡보"
    turnover_bits = []
    if turnover_keep_5 > 0 or turnover_keep_10 > 0:
        turnover_bits.append(f"거래대금유지 5분 {turnover_keep_5}봉·10분 {turnover_keep_10}봉")
    if abs(turnover_flash) > 0.01:
        turnover_bits.append(f"돈붙는속도 {format_turnover_flash_label(turnover_flash)} ({turnover_flash:.2f})")
    turnover_tail = (" / " + " / ".join(turnover_bits)) if turnover_bits else ""
    prep_label = str(item.get("prebreakout_label", "") or "").strip()
    prep_score = safe_float(item.get("prebreakout_ready_score", 0), 0)
    prep_hold = int(safe_float(item.get("prebreakout_hold_near_high_bars", 0), 0))
    prep_pullback = safe_float(item.get("prebreakout_pullback_depth_pct", 0), 0)
    prep_retest = int(safe_float(item.get("prebreakout_retest_gap_bars", 999), 999))
    prep_reaccel = safe_float(item.get("prebreakout_volume_reaccel_score", 0), 0)
    prep_bits = []
    if prep_label and prep_label != "돌파 전 준비도 확인중":
        prep_bits.append(f"직전준비 {prep_label}")
    if abs(prep_score) > 0.01:
        prep_bits.append(f"준비점수 {prep_score:.2f}")
    if prep_hold > 0:
        prep_bits.append(f"고점아래체류 {prep_hold}봉")
    if prep_pullback > 0:
        prep_bits.append(f"눌림깊이 {prep_pullback:.2f}%")
    if 0 <= prep_retest < 900:
        prep_bits.append(f"재접근간격 {prep_retest}봉")
    if abs(prep_reaccel) > 0.01:
        prep_bits.append(f"직전거래량재가속 {prep_reaccel:.2f}")
    prep_tail = (" / " + " / ".join(prep_bits)) if prep_bits else ""
    current_label = str(item.get("current_candle_label", "") or "").strip()
    current_pressure = safe_float(item.get("current_candle_pressure_score", 0), 0)
    current_live = safe_float(item.get("current_candle_live_score", 0), 0)
    current_tail = f" / 현재봉 {current_label}(살아남 {current_live:.2f}·밀림 {current_pressure:.2f})" if current_label else ""
    if compact:
        return (
            f"{quant_label} / 몸통1봉 {candle_1_text}·3봉 {candle_3_text}·5봉 {candle_5_text} / "
            f"종가강도 1봉 {close_1_text}·5봉 {close_5_text} / 윗꼬리 1봉 {wick_1_text}·5봉 {upper5:.2f}% / "
            f"회복속도 {recovery_speed:.2f}/봉 / {format_recovery_profile_text(item, compact=True)} / {re_text} / "
            f"상단체류 0.5% {int(safe_float(item.get('hold_near_high_bars_05', 0), 0))}봉·1.0% {int(safe_float(item.get('hold_near_high_bars_10', 0), 0))}봉 / 유지 {hold_score:.2f}{turnover_tail}{prep_tail}{current_tail}"
        )
    return (
        f"{quant_label} / 몸통1봉 {candle_1_text}·3봉 {candle_3_text}·5봉 {candle_5_text} / "
        f"종가강도 1봉 {close_1_text}·3봉 {close_3_text}·5봉 {close_5_text} / "
        f"윗꼬리 1봉 {wick_1_text}·3봉 {upper3:.2f}%·5봉 {upper5:.2f}% / "
        f"아랫꼬리 1봉 {lower_1_text}·3봉 {lower3:.2f}%·5봉 {lower5:.2f}% / "
        f"연속양봉 {bull_streak} / 연속음봉 {bear_streak} / 강한양봉 {strong_bulls}개 / "
        f"눌림 {pullback:.2f}%→회복 {recovery:.2f}%({recovery_speed:.2f}/봉, {pullback_bars}봉) / 압축 {comp_score:.2f} / "
        f"{format_recovery_profile_text(item)} / {re_text} / 상단체류 0.5% {int(safe_float(item.get('hold_near_high_bars_05', 0), 0))}봉·1.0% {int(safe_float(item.get('hold_near_high_bars_10', 0), 0))}봉 / 유지 {hold_score:.2f}({hold_bars}봉){turnover_tail}{prep_tail}{current_tail}"
    )
def format_chart_quant_line(item: dict, short: bool = False) -> str:
    summary = format_chart_quant_summary_text(item, compact=short)
    if not summary:
        return ""
    gap_ctx = get_gap_context_snapshot(item)
    gap_short = safe_float(gap_ctx.get("short_gap_pct", 999), 999)
    gap_30 = safe_float(gap_ctx.get("gap_30m_pct", 999), 999)
    gap_60 = safe_float(gap_ctx.get("gap_60m_pct", 999), 999)
    gap_tail = []
    if 0 <= gap_short < 900:
        gap_tail.append(f"단기 {gap_short:.2f}%")
    if 0 <= gap_30 < 900:
        gap_tail.append(f"30분 {gap_30:.2f}%")
    if 0 <= gap_60 < 900:
        gap_tail.append(f"60분 {gap_60:.2f}%")
    gap_text = " / ".join(gap_tail)
    return "- 차트수치: " + summary + (f" / 거리 {gap_text}" if gap_text else "")
def format_mtf_context_line(item: dict, short: bool = False) -> str:
    ensure_roadmap_context(item)
    htf_gap = safe_float(item.get("htf_gap_pct", 999), 999)
    htf_rise = safe_float(item.get("htf_rise_pct", 0), 0)
    htf_label = str(item.get("htf_setup_label", "4시간봉 확인중") or "4시간봉 확인중")
    daily_gap = safe_float(item.get("daily_gap_pct", 999), 999)
    daily_rise = safe_float(item.get("daily_rise_pct", 0), 0)
    daily_label = str(item.get("daily_setup_label", "일봉 확인중") or "일봉 확인중")
    htf_missing = ("데이터 부족" in htf_label or "확인중" in htf_label or htf_gap >= 900 or safe_float(item.get("htf_high_price", 0), 0) <= 0 or safe_float(item.get("htf_low_price", 0), 0) <= 0)
    daily_missing = ("데이터 부족" in daily_label or "확인중" in daily_label or daily_gap >= 900 or safe_float(item.get("daily_high_price", 0), 0) <= 0 or safe_float(item.get("daily_low_price", 0), 0) <= 0)
    if htf_missing:
        htf_text = "4시간 데이터 확인중" if "데이터 부족" not in htf_label else f"4시간 {htf_label}"
    else:
        htf_text = (f"4시간 {htf_label} (고점거리 {htf_gap:.2f}% / 저점대비 {htf_rise:.2f}%)" if short
                    else f"4시간 {htf_label} (최근4시간 고점거리 {htf_gap:.2f}% / 저점대비 {htf_rise:.2f}%)")
    if daily_missing:
        daily_text = "일봉 데이터 확인중" if "데이터 부족" not in daily_label else f"일봉 {daily_label}"
    else:
        daily_text = (f"일봉 {daily_label} (고점거리 {daily_gap:.2f}% / 저점대비 {daily_rise:.2f}%)" if short
                      else f"일봉 {daily_label} (일봉 고점거리 {daily_gap:.2f}% / 저점대비 {daily_rise:.2f}%)")
    htf_pos = str(item.get("htf_box_position_label", "") or "").strip()
    daily_pos = str(item.get("daily_box_position_label", "") or "").strip()
    rebound_day = int(safe_float(item.get("daily_rebound_day", 0), 0))
    tail = []
    if htf_pos:
        tail.append(htf_pos)
    if daily_pos:
        tail.append(daily_pos)
    if rebound_day > 0:
        tail.append(f"일봉 반등 {rebound_day}일차 추정")
    return f"- 상위봉: {htf_text} / {daily_text}" + (f" / {' / '.join(tail)}" if tail else "")
def init_price_track(ref: dict):
    ref.setdefault("track", {})
    track = ref["track"]
    alert_price = safe_float(ref.get("alert_price", 0))
    alert_ts = safe_float(ref.get("alert_ts", 0))
    track.setdefault("max_price", alert_price)
    track.setdefault("min_price", alert_price)
    track.setdefault("max_up_pct", 0.0)
    track.setdefault("max_down_pct", 0.0)
    track.setdefault("max_ts", alert_ts)
    track.setdefault("min_ts", alert_ts)
    track.setdefault("last_price", alert_price)
    track.setdefault("last_ts", alert_ts)
    track.setdefault("last_update_ts", 0.0)
    track.setdefault("samples", [])
    samples = track.get("samples")
    if not isinstance(samples, list):
        samples = []
        track["samples"] = samples
    if alert_price > 0 and alert_ts > 0 and not samples:
        samples.append({"ts": alert_ts, "price": alert_price})
def trim_price_track_samples(track: dict, keep_after_ts: float):
    samples = track.get("samples")
    if not isinstance(samples, list):
        track["samples"] = []
        return
    kept = []
    for row in samples:
        if not isinstance(row, dict):
            continue
        ts = safe_float(row.get("ts", 0), 0)
        price = safe_float(row.get("price", 0), 0)
        if ts <= 0 or price <= 0:
            continue
        if ts >= keep_after_ts:
            kept.append({"ts": ts, "price": price})
    track["samples"] = kept[-220:]
def update_price_track(ref: dict, price: float, now_ts: float):
    alert_price = safe_float(ref.get("alert_price", 0))
    if alert_price <= 0 or price <= 0:
        return
    init_price_track(ref)
    track = ref["track"]
    if price >= safe_float(track.get("max_price", 0), 0):
        track["max_price"] = price
        track["max_ts"] = now_ts
    if safe_float(track.get("min_price", 0), 0) <= 0 or price <= safe_float(track.get("min_price", 0), 0):
        track["min_price"] = price
        track["min_ts"] = now_ts
    track["last_price"] = price
    track["last_ts"] = now_ts
    track["max_up_pct"] = max(safe_float(track.get("max_up_pct", 0)), ((price - alert_price) / alert_price) * 100.0)
    track["max_down_pct"] = min(safe_float(track.get("max_down_pct", 0)), ((price - alert_price) / alert_price) * 100.0)
    track["last_update_ts"] = now_ts
    samples = track.get("samples")
    if not isinstance(samples, list):
        samples = []
        track["samples"] = samples
    last_sample_ts = safe_float(samples[-1].get("ts", 0), 0) if samples else 0
    if not samples or now_ts - last_sample_ts >= 1.0:
        samples.append({"ts": now_ts, "price": price})
    trim_price_track_samples(track, now_ts - PRICE_TRACK_WINDOW_SEC)
def get_price_track_summary(ref: dict, end_ts: float = None, fallback_price: float = 0.0):
    alert_price = safe_float(ref.get("alert_price", 0), 0)
    alert_ts = safe_float(ref.get("alert_ts", 0), 0)
    track = ref.get("track", {}) if isinstance(ref.get("track"), dict) else {}
    if end_ts is None or end_ts <= 0:
        end_ts = safe_float(track.get("last_ts", alert_ts), alert_ts)
    rows = []
    samples = track.get("samples") if isinstance(track.get("samples"), list) else []
    for row in samples:
        if not isinstance(row, dict):
            continue
        ts = safe_float(row.get("ts", 0), 0)
        price = safe_float(row.get("price", 0), 0)
        if ts < alert_ts or ts > end_ts or price <= 0:
            continue
        rows.append((ts, price))
    if not rows and alert_price > 0 and alert_ts > 0:
        rows.append((alert_ts, alert_price))
    if fallback_price > 0 and (not rows or safe_float(rows[-1][0], 0) < end_ts):
        rows.append((end_ts, fallback_price))
    if not rows:
        base_price = fallback_price if fallback_price > 0 else alert_price
        return {
            "end_ts": end_ts,
            "end_price": base_price,
            "end_up_pct": 0.0,
            "max_price": base_price,
            "min_price": base_price,
            "max_up_pct": 0.0,
            "max_down_pct": 0.0,
            "max_ts": alert_ts,
            "min_ts": alert_ts,
            "sample_count": 0,
            "coverage_sec": 0.0,
            "peak_fade_pct": 0.0,
            "early_5m_up_pct": 0.0,
            "early_10m_up_pct": 0.0,
            "late_start_flag": False,
            "hold_quality_score": 0.0,
            "peak_hold_ratio": 0.0,
            "first_meaningful_move_sec": 0.0,
            "first_positive_move_sec": 0.0,
        }
    max_ts, max_price = max(rows, key=lambda x: x[1])
    min_ts, min_price = min(rows, key=lambda x: x[1])
    end_price = rows[-1][1]
    max_up_pct = ((max_price - alert_price) / alert_price) * 100.0 if alert_price > 0 else 0.0
    max_down_pct = ((min_price - alert_price) / alert_price) * 100.0 if alert_price > 0 else 0.0
    end_up_pct = ((end_price - alert_price) / alert_price) * 100.0 if alert_price > 0 else 0.0
    sample_count = len(rows)
    coverage_sec = max(0.0, safe_float(rows[-1][0], alert_ts) - safe_float(rows[0][0], alert_ts)) if rows else 0.0
    peak_fade_pct = max(0.0, max_up_pct - end_up_pct)
    def _max_up_until(sec_limit: float):
        if alert_price <= 0:
            return 0.0
        cap_ts = alert_ts + sec_limit
        local = [((price - alert_price) / alert_price) * 100.0 for ts, price in rows if ts <= cap_ts]
        return max(local) if local else 0.0
    early_5m_up_pct = _max_up_until(300.0)
    early_10m_up_pct = _max_up_until(600.0)
    first_positive_move_sec = 0.0
    first_meaningful_move_sec = 0.0
    if alert_price > 0:
        for ts, price in rows:
            up_pct = ((price - alert_price) / alert_price) * 100.0
            if first_positive_move_sec <= 0 and up_pct >= 0.30:
                first_positive_move_sec = max(0.0, ts - alert_ts)
            if first_meaningful_move_sec <= 0 and up_pct >= 0.80:
                first_meaningful_move_sec = max(0.0, ts - alert_ts)
            if first_positive_move_sec > 0 and first_meaningful_move_sec > 0:
                break
    late_start_flag = bool(max_up_pct >= 1.20 and early_10m_up_pct < 0.60 and (max_ts - alert_ts) >= 900.0)
    peak_hold_ratio = 0.0
    if max_up_pct > 0:
        peak_hold_ratio = max(0.0, min(1.0, (end_up_pct / max_up_pct)))
    hold_quality_score = (end_up_pct * 0.55) + (peak_hold_ratio * 1.1) - (peak_fade_pct * 0.35) - (abs(min(0.0, max_down_pct)) * 0.15)
    if late_start_flag:
        hold_quality_score -= 0.15
    return {
        "end_ts": end_ts,
        "end_price": end_price,
        "end_up_pct": end_up_pct,
        "max_price": max_price,
        "min_price": min_price,
        "max_up_pct": max_up_pct,
        "max_down_pct": max_down_pct,
        "max_ts": max_ts,
        "min_ts": min_ts,
        "sample_count": sample_count,
        "coverage_sec": coverage_sec,
        "peak_fade_pct": peak_fade_pct,
        "early_5m_up_pct": early_5m_up_pct,
        "early_10m_up_pct": early_10m_up_pct,
        "late_start_flag": late_start_flag,
        "hold_quality_score": hold_quality_score,
        "peak_hold_ratio": peak_hold_ratio,
        "first_meaningful_move_sec": first_meaningful_move_sec,
        "first_positive_move_sec": first_positive_move_sec,
    }
def get_track_quality_text(summary: dict) -> str:
    sample_count = int(safe_float(summary.get("sample_count", 0), 0))
    coverage_sec = safe_float(summary.get("coverage_sec", 0), 0)
    if sample_count >= 4 and coverage_sec >= 60:
        status = "정상"
    else:
        status = "부족"
    return f"- 추적기록: {status} / 수집샘플 {sample_count}개"
def update_active_price_check_refs(now_ts: float = None):
    """내부감시 10분/30분 가격 추적.
    v2.5.219:
    - get_current_price 개별조회로 빠지지 않게 통합 가격 함수만 사용한다.
    - 가격소스(ws/rest_bulk/light_snapshot/api_cache/miss)를 track과 /scan_health에 남긴다.
    """
    now_ts = safe_float(now_ts, time.time())
    active = []
    for ref_id, ref in PRICE_CHECK_REFS.items():
        alert_ts = safe_float(ref.get("alert_ts", 0))
        if alert_ts <= 0 or now_ts - alert_ts > PRICE_TRACK_WINDOW_SEC:
            continue
        active.append((ref_id, ref))
    active.sort(key=lambda x: safe_float(x[1].get("alert_ts", 0)), reverse=True)
    active = active[:20]
    changed = False
    for ref_id, ref in active:
        init_price_track(ref)
        last_update_ts = safe_float(ref.get("track", {}).get("last_update_ts", 0), 0)
        if now_ts - last_update_ts < PRICE_TRACK_UPDATE_SEC:
            continue
        ticker = ref.get("ticker", "")
        price, source, age = get_price_for_tracking_with_source(
            ticker,
            caller="update_active_price_check_refs",
            allow_api_fallback=False,
        )
        try:
            tr = ref.setdefault("track", {})
            tr["last_price_source"] = str(source or "none")
            tr["last_price_source_age"] = safe_float(age, 0)
            tr["last_price_source_ts"] = now_ts
        except Exception:
            pass
        if price <= 0:
            continue
        update_price_track(ref, price, now_ts)
        changed = True
    if changed:
        persist_price_check_state()
def classify_price_check_result_type(summary: dict) -> str:
    best_up_pct = safe_float(summary.get("max_up_pct", 0), 0)
    end_up_pct = safe_float(summary.get("end_up_pct", 0), 0)
    worst_down_pct = safe_float(summary.get("max_down_pct", 0), 0)
    peak_fade_pct = safe_float(summary.get("peak_fade_pct", 0), 0)
    early_5m_up_pct = safe_float(summary.get("early_5m_up_pct", 0), 0)
    hold_quality_score = safe_float(summary.get("hold_quality_score", 0), 0)
    late_start_flag = bool(summary.get("late_start_flag"))
    if best_up_pct >= 2.20 and end_up_pct >= 1.10 and peak_fade_pct <= 1.10 and hold_quality_score >= 0.55:
        return "계속 우상향"
    if early_5m_up_pct >= 0.90 and best_up_pct >= 1.40:
        return "초반 바로 감"
    if late_start_flag and best_up_pct >= 1.50:
        return "늦게 출발"
    if best_up_pct >= 1.80 and peak_fade_pct >= 1.20 and end_up_pct <= 0.40:
        return "한 번 튀고 식음"
    if worst_down_pct <= -1.50 and end_up_pct > 0.20:
        return "눌렸다가 회복"
    if best_up_pct <= 0.80 and end_up_pct <= 0.30:
        return "끝까지 약함"
    if best_up_pct >= 1.00 and end_up_pct >= 0.30:
        return "조금 갔지만 애매"
    return "결과 애매"
def get_price_check_timing_line(summary: dict) -> str:
    first_positive = safe_float(summary.get("first_positive_move_sec", 0), 0)
    first_meaningful = safe_float(summary.get("first_meaningful_move_sec", 0), 0)
    late_start_flag = bool(summary.get("late_start_flag"))
    early_5m_up_pct = safe_float(summary.get("early_5m_up_pct", 0), 0)
    early_10m_up_pct = safe_float(summary.get("early_10m_up_pct", 0), 0)
    first_positive_text = format_elapsed_text(first_positive) if first_positive > 0 else "반응 약함"
    first_meaningful_text = format_elapsed_text(first_meaningful) if first_meaningful > 0 else "확실한 출발 약함"
    late_text = "늦게 출발" if late_start_flag else "초반 반응"
    return (
        f"- 결과구조: {classify_price_check_result_type(summary)} / "
        f"초반5분 {early_5m_up_pct:+.2f}% / 초반10분 {early_10m_up_pct:+.2f}% / "
        f"첫 반응 {first_positive_text} / 의미 있는 출발 {first_meaningful_text} / {late_text}"
    )
def get_price_check_hold_line(summary: dict) -> str:
    peak_fade_pct = safe_float(summary.get("peak_fade_pct", 0), 0)
    peak_hold_ratio = safe_float(summary.get("peak_hold_ratio", 0), 0) * 100.0
    hold_quality_score = safe_float(summary.get("hold_quality_score", 0), 0)
    max_up_pct = safe_float(summary.get("max_up_pct", 0), 0)
    end_up_pct = safe_float(summary.get("end_up_pct", 0), 0)
    return (
        f"- 유지력: 최고뒤 밀림 {peak_fade_pct:.2f}% / 최고대비 유지 {peak_hold_ratio:.0f}% / "
        f"유지점수 {hold_quality_score:.2f} / 최고 {max_up_pct:+.2f}% / 끝 {end_up_pct:+.2f}%"
    )
def get_price_check_validation_line(ref: dict, summary: dict) -> str:
    source_label = str(ref.get("source_label", "") or "")
    strategy_label = str(ref.get("strategy_label", "") or "")
    judgement_text = str(ref.get("judgement_text", "") or "")
    source_text = f"{source_label} {strategy_label} {judgement_text}"
    result_type = classify_price_check_result_type(summary)
    best_up_pct = safe_float(summary.get("max_up_pct", 0), 0)
    end_up_pct = safe_float(summary.get("end_up_pct", 0), 0)
    if any(x in source_text for x in ["지금 볼", "초반 자리", "초반 선점형"]):
        if result_type in {"초반 바로 감", "계속 우상향"}:
            note = "초반 판단이 대체로 맞았음"
        elif result_type == "늦게 출발":
            note = "방향은 맞았지만 출발은 늦었음"
        else:
            note = "초반 판단치고는 힘이 약했음"
    elif any(x in source_text for x in ["미리 볼", "막 뜨기 직전형", "막 뜨기 직전"]):
        if best_up_pct >= 2.00 and end_up_pct >= 0.80:
            note = "미리 보기보단 승격이 더 빨라도 됐음"
        elif result_type in {"끝까지 약함", "결과 애매", "조금 갔지만 애매"}:
            note = "미리 보기 판단은 무난했음"
        else:
            note = "미리 보기 방향은 대체로 맞았음"
    else:
        if end_up_pct >= 1.00:
            note = "후보 방향은 대체로 맞았음"
        elif end_up_pct <= -0.50:
            note = "보수적으로 본 건 맞았음"
        else:
            note = "검증 결과는 보통 수준"
    return f"- 판정검증: {note}"
def get_price_check_note(ref: dict, current_price: float, summary: dict = None) -> str:
    alert_price = safe_float(ref.get("alert_price", 0))
    if alert_price <= 0 or current_price <= 0:
        return "판단: 비교 불가"
    if summary is None:
        end_pct = ((current_price - alert_price) / alert_price) * 100.0
        max_up_pct = end_pct
        max_down_pct = min(0.0, end_pct)
        peak_fade_pct = 0.0
        early_5m_up_pct = end_pct
        hold_quality_score = 0.0
    else:
        end_pct = safe_float(summary.get("end_up_pct", 0), 0)
        max_up_pct = safe_float(summary.get("max_up_pct", 0), 0)
        max_down_pct = safe_float(summary.get("max_down_pct", 0), 0)
        peak_fade_pct = safe_float(summary.get("peak_fade_pct", 0), 0)
        early_5m_up_pct = safe_float(summary.get("early_5m_up_pct", 0), 0)
        hold_quality_score = safe_float(summary.get("hold_quality_score", 0), 0)
    result_type = classify_price_check_result_type(summary or {})
    if result_type == "계속 우상향":
        return "판단: 좋은 알림. 초반 판단도 맞고 유지력도 괜찮았음"
    if result_type == "초반 바로 감":
        return "판단: 초반 알림 성공. 이런 건 놓치면 안 되는 표본"
    if result_type == "늦게 출발":
        return "판단: 방향은 맞았지만 출발이 늦음. 초입 선점형으로는 아쉬움"
    if result_type == "한 번 튀고 식음":
        return "판단: 가짜 상승. 순간 매도 말고 다시 사기엔 별로"
    if result_type == "눌렸다가 회복":
        return "판단: 중간 흔들림 후 회복. 재출발형 표본으로 따로 볼 가치 있음"
    if max_down_pct <= -2.0 or end_pct <= -2.0:
        return "판단: 실패 후보. 알림 뒤 바로 무너져서 줄여야 할 유형"
    if max_up_pct >= 2.50 and end_pct < 0.50 and peak_fade_pct >= 1.80:
        return "판단: 최고가는 있었지만 대부분 반납. 늦게 잡으면 손익비 별로"
    if max_up_pct >= 1.50 and end_pct >= 0.30:
        return "판단: 조금 먹을 수는 있었지만 강한 표본은 아님"
    if early_5m_up_pct < 0.30 and hold_quality_score < 0.20:
        return "판단: 안 보내도 되는 약한 후보에 가까움"
    if end_pct <= -0.5:
        return "판단: 지금 사기 별로. 알림 뒤 밀림"
    return "판단: 애매. 큰 수익 후보로 보긴 부족"
def format_offset_text(base_ts: float, event_ts: float) -> str:
    base_ts = safe_float(base_ts, 0)
    event_ts = safe_float(event_ts, 0)
    if base_ts <= 0 or event_ts <= 0:
        return "--"
    diff = max(0, int(event_ts - base_ts))
    if diff < 60:
        return f"{diff}초 뒤"
    m, s = divmod(diff, 60)
    return f"{m}분 {s}초 뒤"
def cleanup_price_check_refs(now_ts: float = None):
    now_ts = safe_float(now_ts, time.time())
    changed = False
    expired = []
    for ref_id, data in PRICE_CHECK_REFS.items():
        saved_at = safe_float(data.get("alert_ts", 0))
        if saved_at <= 0 or now_ts - saved_at > PRICE_CHECK_REF_TTL_SEC:
            expired.append(ref_id)
    for ref_id in expired:
        PRICE_CHECK_REFS.pop(ref_id, None)
        changed = True
    if len(PRICE_CHECK_REFS) > PRICE_CHECK_REF_MAX:
        ordered = sorted(PRICE_CHECK_REFS.items(), key=lambda x: safe_float(x[1].get("alert_ts", 0)))
        drop_count = len(PRICE_CHECK_REFS) - PRICE_CHECK_REF_MAX
        for ref_id, _ in ordered[:drop_count]:
            PRICE_CHECK_REFS.pop(ref_id, None)
            changed = True
    expired_sched = []
    for key, sched in PRICE_CHECK_SCHEDULED.items():
        if isinstance(sched, dict):
            target_ts = safe_float(sched.get("target_ts", 0), 0)
            ref_id = (sched.get("ref_id") or key.split(":", 1)[0]).strip()
        else:
            target_ts = safe_float(sched, 0)
            ref_id = key.split(":", 1)[0]
        if target_ts <= 0 or now_ts - target_ts > 1800 or ref_id not in PRICE_CHECK_REFS:
            expired_sched.append(key)
    for key in expired_sched:
        PRICE_CHECK_SCHEDULED.pop(key, None)
        changed = True
    if changed:
        persist_price_check_state()
def has_pending_30m_check_for_ticker(ticker: str, now_ts: float = None) -> bool:
    now_ts = safe_float(now_ts, time.time())
    if not ticker:
        return False
    for sched in PRICE_CHECK_SCHEDULED.values():
        if not isinstance(sched, dict):
            continue
        if int(safe_float(sched.get("target_min", 0), 0)) < 30:
            continue
        target_ts = safe_float(sched.get("target_ts", 0), 0)
        if target_ts <= now_ts:
            continue
        ref_id = str(sched.get("ref_id", "") or "").strip()
        ref = PRICE_CHECK_REFS.get(ref_id, {}) if ref_id else {}
        if str(ref.get("ticker", "") or "").upper() == str(ticker).upper():
            return True
    return False
def make_price_check_ref(item: dict, alert_type: str = "new", source_label: str = "", judgement_text: str = "") -> str:
    now_ts = time.time()
    cleanup_price_check_refs(now_ts)
    ticker = item.get("ticker", "?")
    alert_price = safe_float(item.get("current_price", item.get("price", 0)))
    ref_id = f"{ticker}_{int(now_ts * 1000)}"[-40:]
    pre_alert_snapshot = ensure_pre_alert_snapshot(item)
    PRICE_CHECK_REFS[ref_id] = {
        "ticker": ticker,
        "alert_price": alert_price,
        "alert_ts": now_ts,
        "strategy_label": item.get("strategy_label", ""),
        "alert_type": alert_type,
        "source_label": source_label or item.get("strategy_label", ""),
        "judgement_text": judgement_text or get_watch_judgement_text(item),
        "pre_alert_snapshot": pre_alert_snapshot,
        "root_message_id": None,
    }
    init_price_track(PRICE_CHECK_REFS[ref_id])
    update_price_track(PRICE_CHECK_REFS[ref_id], alert_price, now_ts)
    persist_price_check_state()
    return ref_id
def unpack_recent_entry(entry):
    if len(entry) >= 4:
        item, alert_type, reason_text, header = entry[0], entry[1], entry[2], entry[3]
    else:
        item, alert_type, reason_text = entry[0], entry[1], entry[2]
        header = ""
    return item, alert_type, reason_text, header
def get_bithumb_chart_url(ticker: str, market: str = "KRW") -> str:
    ticker = str(ticker or "").upper().strip()
    market = str(market or "KRW").upper().strip()
    return f"https://m.bithumb.com/react/trade/chart/{ticker}-{market}"
def build_price_check_markup(prepared_entries, section_key_override: str = ""):
    if not prepared_entries:
        return None
    rows = []
    for idx, prepared in enumerate(prepared_entries, start=1):
        item = prepared["item"]
        ref_id = prepared["ref_id"]
        ticker = item.get("ticker", "?")
        judgement = get_watch_judgement_text(item)
        caution = get_watch_caution_text(item)
        section_key = section_key_override or get_watch_display_group(item, judgement, caution)
        rows.append([
            InlineKeyboardButton(f"{bold_number_badge(idx)} {ticker} 빗썸 열기", url=get_bithumb_chart_url(ticker)),
        ])
        if section_key in {"entry", "recovery", "early", "restart", "live"}:
            rows.append([
                InlineKeyboardButton(f"{circled_number(idx)} 지금", callback_data=f"pc:{ref_id}:now"),
                InlineKeyboardButton("15분뒤", callback_data=f"pc:{ref_id}:15"),
                InlineKeyboardButton("30분뒤", callback_data=f"pc:{ref_id}:30"),
            ])
        else:
            rows.append([
                InlineKeyboardButton("30분뒤", callback_data=f"pc:{ref_id}:30"),
            ])
    return InlineKeyboardMarkup(rows)
def build_price_check_brief_lines(ref: dict, current_price: float, now_ts: float, target_min: int = 0, summary: dict = None, target_ts: float = None):
    """v2.5.167: 자동 15/30분 확인 메시지는 짧게 보낸다.
    자세한 검증은 /review_dump에 모으고, 자동 알림은 핵심 결과만 보여준다.
    """
    ticker = ref.get("ticker", "?")
    alert_price = safe_float(ref.get("alert_price", 0), 0)
    alert_ts = safe_float(ref.get("alert_ts", 0), 0)
    if target_min > 0:
        target_ts = safe_float(target_ts, alert_ts + target_min * 60)
        effective_ts = target_ts
    else:
        effective_ts = now_ts
    if summary is None:
        summary = get_price_track_summary(ref, effective_ts, fallback_price=current_price)
    end_price = safe_float(summary.get("end_price", current_price), current_price)
    result_type = classify_price_check_result_type(summary or {})
    max_up = safe_float(summary.get("max_up_pct", 0), 0)
    end_up = safe_float(summary.get("end_up_pct", 0), 0)
    worst = safe_float(summary.get("max_down_pct", 0), 0)
    note = get_price_check_note(ref, end_price, summary=summary)
    judgement_text = str(ref.get("judgement_text", "") or "").strip()
    source_label = str(ref.get("source_label", "") or "").strip()
    title = f"⏱ 《{ticker}》 {target_min}분 확인" if target_min > 0 else f"💰 《{ticker}》 지금 확인"
    lines = [title]
    if source_label:
        lines.append(f"- 종류: {source_label}")
    if judgement_text:
        lines.append(f"- 최초판단: {judgement_text[:120]}")
    lines += [
        f"- 가격: 알림 {fmt_price(alert_price)} → 현재 {fmt_price(end_price)} ({end_up:+.2f}%)",
        f"- 결과: 최고 {max_up:+.2f}% / 최저 {worst:+.2f}% / 유형 {result_type}",
        f"- 한줄: {note.replace('판단: ', '')}",
        f"- 시각: 알림 {format_hms(alert_ts)} / 확인 {format_hms(effective_ts)} / 경과 {format_elapsed_text(max(0.0, effective_ts - alert_ts))}",
        "- 자세한 수치/원인: /review_dump",
    ]
    return lines
def build_price_check_lines(ref: dict, current_price: float, now_ts: float, target_min: int = 0, summary: dict = None, target_ts: float = None):
    ticker = ref.get("ticker", "?")
    alert_price = safe_float(ref.get("alert_price", 0))
    alert_ts = safe_float(ref.get("alert_ts", 0))
    source_label = (ref.get("source_label") or "").strip()
    strategy_label = (ref.get("strategy_label") or "").strip()
    judgement_text = (ref.get("judgement_text") or "").strip()
    snap = ref.get("pre_alert_snapshot", {}) if isinstance(ref.get("pre_alert_snapshot"), dict) else {}
    if target_min > 0:
        target_ts = safe_float(target_ts, alert_ts + target_min * 60)
        effective_ts = target_ts
    else:
        effective_ts = now_ts
    if summary is None:
        summary = get_price_track_summary(ref, effective_ts, fallback_price=current_price)
    end_price = safe_float(summary.get("end_price", current_price), current_price)
    change_pct = ((end_price - alert_price) / alert_price * 100.0) if alert_price > 0 else 0.0
    elapsed_sec = max(0.0, effective_ts - alert_ts)
    if target_min <= 0:
        title = f"💰 {bold_ticker_text(ticker)} 지금 확인"
    else:
        title = f"⏱ {bold_ticker_text(ticker)} {target_min}분 확인"
    lines = [title, ""]
    if source_label:
        lines.append(f"- 알림종류: {source_label}")
    if strategy_label:
        lines.append(f"- 전략: {strategy_label}")
    if judgement_text:
        lines.append(f"- 한눈판단: {judgement_text}")
    if snap:
        lines.append(
            f"- 직전흐름(최근30분 기준): 5분 {safe_float(snap.get('chg_5m', 0)):+.2f}% / "
            f"30분 {safe_float(snap.get('chg_30m', 0)):+.2f}% / "
            f"저점대비 {safe_float(snap.get('from_30m_low_pct', 0)):+.2f}% / "
            f"{format_recent_high_gap_text(safe_float(snap.get('below_30m_high_pct', 0), 0))}"
        )
        price_ctx_line = format_recent_30m_price_context(snap, current_price=end_price)
        if price_ctx_line:
            lines.append(price_ctx_line)
    lines.append("")
    lines.extend([
        f"- 알림가: {fmt_price(alert_price)}",
        f"- 현재가: {fmt_price(end_price)}",
        f"- 변화: {change_pct:+.2f}%",
    ])
    max_price = safe_float(summary.get("max_price", 0), 0)
    min_price = safe_float(summary.get("min_price", 0), 0)
    if max_price > 0:
        lines.append(f"- 중간 최고가: {fmt_price(max_price)} ({safe_float(summary.get('max_up_pct', 0), 0):+.2f}%) / {format_offset_text(alert_ts, safe_float(summary.get('max_ts', 0), alert_ts))}")
    if min_price > 0:
        lines.append(f"- 중간 최저가: {fmt_price(min_price)} ({safe_float(summary.get('max_down_pct', 0), 0):+.2f}%) / {format_offset_text(alert_ts, safe_float(summary.get('min_ts', 0), alert_ts))}")
    lines.append(get_track_quality_text(summary))
    lines.append(get_price_check_timing_line(summary))
    lines.append(get_price_check_hold_line(summary))
    lines.append(get_price_check_validation_line(ref, summary))
    lines.extend([
        "",
        f"- 알림시각: {format_hms(alert_ts)}",
        f"- 확인시각: {format_hms(effective_ts)}",
        f"- 지난시간: {format_elapsed_text(elapsed_sec)}",
        "",
        get_price_check_note(ref, end_price, summary=summary),
    ])
    return lines
def send_price_check_result(chat_id, ref: dict, target_min: int = 0, now_ts: float = None):
    ticker = ref.get("ticker", "?")
    now_ts = safe_float(now_ts, time.time())
    current_price, price_source, price_age = get_price_for_tracking_with_source(
        ticker,
        caller="send_price_check_result",
        allow_api_fallback=False,
    )
    if current_price <= 0:
        try:
            bot.send_message(chat_id=chat_id, text=f"⚠️ {ticker} 현재가를 불러오지 못해서 비교를 못 했어.")
        except Exception as e:
            print(f"[텔레그램 지연 비교 오류] {e}")
        return False
    try:
        try:
            tr = ref.setdefault("track", {})
            tr["last_price_source"] = str(price_source or "unknown")
            tr["last_price_source_age"] = safe_float(price_age, 0)
            tr["last_price_source_ts"] = now_ts
        except Exception:
            pass
        update_price_track(ref, current_price, now_ts)
        if target_min > 0:
            target_ts = safe_float(ref.get("alert_ts", 0)) + target_min * 60
            summary = get_price_track_summary(ref, target_ts, fallback_price=0.0)
            if safe_float(summary.get("end_price", 0), 0) <= 0:
                summary = get_price_track_summary(ref, target_ts, fallback_price=current_price)
            msg = "\n".join(build_price_check_brief_lines(ref, current_price, now_ts, target_min=target_min, summary=summary, target_ts=target_ts))
        else:
            summary = get_price_track_summary(ref, now_ts, fallback_price=current_price)
            msg = "\n".join(build_price_check_lines(ref, current_price, now_ts, target_min=target_min, summary=summary, target_ts=now_ts))
        send_to_chat_chunks(
            chat_id,
            msg,
            reply_to_message_id=ref.get("root_message_id"),
            limit=TG_MESSAGE_SOFT_LIMIT,
        )
        persist_price_check_state()
        return True
    except Exception as e:
        print(f"[텔레그램 지연 비교 오류] {e}")
        return False
def process_scheduled_price_checks(now_ts: float = None):
    now_ts = safe_float(now_ts, time.time())
    due_keys = []
    for key, sched in list(PRICE_CHECK_SCHEDULED.items()):
        if not isinstance(sched, dict):
            continue
        target_ts = safe_float(sched.get("target_ts", 0), 0)
        if target_ts > 0 and now_ts >= target_ts:
            due_keys.append(key)
    for key in due_keys:
        sched = PRICE_CHECK_SCHEDULED.pop(key, None)
        persist_price_check_state()
        if not isinstance(sched, dict):
            continue
        ref_id = (sched.get("ref_id") or "").strip()
        ref = PRICE_CHECK_REFS.get(ref_id)
        if not ref:
            continue
        chat_id = sched.get("chat_id", CHAT_ID)
        target_min = int(safe_float(sched.get("target_min", 0), 0))
        send_price_check_result(chat_id, ref, target_min=target_min, now_ts=now_ts)
def cleanup_recent_candidate_alerts(now_ts: float = None):
    now_ts = safe_float(now_ts, time.time())
    fresh = []
    for row in RECENT_CANDIDATE_ALERTS:
        if not isinstance(row, dict):
            continue
        saved_at = safe_float(row.get("saved_at", 0))
        if saved_at <= 0:
            continue
        if now_ts - saved_at > RECENT_CANDIDATE_TTL_SEC:
            continue
        fresh.append(row)
    del RECENT_CANDIDATE_ALERTS[:]
    RECENT_CANDIDATE_ALERTS.extend(fresh[-RECENT_CANDIDATE_MAX:])
    persist_recent_candidate_alerts()
def save_recent_candidate_alerts(entries, header: str = ""):
    if not entries:
        return
    now_ts = time.time()
    cleanup_recent_candidate_alerts(now_ts)
    for item, alert_type, reason_text in entries:
        try:
            RECENT_CANDIDATE_ALERTS.append({
                "saved_at": now_ts,
                "header": header or "",
                "item": dict(item),
                "alert_type": alert_type or "new",
                "reason_text": reason_text or "",
            })
        except Exception:
            continue
    cleanup_recent_candidate_alerts(now_ts)
def prepare_watch_entries(entries):
    prepared = []
    for entry in entries:
        item, alert_type, reason_text, header = unpack_recent_entry(entry)
        ensure_pre_alert_snapshot(item)
        ref_id = make_price_check_ref(
            item,
            alert_type=alert_type,
            source_label=header or item.get("strategy_label", ""),
            judgement_text=get_watch_judgement_text(item),
        )
        prepared.append({
            "entry": entry,
            "item": item,
            "alert_type": alert_type,
            "reason_text": reason_text,
            "header": header,
            "ref_id": ref_id,
        })
    return prepared
def send_watch_alert_bundle(header: str, entries, section_key: str = ""):
    if not entries:
        return
    filtered_entries = []
    now_ts = time.time()
    for entry in list(entries or []):
        item = entry[0] if isinstance(entry, (list, tuple)) and entry else entry
        if not isinstance(item, dict):
            continue
        block_reason = get_user_alert_block_reason(item, section_key)
        if block_reason:
            try:
                register_missed_review_candidate(item, now_ts=now_ts, seen_market=True, seen_shortlist=True, seen_signal=True, alert_sent=False, alert_section=section_key or 'blocked', quality_block_reason=f"사용자 알림 직전 제외: {block_reason}")
                append_reverse_trace(item, stage='alert_blocked', extra_reason=f"사용자 알림 직전 제외: {block_reason}", now_ts=now_ts)
            except Exception:
                pass
            continue
        filtered_entries.append(entry)
    if not filtered_entries:
        return
    entries = filtered_entries
    prepared = prepare_watch_entries(entries)
    save_recent_candidate_alerts(entries, header=header)
    body = []
    for idx, prepared_entry in enumerate(prepared, start=1):
        item = prepared_entry["item"]
        alert_type = prepared_entry["alert_type"]
        reason_text = prepared_entry["reason_text"]
        body.append(
            format_watch_alert_line(
                item,
                order=idx,
                alert_type=alert_type,
                reason_text=reason_text,
                section_override=section_key,
            )
        )
    markup = build_price_check_markup(prepared, section_key_override=section_key)
    sent = send(header + "\n\n" + "\n\n".join(body), reply_markup=markup)
    if sent and getattr(sent, "message_id", None):
        for prepared_entry in prepared:
            PRICE_CHECK_REFS[prepared_entry["ref_id"]]["root_message_id"] = sent.message_id
        persist_price_check_state()
