def _paper_classify_for_register_v258(row: dict):
    """v2.5.259 override: strict/loose를 분리하고 signal 판단과 paper 타입을 맞춘다."""
    cls = _signal_v257_classify(row) if '_signal_v257_classify' in globals() else _signal_v256_classify(row)
    cls = dict(cls or {})
    grade = str(cls.get("grade", "") or "").upper()
    entry_rule = _paper_v259_signal_entry_rule(cls)
    cls["paper_entry_rule_v259"] = entry_rule
    cls["paper_original_grade"] = grade
    strict_ok, strict_reason = _paper_v259_strict_gate(cls)
    if strict_ok:
        PAPER_V259_STATS["strict_registered"] = int(safe_float(PAPER_V259_STATS.get("strict_registered", 0), 0)) + 1
        PAPER_V259_STATS["last_note"] = f"strict {cls.get('ticker','?')}/{entry_rule}"
        return True, "strict_signal", strict_reason, cls
    loose_ok, loose_reason = _paper_v259_loose_gate(cls) if PAPER_LOOSE_TEST_ON else (False, "loose off")
    if loose_ok:
        PAPER_V259_STATS["loose_registered"] = int(safe_float(PAPER_V259_STATS.get("loose_registered", 0), 0)) + 1
        PAPER_V259_STATS["last_note"] = f"loose {cls.get('ticker','?')}/{entry_rule}"
        if entry_rule == "observe":
            entry_rule = "now"
            cls["paper_entry_rule_v259"] = "now"
            cls["paper_original_grade"] = grade
            cls["grade"] = "BUY_OK"
            cls["decision"] = "모의검증 진입"
        return True, "loose_threshold_test", loose_reason, cls
    PAPER_V259_STATS["blocked_weak"] = int(safe_float(PAPER_V259_STATS.get("blocked_weak", 0), 0)) + 1
    PAPER_V259_STATS["last_note"] = f"blocked {cls.get('ticker','?')}/{strict_reason}/{loose_reason}"
    return False, "blocked_weak", f"{strict_reason} / {loose_reason}", cls
