        if _paper_v259_is_thin_money(cls) or money < 50_000_000: _paper_v260_inc("strict_blocked", "strict 돈 부족"); return False, "strict 대금 부족/돈얇음"
        if weak_candle or "밀림" in candle or "위꼬리" in candle or "매도 우세" in reasons or "매도우세" in money_sustain or "반짝" in money_sustain or "식는" in money_sustain: _paper_v260_inc("strict_blocked", "strict 현재봉/돈흐름 약함"); return False, "현재봉/체결 약함"
        if trade_count < PAPER_V260_STRICT_MIN_TRADE: _paper_v260_inc("strict_blocked", "strict 체결수 부족"); return False, "60초 체결 부족"
