def _v319_read_file_state_quick(path: str) -> str:
    """파일 내용을 읽지 않고 존재/크기만 본다. route_doctor에서 파일 lock/대형 JSON read를 피한다."""
    try:
        if not path:
            return "경로 없음"
        if not os.path.exists(path):
            return "없음(초기상태 가능)"
        size = os.path.getsize(path)
        if size >= 1024 * 1024:
            return f"있음 {size/1024/1024:.1f}MB"
        return f"있음 {size/1024:.1f}KB"
    except Exception as e:
        return f"확인실패 {e.__class__.__name__}"
