def _v322_reason_is_soft_profit(reason: str) -> bool:
    r = str(reason or "").lower()
    soft_words = ["protect", "profit", "신호약화", "보호", "익절", "weakening"]
    hard_words = ["hard", "stop_loss", "fast_cut", "손절", "v322_common", "v322_weak", "v322_strong"]
    return any(w in r for w in soft_words) and not any(w in r for w in hard_words)
def _paper_close_position_v258(pos_id: str, pos: dict, price: float, reason: str, now_ts: float = None):
    """v322: 강한놓침 눌림/복귀 라인은 작은 보호청산을 최대 2회 보류해 1%대 수익을 노린다."""
    now_ts = now_ts or _v322_now()
    try:
        p = dict(pos or {})
        pnl = _v322_current_pnl(p, safe_float(price, 0))
        best = _v322_max_profit(p, pnl)
        strong = _v322_is_strong_line(p)
        defer_count = int(safe_float(p.get("v322_defer_close_count", 0), 0))
        if strong and _v322_reason_is_soft_profit(reason) and pnl >= V322_STRONG_DEFER_MIN_PNL and best < V322_STRONG_TARGET_BEFORE_EASY_CLOSE and defer_count < V322_STRONG_DEFER_MAX_COUNT:
            with PAPER_STATE_LOCK:
                if pos_id in paper_positions and isinstance(paper_positions.get(pos_id), dict):
                    paper_positions[pos_id]["v322_defer_close_count"] = defer_count + 1
                    paper_positions[pos_id]["v322_defer_close_reason"] = str(reason)[:120]
                    paper_positions[pos_id]["v322_defer_close_ts"] = now_ts
                    paper_positions[pos_id]["v322_target_before_easy_close"] = V322_STRONG_TARGET_BEFORE_EASY_CLOSE
                    paper_positions[pos_id]["v322_breakeven_guard"] = V322_STRONG_BREAKEVEN_FLOOR
                    save_paper_state_v258()
            _v322_inc("strong_close_deferred", f"강한라인 작은청산 보류 {p.get('ticker','?')}/{pnl:+.2f}% 최고{best:+.2f}%")
            return None
    except Exception as e:
        try: append_runtime_error_log("v322_close_defer", str(e), exc=e, include_traceback=False)
        except Exception: pass
    if callable(_BASE_PAPER_CLOSE_POSITION_V322):
        return _BASE_PAPER_CLOSE_POSITION_V322(pos_id, pos, price, reason, now_ts)
    return None
