def _v326_blob(obj) -> str:
    try:
        if not isinstance(obj, dict):
            return str(obj or "").lower()
        keys = [
            "lane", "easy_lane", "route", "watch_route", "trigger", "source", "mode", "paper_type",
            "entry_rule", "register_reason", "signal_decision", "decision", "final_decision",
            "final_class", "final_type", "pattern_tag", "record_type", "trace_reason", "rank_reason",
            "close_reason", "cancel_reason", "v321_force_connected", "v320_force_connected",
            "v324_entry_raw_hint", "raw_hint", "v326_route_class",
        ]
        parts = []
        for k in keys:
            v = obj.get(k)
            if v not in (None, "", [], {}):
                parts.append(str(v))
        return " / ".join(parts).lower()[:2500]
    except Exception:
        return ""
def _v326_score(row: dict) -> float:
    try:
        for k in ["score", "signal_score", "quality_score", "entry_score"]:
            v = safe_float((row or {}).get(k, 0), 0)
            if v:
                return v
    except Exception:
        pass
    return 0.0
def _v326_is_weak_breakout_reentry_row(row: dict, mode: str = "") -> bool:
    """POLA/XPLA처럼 약한 돌파형을 바로 진입시키지 않고 재확인으로 보내기 위한 좁은 판정."""
    try:
        r = row if isinstance(row, dict) else {}
        b = _v326_blob(r)
        mode_txt = str(mode or "").lower()
        if mode_txt and mode_txt != "breakout":
            return False
        route_break = ("breakout" in b) or ("돌파" in b) or ("복귀감시" in b) or (mode_txt == "breakout") or ("strong_return" in b)
        if not route_break:
            return False
        score = _v326_score(r)
        weak_score = bool(0 < score <= 3.30)
        weak_text = any(w in b for w in [
            "반짝형", "반짝형 관찰", "정밀검토 대기", "바로 매수 신호 아님", "복기용",
            "막판 밀림 강함", "현재봉 막판 밀림", "돈이 계속 붙는 힘 0", "고점 다시도전 힘 0", "유지 0.00",
        ])
        strong_score = bool(score >= 4.00)
        return bool((weak_score or weak_text) and not strong_score)
    except Exception:
        return False
