def _v327_route_class(obj) -> str:
    """상용급 기준의 중앙 route 표준분류. 분류 실패해도 unknown으로 빠지고 로직은 멈추지 않는다."""
    try:
        b = _v327_blob(obj)
        if not b.strip():
            _v327_inc("route_unknown", "빈 route")
            return "unknown"
        if (
            "cancel_reentry_forced_v313_눌림" in b or "cancel_reentry_forced_v313_p" in b or
            "strong_reentry_pullback" in b or "강한놓침 눌림" in b or "눌림감시" in b or
            ("cancel_reentry" in b and "pullback" in b) or ("cancel_reentry" in b and "눌림" in b)
        ):
            _v327_inc("route_forced")
            return "strong_reentry_pullback"
        if (
            "cancel_reentry_forced_v313_돌파" in b or "cancel_reentry_forced_v313_b" in b or
            "strong_return_v314" in b or "strong_reentry_breakout" in b or "강한놓침 복귀" in b or
            "복귀감시" in b or ("cancel_reentry" in b and "breakout" in b) or
            ("cancel_reentry" in b and "돌파" in b) or ("cancel_reentry" in b and "복귀" in b)
        ):
            _v327_inc("route_forced")
            return "strong_reentry_breakout"
        if "strict_signal_common_prepare" in b or "공통확인" in b or ("common" in b and "prepare" in b):
            _v327_inc("route_forced")
            return "strict_common"
        if "strict_signal" in b or "실전급" in b:
            _v327_inc("route_forced")
            return "strict_signal"
        if "v275_order_flow_prepare" in b or "체결흐름" in b or "order_flow" in b:
            _v327_inc("route_forced")
            return "order_flow_prepare"
        if "v274_preview_bridge_prepare" in b or "관심 후보" in b or "interest" in b or "preview_bridge" in b:
            _v327_inc("route_forced")
            return "interest_prepare"
        if "매도우세 재감시" in b or "sell_heavy" in b:
            _v327_inc("route_forced")
            return "sell_heavy_rewatch"
        _v327_inc("route_unknown", b[:120])
        return "unknown"
    except Exception as e:
        try: append_runtime_error_log("v327_route_class", str(e), exc=e, include_traceback=False)
        except Exception: pass
        _v327_inc("route_error")
        return "unknown"
def _v327_is_strong_class(cls: str) -> bool:
    return str(cls or "") in {"strong_reentry_pullback", "strong_reentry_breakout"}
def _v327_is_common_class(cls: str) -> bool:
    return str(cls or "") == "strict_common"
def _v327_is_weak_class(cls: str) -> bool:
    return str(cls or "") in {"interest_prepare", "strict_signal", "order_flow_prepare", "sell_heavy_rewatch"}
