def paper_register_candidate_v258(row: dict, trigger: str = "auto") -> bool:
    """v329: paper 등록 직전에 의심 차트는 해당 코인만 REST 1분봉 복구 후 재판단한다."""
    row = row if isinstance(row, dict) else {}
    try:
        q0 = _BASE_V328_CHART_QUALITY_V329(row) if callable(_BASE_V328_CHART_QUALITY_V329) else _v328_chart_quality(row)
        if _v329_need_repair(row, q0):
            q = _v329_repair_chart_quality(row, q0, reason="paper_register")
            if q.get("ok"):
                _v329_apply_repair_to_row(row, q)
                _v329_inc("paper_precheck_repair", f"paper직전 차트복구 {str(row.get('ticker','?')).upper()}")
    except Exception as e:
        try: append_runtime_error_log("v329_paper_pre_repair", str(e), exc=e, include_traceback=False)
        except Exception: pass
    try:
        block, why, q = _v328_should_block_paper_entry(row)
        if block:
            _v329_inc("repair_blocked_fail", f"paper등록 차단 {str(row.get('ticker','?')).upper()}/{q.get('code')}")
            try:
                append_runtime_event_log("v329_chart_entry_block", "차트복구 후에도 paper 진입 차단", extra={"ticker": str(row.get("ticker", "?")), "why": why, "quality": q})
            except Exception:
                pass
            return False
    except Exception:
        pass
    return _BASE_PAPER_REGISTER_V329(row, trigger=trigger) if callable(_BASE_PAPER_REGISTER_V329) else False
