def _v330_inc(key: str, note: str = ""):
    try:
        if key in V330_STATS:
            V330_STATS[key] = int(safe_float(V330_STATS.get(key, 0), 0)) + 1
        if note:
            V330_STATS["last_note"] = str(note)[:240]
    except Exception:
        pass
def _v330_fail(code: str, ticker: str = "", note: str = ""):
    try:
        code = str(code or "unknown")[:60]
        d = globals().setdefault("V330_FAIL_REASONS", {})
        if not isinstance(d, dict):
            d = {}
        d[code] = int(safe_float(d.get(code, 0), 0)) + 1
        globals()["V330_FAIL_REASONS"] = d
        _v330_inc("repair_fail", f"{ticker} {code} {note}".strip())
    except Exception:
        pass
def _v330_reason_is_critical(reason: str) -> bool:
    r = str(reason or "").lower()
    return any(x in r for x in ["paper", "entry", "forced", "pending", "v328_quality", "gate", "strong", "reentry"])
def _v330_route_needs_hard_precheck(row: dict) -> bool:
    try:
        row = row if isinstance(row, dict) else {}
        blob = _v328_blob(row) if callable(globals().get("_v328_blob")) else str(row).lower()
        return any(x in blob for x in [
            "취소후 복귀감시", "강한놓침 복귀감시", "강한놓침 눌림감시", "cancel_reentry",
            "strong_reentry", "strict_signal", "interest_prepare", "v274_preview", "v275_order_flow",
            "정밀검토", "재감시", "진입 대기",
        ])
    except Exception:
        return False
def _v330_base_quality(row: dict) -> dict:
    try:
        if callable(globals().get("_BASE_V328_CHART_QUALITY_V329")):
            return _BASE_V328_CHART_QUALITY_V329(row if isinstance(row, dict) else {})
    except Exception:
        pass
    try:
        return _v328_chart_quality(row if isinstance(row, dict) else {})
    except Exception:
        return {"code": "MISSING", "reason": "quality 계산 실패"}
def _v330_df_ok(df, min_rows: int = 3) -> bool:
    try:
        return df is not None and hasattr(df, "tail") and len(df) >= int(min_rows)
    except Exception:
        return False
def _v330_get_cached_df(ticker: str):
    ticker = str(ticker or "").upper().strip()
    if not ticker:
        return None, "empty_ticker"
    try:
        df = V329_REPAIR_DF_CACHE.get(ticker) if isinstance(globals().get("V329_REPAIR_DF_CACHE", {}), dict) else None
        if _v330_df_ok(df, 3):
            _v330_inc("source_df_cache", f"DF캐시 {ticker}")
            return df, "v329_df_cache_v330"
    except Exception:
        pass
    try:
        if callable(globals().get("_m1v255_cache")):
            df = _m1v255_cache(ticker, 80.0)
            if _v330_df_ok(df, 3):
                _v330_inc("source_m1_cache", f"중앙캐시 {ticker}")
                return df, "minute1_central_cache_v330"
    except Exception:
        pass
    try:
        if callable(globals().get("get_api_cache_entry")):
            ttl = get_ohlcv_cache_ttl("minute1") * 80 if callable(globals().get("get_ohlcv_cache_ttl")) else 900.0
            df = get_api_cache_entry(API_OHLCV_CACHE, (ticker, "minute1"), max(180.0, ttl), copy_dataframe=True)
            if _v330_df_ok(df, 3):
                _v330_inc("source_api_cache", f"API캐시 {ticker}")
                return df, "api_ohlcv_cache_v330"
    except Exception:
        pass
    return None, "cache_empty"
def _v330_fetch_minute1_df(ticker: str, row: dict = None, reason: str = "repair"):
    """v329 성공 0의 주원인: get_ohlcv(minute1)가 중앙큐로 리다이렉트되어 None을 반환함. v330은 중앙캐시→중앙worker→원본 get_ohlcv 순서로 원인을 나눠 처리한다."""
    ticker = str(ticker or "").upper().strip()
    row = row if isinstance(row, dict) else {"ticker": ticker}
    if not ticker:
        return None, "ticker_empty", "ticker 없음"
    df, src = _v330_get_cached_df(ticker)
    if _v330_df_ok(df, 3):
        _v330_inc("cache_ok", f"캐시복구 {ticker}/{src}")
        return df, src, "cache_ok"
    critical = _v330_reason_is_critical(reason) or _v330_route_needs_hard_precheck(row)
    if callable(globals().get("_m1v255_enqueue")):
        try:
            okq = _m1v255_enqueue(ticker, f"v330_chart_repair:{reason}", row, priority=3.5 if critical else 1.2, force=bool(critical))
            if okq:
                _v330_inc("central_queue", f"중앙큐 등록 {ticker}")
        except Exception as e:
            _v330_fail("central_queue_error", ticker, str(e)[:80])
    if critical and callable(globals().get("process_precision_minute1_chart_once")):
        try:
            _v330_inc("central_process", f"중앙worker 즉시처리 {ticker}")
            process_precision_minute1_chart_once(ticker, reason=f"v330_critical_{str(reason)[:40]}")
            df, src = _v330_get_cached_df(ticker)
            if _v330_df_ok(df, 3):
                return df, src + ":after_worker", "central_worker_ok"
        except Exception as e:
            _v330_fail("central_process_error", ticker, str(e)[:80])
    if critical and callable(globals().get("_ORIG_GET_OHLCV_V255")):
        try:
            try:
                if callable(globals().get("shorten_ohlcv_cooldown_for_priority")):
                    shorten_ohlcv_cooldown_for_priority(ticker, "minute1", max_cooldown_sec=2)
            except Exception:
                pass
            _v330_inc("direct_bypass", f"원본 minute1 직접확인 {ticker}")
            df = _ORIG_GET_OHLCV_V255(ticker, interval="minute1", allow_slow_fetch=True)
            if _v330_df_ok(df, 3):
                try:
                    if callable(globals().get("set_api_cache_entry")):
                        set_api_cache_entry(API_OHLCV_CACHE, (ticker, "minute1"), df, copy_dataframe=True)
                except Exception:
                    pass
                _v330_inc("source_direct", f"원본REST 성공 {ticker}")
                return df, "orig_get_ohlcv_minute1_v330", "direct_ok"
            _v330_fail("direct_empty", ticker, "원본 get_ohlcv 결과 없음")
        except Exception as e:
            _v330_fail("direct_exception", ticker, str(e)[:80])
    if critical and "pybithumb" in globals():
        try:
            _v330_inc("direct_bypass", f"pybithumb 직접확인 {ticker}")
            df = pybithumb.get_ohlcv(ticker, interval="minute1")
            if _v330_df_ok(df, 3):
                try:
                    if callable(globals().get("set_api_cache_entry")):
                        set_api_cache_entry(API_OHLCV_CACHE, (ticker, "minute1"), df, copy_dataframe=True)
                except Exception:
                    pass
                _v330_inc("source_direct", f"pybithumb 성공 {ticker}")
                return df, "pybithumb_direct_minute1_v330", "pybithumb_ok"
            _v330_fail("pybithumb_empty", ticker, "pybithumb 결과 없음")
        except Exception as e:
            _v330_fail("pybithumb_exception", ticker, str(e)[:80])
    _v330_inc("source_pseudo_or_wait", f"정밀대기 {ticker}")
    return None, "minute1_wait_v330", "queued_wait"
def _v329_repair_chart_quality(obj: dict, base_q: dict = None, reason: str = "quality") -> dict:
    obj = obj if isinstance(obj, dict) else {}
    base_q = base_q if isinstance(base_q, dict) else {}
    ticker = _v329_ticker(obj) if callable(globals().get("_v329_ticker")) else str(obj.get("ticker", "") or "").upper().strip()
    if not ticker:
        _v330_fail("ticker_empty", "", "repair")
        return {"ok": False, "code": "REPAIR_FAILED", "reason": "ticker 없음", "prev_code": base_q.get("code")}
    now = _v329_now() if callable(globals().get("_v329_now")) else time.time()
    critical = _v330_reason_is_critical(reason) or _v330_route_needs_hard_precheck(obj)
    try:
        cached = V329_REPAIR_CACHE.get(ticker) if isinstance(globals().get("V329_REPAIR_CACHE", {}), dict) else None
        if isinstance(cached, dict) and now - safe_float(cached.get("repair_ts", 0), 0) <= (18.0 if critical else 45.0):
            if cached.get("ok") or not critical:
                _v329_inc("repair_cache_hit", f"차트복구 캐시 {ticker}")
                out = dict(cached); out["prev_code"] = base_q.get("code", "")
                return out
            _v330_inc("fail_cache_ignored", f"실패캐시 무시 후 재시도 {ticker}")
    except Exception:
        pass
    try: _v329_inc("repair_attempt", f"v330 차트복구 시도 {ticker}/{reason}")
    except Exception: pass
    _v330_inc("repair_attempt", f"{ticker}/{reason}")
    df, src, fetch_status = _v330_fetch_minute1_df(ticker, obj, reason)
    if not _v330_df_ok(df, 3):
        code = "REPAIR_QUEUED" if fetch_status == "queued_wait" else "REPAIR_FAILED"
        q = {"ok": False, "code": code, "reason": f"1분봉 복구 대기/실패: {fetch_status}", "ticker": ticker, "source": src, "fetch_status": fetch_status, "prev_code": base_q.get("code", ""), "repair_ts": now}
        try:
            V329_REPAIR_CACHE[ticker] = dict(q)
            _v329_inc("repair_fail", f"v330 복구 실패 {ticker}/{fetch_status}")
        except Exception:
            pass
        _v330_fail(fetch_status, ticker, src)
        return q
    q = _v329_df_to_quality(ticker, df, src) if callable(globals().get("_v329_df_to_quality")) else {"ok": False, "code": "REPAIR_FAILED", "reason": "df_to_quality 없음"}
    q["prev_code"] = base_q.get("code", "")
    q["fetch_status"] = fetch_status
    q["v330_source"] = src
    q["repair_ts"] = now
    if q.get("ok"):
        try:
            V329_REPAIR_CACHE[ticker] = dict(q)
            V329_REPAIR_DF_CACHE[ticker] = df
            _v329_inc("repair_ok", f"v330 차트복구 성공 {ticker}/{q.get('code')}")
        except Exception:
            pass
        _v330_inc("repair_ok", f"{ticker}/{q.get('code')}")
        if str(q.get("code")) == "REST_FLAT_CONFIRMED":
            _v330_inc("flat_confirmed", ticker)
        try:
            if callable(globals().get("store_precision_minute1_chart_state")):
                store_precision_minute1_chart_state(ticker, df=df, source=str(src), reason=f"v330_chart_repair:{reason}", row_hint=obj)
                try: _v329_inc("rest_df_store")
                except Exception: pass
        except Exception as e:
            _v330_fail("store_precision_error", ticker, str(e)[:80])
    else:
        try:
            V329_REPAIR_CACHE[ticker] = dict(q)
            _v329_inc("repair_fail", f"v330 계산실패 {ticker}/{q.get('reason','')}")
        except Exception:
            pass
        _v330_fail(str(q.get("reason", "df_quality_fail"))[:60], ticker, src)
    return q
try:
    _BASE_V329_APPLY_REPAIR_TO_ROW_V330 = globals().get('_v329_apply_repair_to_row')
except Exception:
    _BASE_V329_APPLY_REPAIR_TO_ROW_V330 = None
def _v329_apply_repair_to_row(row: dict, q: dict) -> dict:
    row = _BASE_V329_APPLY_REPAIR_TO_ROW_V330(row, q) if callable(_BASE_V329_APPLY_REPAIR_TO_ROW_V330) else row
    try:
        if isinstance(row, dict) and isinstance(q, dict) and q.get("ok"):
            row["v330_chart_repair_code"] = q.get("code")
            row["v330_chart_repair_source"] = q.get("source") or q.get("v330_source")
            row["v330_chart_fetch_status"] = q.get("fetch_status")
            row["v330_chart_verified"] = str(q.get("code")) in {"REST_REPAIRED", "CACHE_REPAIRED"}
            row["chart_quality_v330"] = q.get("code")
            _v330_inc("row_applied", f"row반영 {str(row.get('ticker','?')).upper()}/{q.get('code')}")
    except Exception:
        pass
    return row
def _v330_entry_chart_precheck(row: dict, stage: str = "paper"):
    row = row if isinstance(row, dict) else {}
    q0 = _v330_base_quality(row)
    need = False
    try:
        need = bool(_v329_need_repair(row, q0)) if callable(globals().get("_v329_need_repair")) else False
    except Exception:
        need = False
    hard = _v330_route_needs_hard_precheck(row)
    code0 = str((q0 or {}).get("code", "") or "")
    if hard and code0 in {"FLAT_SUSPECT", "MISSING", "WS_ONLY", "REPAIR_FAILED", "REPAIR_QUEUED"}:
        need = True
    if hard and not row.get("v330_chart_verified") and any(x in str(row).lower() for x in ["취소후 복귀감시", "cancel_reentry", "strong_reentry"]):
        need = True
    q = q0
    if need or stage in {"paper_register", "forced_pending"}:
        q = _v329_repair_chart_quality(row, q0, reason=stage)
        if q.get("ok"):
            _v329_apply_repair_to_row(row, q)
        else:
            if hard or stage in {"paper_register", "forced_pending"}:
                return False, True, f"차트복구 미완료({q.get('code')}/{q.get('reason')})", q
    code = str((q or {}).get("code", "") or "")
    if code in {"REPAIR_FAILED", "REPAIR_QUEUED", "REPAIR_RATE_LIMITED", "MISSING", "FLAT_SUSPECT", "WS_ONLY"} and hard:
        return False, True, f"차트상태 {code}라 진입/주입 보류", q
    if code == "REST_FLAT_CONFIRMED" and hard:
        return False, True, "REST 확인해도 평평함 → 진입/주입 보류", q
    last_drop = safe_float((q or {}).get("last_candle_change_pct", 0), 0)
    swing10 = safe_float((q or {}).get("swing10", 0), 0)
    if last_drop <= -0.55 and hard:
        return False, True, f"복구봉 급밀림 {last_drop:+.2f}% → 진입/주입 보류", q
    if swing10 <= 0.05 and hard and safe_float((q or {}).get("maxchg", 0), 0) <= 0.08:
        return False, True, "복구 후에도 최근10분 변동 부족 → 진입/주입 보류", q
    return True, False, "", q
