def _v331_blob(obj: dict) -> str:
    try:
        if not isinstance(obj, dict):
            return ""
        keys = ["lane", "trigger", "register_reason", "signal_grade", "original_grade", "entry_rule", "close_reason", "v331_route", "route", "pattern_tag", "final_class", "final_judgement", "reason"]
        return " ".join(str(obj.get(k, "") or "") for k in keys).lower()
    except Exception:
        return ""
def _v331_lane_type(pos: dict) -> str:
    blob = _v331_blob(pos)
    if any(x in blob for x in ["cancel_reentry", "strong_reentry", "강한놓침", "취소후 복귀", "강한놓침 복귀", "강한놓침 눌림"]):
        return "strong"
    if any(x in blob for x in ["interest_prepare", "관심 후보", "preview", "v274", "v275", "weak", "loose"]):
        return "weak"
    if any(x in blob for x in ["strict", "실전급", "buy_ok"]):
        return "strict"
    return "general"
def _v331_route_from_row(row: dict) -> str:
    try:
        row = row if isinstance(row, dict) else {}
        for k in ["v331_route", "paper_route", "watch_route", "route", "lane", "trigger", "final_class", "final_judgement", "pattern_tag"]:
            v = str(row.get(k, "") or "").strip()
            if v:
                return v[:120]
        blob = _v331_blob(row)
        if "cancel_reentry" in blob or "강한놓침" in blob:
            return "strong_reentry"
        if "interest" in blob or "관심" in blob:
            return "interest_prepare"
        if "strict" in blob or "실전급" in blob:
            return "strict_signal"
    except Exception:
        pass
    return "UNKNOWN_EXPLICIT"
def _v331_chart_code_from_row(row: dict) -> str:
    try:
        row = row if isinstance(row, dict) else {}
        for k in ["v330_chart_repair_code", "chart_quality_v330", "chart_quality_v329", "chart_quality_code", "v328_chart_quality", "chart_quality"]:
            v = str(row.get(k, "") or "").strip()
            if v:
                return v[:80]
    except Exception:
        pass
    return "UNKNOWN_EXPLICIT"
def _v331_calc_pct(entry: float, price: float) -> float:
    try:
        if entry <= 0 or price <= 0:
            return 0.0
        return (price - entry) / entry * 100.0
    except Exception:
        return 0.0
def _v331_price_for_gross(entry: float, gross_pct: float) -> float:
    try:
        return float(entry) * (1.0 + float(gross_pct) / 100.0)
    except Exception:
        return 0.0
def _v331_min_keep_gross(max_up: float, lane_type: str) -> float:
    """전량청산 기준. 수수료 전 gross 최소 회수 목표."""
    fee = safe_float(globals().get("PAPER_FEE_ROUND_TRIP_PCT", 0.10), 0.10)
    max_up = safe_float(max_up, 0)
    lane_type = str(lane_type or "general")
    if max_up >= 1.50:
        return max(fee + 0.55, max_up * 0.55)
    if max_up >= 1.20:
        return max(fee + 0.42, 0.55)
    if max_up >= 0.90:
        return max(fee + 0.25, 0.38)
    if max_up >= 0.70:
        return max(fee + 0.12, 0.24)
    if max_up >= 0.50:
        return max(fee + 0.03, 0.14)
    if lane_type == "strong" and max_up >= 0.35:
        return max(fee + 0.01, 0.11)
    return -999.0
def _v331_central_exit_guard(pos: dict, price: float, reason: str, now_ts: float = None, phase: str = "close"):
    """모든 paper 청산이 통과하는 중앙 보호 엔진. 반환: (price, reason, applied, meta)."""
    try:
        pos = pos if isinstance(pos, dict) else {}
        now_ts = safe_float(now_ts, time.time())
        entry = safe_float(pos.get("entry_price", 0), 0)
        price = safe_float(price, 0)
        if entry <= 0 or price <= 0:
            return price, str(reason or "close"), False, {"why": "bad_price"}
        current_pct = _v331_calc_pct(entry, price)
        max_up = max(safe_float(pos.get("max_up_pct", current_pct), current_pct), current_pct)
        min_down = min(safe_float(pos.get("min_down_pct", current_pct), current_pct), current_pct)
        held = max(0.0, now_ts - safe_float(pos.get("entered_ts", pos.get("created_ts", now_ts)), now_ts))
        lane_type = _v331_lane_type(pos)
        reason0 = str(reason or "close")
        fee = safe_float(globals().get("PAPER_FEE_ROUND_TRIP_PCT", 0.10), 0.10)
        min_keep = _v331_min_keep_gross(max_up, lane_type)
        if min_keep > -900 and current_pct < min_keep:
            guard_price = _v331_price_for_gross(entry, min_keep)
            if guard_price > 0:
                tag = "v331_central_breakeven_guard"
                if max_up >= 0.90:
                    tag = "v331_central_trailing_guard"
                    _v331_inc("trailing_forced", f"{pos.get('ticker')}/{max_up:+.2f}->{min_keep:+.2f}")
                else:
                    _v331_inc("breakeven_forced", f"{pos.get('ticker')}/{max_up:+.2f}->{min_keep:+.2f}")
                if current_pct < -0.05 and max_up >= 0.50:
                    _v331_inc("hard_guard_fail_prevented", f"{pos.get('ticker')} {current_pct:+.2f}%→{min_keep:+.2f}%")
                new_reason = f"{tag}: 최고 {max_up:+.2f}% 후 최소 {min_keep:+.2f}% 방어 / 원래 {reason0}"
                return guard_price, new_reason, True, {"type": tag, "max_up": max_up, "current_pct": current_pct, "min_keep": min_keep, "lane": lane_type}
        if max_up <= 0.15 and held >= 90 and current_pct <= -0.55:
            _v331_inc("no_progress_cut", f"{pos.get('ticker')} {current_pct:+.2f}%")
            new_reason = f"v331_no_progress_crash_cut: 최고 {max_up:+.2f}% 없이 {current_pct:+.2f}% 밀림 / 원래 {reason0}"
            return price, new_reason, True, {"type": "no_progress", "max_up": max_up, "current_pct": current_pct, "lane": lane_type, "min_down": min_down}
        _v331_inc("excluded_with_reason", f"제외 {pos.get('ticker')}: 최고 {max_up:+.2f}% 현재 {current_pct:+.2f}% {lane_type}")
        return price, reason0, False, {"type": "no_guard_needed", "max_up": max_up, "current_pct": current_pct, "lane": lane_type}
    except Exception as e:
        try:
            append_runtime_error_log("v331_central_exit_guard", str(e), exc=e, include_traceback=False)
        except Exception:
            pass
        return price, str(reason or "close"), False, {"why": "exception"}
