def _paper_close_position_v258(pos_id: str, pos: dict, price: float, reason: str, now_ts: float = None):
    _v331_inc("central_close_seen", f"청산중앙 {str((pos or {}).get('ticker','?')).upper()}")
    now_ts = safe_float(now_ts, time.time())
    pos2 = dict(pos or {})
    adj_price, adj_reason, applied, meta = _v331_central_exit_guard(pos2, price, reason, now_ts, phase="close")
    if applied:
        _v331_inc("central_close_protected", f"{pos2.get('ticker')}/{meta.get('type')}")
        try:
            pos2["v331_guard_applied"] = True
            pos2["v331_guard_type"] = str(meta.get("type", ""))
            pos2["v331_original_close_reason"] = str(reason or "")
            pos2["v331_original_close_price"] = safe_float(price, 0)
            pos2["v331_guard_price"] = safe_float(adj_price, 0)
            pos2["v331_guard_meta"] = dict(meta)
        except Exception:
            pass
    return _BASE_PAPER_CLOSE_V331(pos_id, pos2, adj_price, adj_reason, now_ts) if callable(_BASE_PAPER_CLOSE_V331) else None
def _v331_scan_open_guards(phase: str = "loop") -> int:
    """base 청산 로직을 우회하는 OPEN 포지션도 중앙 보호를 먼저/나중에 강제 적용."""
    if not globals().get("PAPER_TRADING_ON", False):
        return 0
    closed = 0
    now_ts = time.time()
    try:
        with PAPER_STATE_LOCK:
            items = [(pid, dict(pos)) for pid, pos in (paper_positions or {}).items() if isinstance(pos, dict) and str(pos.get("status", "")).upper() == "OPEN"]
        for pid, pos in items:
            ticker = str(pos.get("ticker", "") or "").upper().strip()
            if not ticker:
                continue
            fallback = safe_float(pos.get("last_price", pos.get("entry_price", 0)), 0)
            price, src, age = _paper_price_v258(ticker, fallback=fallback) if callable(globals().get("_paper_price_v258")) else (fallback, "fallback", 0)
            if price <= 0:
                continue
            entry = safe_float(pos.get("entry_price", 0), 0)
            current_pct = _v331_calc_pct(entry, price)
            pos["last_price"] = price
            pos["last_price_source"] = src
            pos["last_price_age"] = safe_float(age, 0)
            pos["updated_ts"] = now_ts
            pos["max_up_pct"] = max(safe_float(pos.get("max_up_pct", current_pct), current_pct), current_pct)
            pos["min_down_pct"] = min(safe_float(pos.get("min_down_pct", current_pct), current_pct), current_pct)
            lane_type = _v331_lane_type(pos)
            max_up = safe_float(pos.get("max_up_pct", 0), 0)
            held = max(0.0, now_ts - safe_float(pos.get("entered_ts", pos.get("created_ts", now_ts)), now_ts))
            min_keep = _v331_min_keep_gross(max_up, lane_type)
            should_close = False
            reason = ""
            close_price = price
            if min_keep > -900 and current_pct <= min_keep:
                should_close = True
                close_price = _v331_price_for_gross(entry, min_keep)
                reason = f"v331_live_guard_{phase}: 최고 {max_up:+.2f}% 후 최소 {min_keep:+.2f}% 방어"
            elif max_up <= 0.15 and held >= 90 and current_pct <= -0.55:
                should_close = True
                close_price = price
                reason = f"v331_live_no_progress_cut_{phase}: 최고 {max_up:+.2f}% 없이 {current_pct:+.2f}% 밀림"
            if should_close:
                _v331_inc("guard_scan_close", f"{ticker}/{reason[:60]}")
                _paper_close_position_v258(pid, pos, close_price, reason, now_ts)
                closed += 1
            else:
                with PAPER_STATE_LOCK:
                    if pid in paper_positions:
                        paper_positions[pid].update(pos)
    except Exception as e:
        try:
            append_runtime_error_log("v331_scan_open_guards", str(e), exc=e, include_traceback=False)
        except Exception:
            pass
    return closed
