def _v331_enrich_latest_position(ticker: str, row: dict, now_ts: float = None) -> bool:
    try:
        ticker = str(ticker or "").upper().strip()
        now_ts = safe_float(now_ts, time.time())
        if not ticker:
            return False
        route = _v331_route_from_row(row)
        chart_code = _v331_chart_code_from_row(row)
        grade = str((row or {}).get("signal_grade", "") or (row or {}).get("grade", "") or (row or {}).get("final_grade", "") or "UNKNOWN_EXPLICIT")[:80]
        saved = False
        with PAPER_STATE_LOCK:
            for pid, pos in list((paper_positions or {}).items()):
                if not isinstance(pos, dict) or str(pos.get("ticker", "") or "").upper().strip() != ticker:
                    continue
                age = now_ts - safe_float(pos.get("created_ts", now_ts), now_ts)
                if age > 90:
                    continue
                pos["v331_route"] = route
                pos["v331_chart_code"] = chart_code
                pos["v331_grade"] = grade
                pos["v331_entry_saved"] = True
                pos["v331_entry_saved_ts"] = now_ts
                pos["v331_row_snapshot"] = {
                    "route": route,
                    "chart_code": chart_code,
                    "grade": grade,
                    "score": safe_float((row or {}).get("score", (row or {}).get("final_score", 0)), 0),
                    "price": safe_float((row or {}).get("price", (row or {}).get("current_price", 0)), 0),
                    "v330_chart_repair_code": str((row or {}).get("v330_chart_repair_code", "") or ""),
                    "v330_chart_verified": bool((row or {}).get("v330_chart_verified", False)),
                }
                paper_positions[pid] = pos
                saved = True
        if saved:
            if route == "UNKNOWN_EXPLICIT":
                _v331_inc("route_forced", f"route명시 {ticker}")
            if chart_code == "UNKNOWN_EXPLICIT":
                _v331_inc("chart_forced", f"chart명시 {ticker}")
            _v331_inc("entry_saved", f"paper기록저장 {ticker}/{route}/{chart_code}")
            save_paper_state_v258()
        return saved
    except Exception as e:
        try:
            append_runtime_error_log("v331_enrich_latest_position", str(e), exc=e, include_traceback=False)
        except Exception:
            pass
        return False
def paper_register_candidate_v258(row: dict, trigger: str = ""):
    row = row if isinstance(row, dict) else {}
    ticker = _paper_ticker_v258(row) if callable(globals().get("_paper_ticker_v258")) else str(row.get("ticker", "") or "").upper().strip()
    _v331_inc("entry_seen", f"paper진입중앙 {ticker}")
