def _v333_inc(key: str, note: str = ""):
    try:
        if key in V333_STATS:
            V333_STATS[key] = int(safe_float(V333_STATS.get(key, 0), 0)) + 1
        if note:
            V333_STATS["last_note"] = str(note)[:260]
    except Exception:
        pass
def _v333_ticker(obj: dict) -> str:
    try:
        if callable(globals().get("_v332_ticker")):
            t = _v332_ticker(obj)
            if t:
                return t
        return str((obj or {}).get("ticker", "") or "").upper().strip()
    except Exception:
        return ""
def _v333_blob(*objs) -> str:
    parts = []
    try:
        for obj in objs:
            if not isinstance(obj, dict):
                continue
            keys = [
                "ticker", "lane", "trigger", "register_reason", "close_reason", "cancel_reason", "reason", "entry_rule",
                "signal_grade", "original_grade", "grade", "final_grade", "paper_original_grade", "route", "v331_route", "v332_route", "v333_route",
                "final_class", "final_type", "final_judgement", "pattern_tag", "watch_route", "signal_decision", "decision", "note",
                "raw_hint", "v312_judgement", "next_judgement", "minute1_status", "chart_status", "chart_quality_code",
            ]
            parts.extend(str(obj.get(k, "") or "") for k in keys)
    except Exception:
        pass
    return " | ".join(parts).lower()
def _v333_route_from_any(row: dict = None, pos: dict = None) -> str:
    try:
        merged = {}
        if isinstance(row, dict):
            merged.update(row)
        if isinstance(pos, dict):
            merged.update(pos)
        if callable(globals().get("_v332_route_from_row")):
            r0 = _v332_route_from_row(merged)
            if r0:
                return str(r0)[:140]
        for k in ["v333_route", "v332_route", "v331_route", "paper_route", "watch_route", "route", "lane", "trigger", "final_class", "final_judgement", "pattern_tag"]:
            v = str(merged.get(k, "") or "").strip()
            if v:
                return v[:140]
        blob = _v333_blob(row or {}, pos or {})
        if any(x in blob for x in ["강한놓침", "강한 놓침", "cancel_reentry", "v313", "v314", "복귀감시", "눌림감시"]):
            return "cancel_reentry_strong_watch"
        if any(x in blob for x in ["실전급", "strict_signal", "strict"]):
            return "strict_signal"
        if any(x in blob for x in ["관심", "preview", "v274", "미리볼"]):
            return "interest_prepare"
        if any(x in blob for x in ["체결흐름", "trade_flow"]):
            return "trade_flow_prepare"
    except Exception:
        pass
    return "UNKNOWN_EXPLICIT"
def _v333_grade_from_any(row: dict = None, pos: dict = None) -> str:
    try:
        merged = {}
        if isinstance(row, dict):
            merged.update(row)
        if isinstance(pos, dict):
            merged.update(pos)
        for k in [
            "v333_grade", "v332_grade", "v331_grade", "signal_grade", "grade", "entry_grade", "final_grade",
            "original_grade", "paper_original_grade", "signal_decision", "decision",
        ]:
            v = str(merged.get(k, "") or "").strip()
            if v and "미저장" not in v:
                return v[:80]
        blob = _v333_blob(row or {}, pos or {})
        if any(x in blob for x in ["실전급", "strict_signal", "strict"]):
            return "실전급"
        if any(x in blob for x in ["강한놓침", "강한 놓침", "v313", "v314", "cancel_reentry"]):
            return "강한놓침"
        if any(x in blob for x in ["관심", "preview", "v274", "미리볼"]):
            return "관심"
        if any(x in blob for x in ["체결흐름", "trade_flow"]):
            return "체결흐름"
    except Exception:
        pass
    _v333_inc("entry_trace_unknown_grade", "grade UNKNOWN_EXPLICIT")
    return "UNKNOWN_EXPLICIT"
def _v333_chart_from_any(row: dict = None, pos: dict = None) -> str:
    try:
        merged = {}
        if isinstance(row, dict):
            merged.update(row)
        if isinstance(pos, dict):
            merged.update(pos)
        if callable(globals().get("_v332_chart_from_row")):
            c0 = _v332_chart_from_row(merged)
            if c0 and c0 != "UNKNOWN_EXPLICIT":
                return str(c0)[:100]
        for k in [
            "v333_chart_code", "v332_chart_code", "v331_chart_code", "chart_status", "minute1_status", "chart_check",
            "v330_chart_repair_code", "v329_chart_repair_code", "chart_quality_code", "v328_chart_quality_code", "precision_chart_status",
            "minute1_central_status", "source",
        ]:
            v = str(merged.get(k, "") or "").strip()
            if v and "미저장" not in v:
                return v[:100]
        if bool(merged.get("v330_chart_verified", False)):
            return "v330_VERIFIED"
        if bool(merged.get("v329_chart_repaired", False)) or "cache_repaired" in _v333_blob(merged):
            return "v329_CACHE_REPAIRED"
    except Exception:
        pass
    _v333_inc("entry_trace_unknown_chart", "chart UNKNOWN_EXPLICIT")
    return "UNKNOWN_EXPLICIT"
def _v333_enrich_position_dict(pos: dict, row: dict = None, note: str = "") -> tuple[dict, bool]:
    try:
        if not isinstance(pos, dict):
            return pos, False
        row = row if isinstance(row, dict) else {}
        try:
            if callable(globals().get("_v332_enrich_position_dict")):
                pos, _ = _v332_enrich_position_dict(pos, row, note=f"v333_base/{note}")
        except Exception:
            pass
        grade = _v333_grade_from_any(row, pos)
        chart = _v333_chart_from_any(row, pos)
        route = _v333_route_from_any(row, pos)
        changed = False
        force_fields = {
            "v333_schema": V333_SCHEMA_VERSION,
            "v333_entry_saved": True,
            "v333_entry_saved_ts": time.time(),
            "v333_route": route,
            "v332_route": pos.get("v332_route", route) or route,
            "v331_route": pos.get("v331_route", route) or route,
            "v333_grade": grade,
            "v332_grade": pos.get("v332_grade", grade) or grade,
            "v331_grade": pos.get("v331_grade", grade) or grade,
            "v333_chart_code": chart,
            "v332_chart_code": pos.get("v332_chart_code", chart) or chart,
            "v331_chart_code": pos.get("v331_chart_code", chart) or chart,
        }
        output_fields = {
            "signal_grade": grade,
            "original_grade": grade,
            "paper_original_grade": grade,
            "grade": grade,
            "route": route,
            "watch_route": route,
            "chart_status": chart,
            "minute1_status": chart,
            "chart_quality_code": chart,
        }
        for k, v in force_fields.items():
            if pos.get(k) != v:
                pos[k] = v
                changed = True
        for k, v in output_fields.items():
            cur = str(pos.get(k, "") or "").strip()
            if (not cur) or "미저장" in cur:
                pos[k] = v
                changed = True
                if k in {"signal_grade", "original_grade", "grade"}:
                    _v333_inc("entry_trace_grade_fixed", f"등급필드보정 {pos.get('ticker')}/{k}")
                if k in {"chart_status", "minute1_status", "chart_quality_code"}:
                    _v333_inc("entry_trace_chart_fixed", f"차트필드보정 {pos.get('ticker')}/{k}")
        snap = pos.get("v333_row_snapshot") if isinstance(pos.get("v333_row_snapshot"), dict) else {}
        snap.update({"route": route, "grade": grade, "chart_code": chart, "note": str(note or "")[:120], "ts": time.time()})
        pos["v333_row_snapshot"] = snap
        return pos, changed
    except Exception as e:
        try: append_runtime_error_log("v333_enrich_position_dict", str(e), exc=e, include_traceback=False)
        except Exception: pass
        return pos, False
def _v333_enrich_all_active_positions(reason: str = "periodic", limit: int = 120) -> int:
    changed_n = 0
    try:
        with PAPER_STATE_LOCK:
            items = list((paper_positions or {}).items()) if isinstance(paper_positions, dict) else []
            for pid, pos in items[:max(1, int(limit))]:
                if not isinstance(pos, dict):
                    continue
                if str(pos.get("status", "") or "").upper() not in {"PENDING", "OPEN"}:
                    continue
                enriched, changed = _v333_enrich_position_dict(dict(pos), dict(pos), note=reason)
                if changed or "미저장" in str(pos):
                    paper_positions[pid] = enriched
                    changed_n += 1
        if changed_n:
            try: save_paper_state_v258()
            except Exception: pass
            _v333_inc("entry_enriched_all", f"active일괄보정 {changed_n}/{reason}")
    except Exception as e:
        try: append_runtime_error_log("v333_enrich_all_active_positions", str(e), exc=e, include_traceback=False)
        except Exception: pass
    return changed_n
