def force_cancel_reentry_queue_v333(max_register: int = 6) -> int:
    added = 0
    try:
        _v333_inc("rewatch_scan", "큰놓침/지연 재감시 스캔")
        rows = _v313_cancel_rows(limit=180) if callable(globals().get("_v313_cancel_rows")) else []
        now_ts = time.time()
        picked = []
        for row in list(rows or []):
            if not isinstance(row, dict):
                continue
            ticker = _v333_ticker(row)
            if not ticker:
                continue
            cancel_ts = safe_float(row.get("cancel_ts", row.get("created_ts", 0)), 0)
            age = now_ts - cancel_ts if cancel_ts > 0 else 0
            if age <= 0 or age > V333_BIG_MISS_LATE_MAX_AGE_SEC:
                continue
            strong, _ticker, why = _v333_is_rewatch_row_strong(row)
            max_up = safe_float(row.get("max_up_after_cancel_pct", row.get("max_up_pct", 0)), 0)
            cur_up = safe_float(row.get("current_after_cancel_pct", row.get("current_up_pct", 0)), 0)
            if strong and (age <= V333_BIG_MISS_FAST_MAX_AGE_SEC or cur_up >= 1.0 or max_up >= 4.0):
                picked.append((age <= V333_BIG_MISS_FAST_MAX_AGE_SEC, max_up, cur_up, -age, row, why))
        picked.sort(key=lambda x: (x[0], x[1], x[2], x[3]), reverse=True)
        for *_rest, row, why in picked[:max(1, int(max_register))]:
            if added >= max(1, int(max_register)):
                break
            if _v333_force_rewatch_from_row(row, source="missed_scan"):
                added += 1
        if added:
            _v333_inc("rewatch_registered", f"스캔등록 {added}")
    except Exception as e:
        try: append_runtime_error_log("force_cancel_reentry_queue_v333", str(e), exc=e, include_traceback=False)
        except Exception: pass
    return added
