V333_RANK_SOURCE_CACHE = globals().get("V333_RANK_SOURCE_CACHE", {"ts": 0.0, "rows": [], "sec": 0.0, "note": ""})
def get_light_snapshot_rank_rows(limit: int = REALTIME_RANK_DISPLAY_LIMIT, min_move_pct: float = REALTIME_RANK_MIN_RECORD_MOVE_PCT) -> list:
    """v333: rank_source가 10초대로 튀면 2분 이상 완성본을 재사용한다. 명령어 캐시용 병목 완화이며 스캔 조건 변경이 아니다."""
    _v333_inc("rank_source_call", "rank_source 호출")
    now_ts = time.time()
    safe_limit = max(20, min(int(safe_float(limit, 70)), 70))
    try:
        cached_rows = V333_RANK_SOURCE_CACHE.get("rows") if isinstance(V333_RANK_SOURCE_CACHE, dict) else []
        cached_ts = safe_float(V333_RANK_SOURCE_CACHE.get("ts", 0), 0) if isinstance(V333_RANK_SOURCE_CACHE, dict) else 0
        cached_sec = safe_float(V333_RANK_SOURCE_CACHE.get("sec", 0), 0) if isinstance(V333_RANK_SOURCE_CACHE, dict) else 0
        age = now_ts - cached_ts if cached_ts > 0 else 999999
        if cached_rows and age <= V333_RANK_REUSE_NORMAL_SEC:
            _v333_inc("rank_source_reuse", f"짧은재사용 {len(cached_rows)}개/{age:.0f}s")
            return list(cached_rows)[:safe_limit]
        if cached_rows and cached_sec >= V333_RANK_HARD_BUDGET_SEC and age <= V333_RANK_REUSE_AFTER_SLOW_SEC:
            _v333_inc("rank_source_hard_reuse", f"느린뒤강제재사용 {cached_sec:.1f}s/{age:.0f}s")
            return list(cached_rows)[:safe_limit]
        v322 = globals().get("V322_RANK_SOURCE_CACHE", {})
        v322_rows = v322.get("rows") if isinstance(v322, dict) else []
        v322_ts = safe_float(v322.get("ts", 0), 0) if isinstance(v322, dict) else 0
        v322_sec = safe_float(v322.get("sec", 0), 0) if isinstance(v322, dict) else 0
        v322_age = now_ts - v322_ts if v322_ts > 0 else 999999
        if v322_rows and v322_sec >= V333_RANK_HARD_BUDGET_SEC and v322_age <= V333_RANK_REUSE_AFTER_SLOW_SEC:
            V333_RANK_SOURCE_CACHE.update({"ts": now_ts, "rows": list(v322_rows)[:90], "sec": v322_sec, "note": "v322느린캐시재사용"})
            _v333_inc("rank_source_hard_reuse", f"v322느린캐시재사용 {v322_sec:.1f}s/{v322_age:.0f}s")
            return list(v322_rows)[:safe_limit]
    except Exception:
        pass
    t0 = time.time()
    try:
        rows = _BASE_GET_LIGHT_SNAPSHOT_RANK_ROWS_V333(limit=safe_limit, min_move_pct=min_move_pct) if callable(_BASE_GET_LIGHT_SNAPSHOT_RANK_ROWS_V333) else []
        sec = max(0.0, time.time() - t0)
        frozen = freeze_rank_rows_for_command_snapshot(rows, limit=max(safe_limit, 70)) if callable(globals().get("freeze_rank_rows_for_command_snapshot")) else list(rows or [])[:safe_limit]
        V333_RANK_SOURCE_CACHE.update({"ts": time.time(), "rows": list(frozen or [])[:90], "sec": sec, "note": f"원본 {sec:.2f}s/{len(frozen or [])}개"})
        _v333_inc("rank_source_refresh", f"rank_source갱신 {sec:.2f}s/{len(frozen or [])}개")
        if sec >= V333_RANK_HARD_BUDGET_SEC:
            _v333_inc("rank_source_slow", f"rank_source느림 {sec:.2f}s")
        return list(frozen or [])[:safe_limit]
    except Exception as e:
        try: append_runtime_error_log("v333_rank_source", str(e), exc=e, include_traceback=False)
        except Exception: pass
        cached_rows = V333_RANK_SOURCE_CACHE.get("rows", []) if isinstance(V333_RANK_SOURCE_CACHE, dict) else []
        if cached_rows:
            _v333_inc("rank_source_error_reuse", "오류시캐시재사용")
            return list(cached_rows)[:safe_limit]
        return []
