def _v335_ticker(obj: dict) -> str:
    try:
        if callable(globals().get("_v333_ticker")):
            t = _v333_ticker(obj)
            if t:
                return t
        if callable(globals().get("_v332_ticker")):
            t = _v332_ticker(obj)
            if t:
                return t
        return str((obj or {}).get("ticker", "") or "").upper().strip()
    except Exception:
        return ""
def _v335_text(obj: dict, keys: list, default: str = "") -> str:
    try:
        obj = obj if isinstance(obj, dict) else {}
        for k in keys:
            v = obj.get(k)
            if v is None:
                continue
            s = str(v).strip()
            if s:
                return s
    except Exception:
        pass
    return default
def _v335_num(obj: dict, keys: list, default: float = 0.0) -> float:
    try:
        obj = obj if isinstance(obj, dict) else {}
        for k in keys:
            if k in obj:
                v = safe_float(obj.get(k), None)
                if v is not None:
                    return float(v)
    except Exception:
        pass
    return float(default)
def _v335_blob(*objs) -> str:
    parts = []
    try:
        for obj in objs:
            if not isinstance(obj, dict):
                continue
            for k in [
                "ticker", "lane", "trigger", "register_reason", "reason", "cancel_reason", "close_reason",
                "signal_grade", "original_grade", "paper_original_grade", "grade", "final_grade", "entry_grade",
                "route", "v331_route", "v332_route", "v333_route", "v335_route", "watch_route",
                "final_decision", "final_judgement", "final_class", "final_type", "rank_watch_action", "rank_watch_chart_state",
                "signal_decision", "decision", "primary_reason", "note", "source", "precision_chart_source", "current_candle_source",
                "chart_status", "minute1_status", "chart_quality_code", "v335_context_source",
            ]:
                parts.append(str(obj.get(k, "") or ""))
    except Exception:
        pass
    return " | ".join(parts).lower()
def _v335_price(row: dict) -> float:
    return _v335_num(row, ["current_price", "price", "entry_price", "last_price", "close", "trade_price"], 0.0)
