def _v335_entry_risk_reasons(ctx: dict, original_row: dict = None, merged_row: dict = None) -> list:
    reasons = []
    try:
        ctx = ctx if isinstance(ctx, dict) else {}
        original_row = original_row if isinstance(original_row, dict) else {}
        merged_row = merged_row if isinstance(merged_row, dict) else {}
        blob = _v335_blob(ctx, original_row, merged_row)
        route = str(ctx.get("route", "") or "")
        grade = str(ctx.get("grade", "") or "")
        chart = str(ctx.get("chart_status", "") or "")
        final_decision = str(ctx.get("final_decision", "") or "")
        source = str(ctx.get("source", "") or "")
        strict_like = any(x in (route + " " + blob) for x in ["실전급", "strict_signal", "strict"])
        nonbuy_words = ["반짝", "관찰", "복기", "매수신호 아님", "매수 신호 아님", "내부감시", "승격금지", "버림", "discard"]
        if any(w in (final_decision + " " + blob) for w in nonbuy_words):
            reasons.append("최종판정매수아님")
        if str(grade).upper() in {"C", "D", "DISCARD"} or "등급 c" in blob or "grade c" in blob:
            reasons.append("C등급")
        if any(w in (chart + " " + source + " " + blob).lower() for w in ["미검증", "ws_light_snapshot_pseudo", "light_snapshot_pseudo", "unknown_explicit", "pending"]):
            reasons.append("차트미검증")
        short_vals = [safe_float(ctx.get(k, 0), 0) for k in ["change_1m", "change_3m", "change_5m", "change_15m"]]
        if short_vals and max(short_vals) <= 0.0:
            reasons.append("단기흐름음수")
        if safe_float(ctx.get("from_low_pct", 0), 0) <= 0.05 and safe_float(ctx.get("change_5m", 0), 0) <= 0.05:
            reasons.append("저점회복없음")
        row_route = _v335_route(original_row) if original_row else ""
        row_grade = _v335_grade(original_row) if original_row else ""
        row_decision = _v335_text(original_row, ["final_decision", "final_judgement", "final_class", "signal_decision", "decision"], "")
        mismatch = False
        if row_route and row_route != "UNKNOWN_EXPLICIT" and route and route != "UNKNOWN_EXPLICIT" and row_route != route:
            mismatch = True
        if row_grade and row_grade != "UNKNOWN_EXPLICIT" and grade and grade != "UNKNOWN_EXPLICIT" and row_grade != grade:
            mismatch = True
        if row_decision and final_decision and row_decision != final_decision:
            mismatch = True
        if mismatch:
            reasons.append("row허브불일치")
            _v335_inc("context_mismatch", f"row-hub mismatch {ctx.get('ticker')}/{row_route}->{route}/{row_grade}->{grade}")
        if strict_like:
            risk_count = len([r for r in reasons if r in {"최종판정매수아님", "C등급", "차트미검증", "단기흐름음수", "저점회복없음", "row허브불일치"}])
            if risk_count >= 2:
                return list(dict.fromkeys(reasons))
        if {"최종판정매수아님", "C등급"}.issubset(set(reasons)) and ("차트미검증" in reasons or "단기흐름음수" in reasons):
            return list(dict.fromkeys(reasons))
        return []
    except Exception:
        return []
