if 'build_rank_watch_short_text' not in globals():
    def _v283_pick_rank_rows(limit=12):
        rows = []
        def add_many(obj):
            try:
                if isinstance(obj, dict):
                    vals = list(obj.values())
                elif isinstance(obj, (list, tuple)):
                    vals = list(obj)
                else:
                    vals = []
                for x in vals:
                    if isinstance(x, dict):
                        rows.append(x)
            except Exception:
                pass
        for name in (
            'RANK_WATCH_ROWS', 'rank_watch_rows', 'REALTIME_RANK_ROWS', 'realtime_rank_rows',
            'snapshot_rank_rows', 'FAST_RANK_ROWS', 'latest_rank_rows', 'DATA_FACTORY_V294_STAGE2',
            'DATA_FACTORY_V294_STAGE1', 'shared_market_cache'
        ):
            try:
                add_many(globals().get(name))
            except Exception:
                pass
            if len(rows) >= limit:
                break
        out, seen = [], set()
        for r in rows:
            tk = str(r.get('ticker') or r.get('symbol') or r.get('code') or '').upper().replace('KRW-','')
            if not tk or tk in seen:
                continue
            seen.add(tk); out.append(r)
            if len(out) >= limit:
                break
        return out
    def _v283_float(x, default=0.0):
        try:
            if x is None or x == '': return default
            return float(str(x).replace(',', '').replace('%',''))
        except Exception:
            return default
    def build_rank_watch_short_text(limit=None, *args, **kwargs):
        """v2.8.3: /rank_short 및 캐시 worker용 짧은 랭크 fallback.
        기존 350의 무거운 rank_watch 출력 대신 현재 스냅샷만 요약한다.
        """
        try:
            lim = int(limit or globals().get('RANK_WATCH_SHORT_LIMIT', 12) or 12)
        except Exception:
            lim = 12
        rows = _v283_pick_rank_rows(limit=lim)
        now = None
        try:
            now = time.strftime('%m-%d %H:%M:%S')
        except Exception:
            now = ''
        lines = [
            '📈 랭크 감시 /rank_short',
            f'- 버전: {globals().get("BOT_VERSION", "?")} / 시각 {now}',
            '- v2.8.3 다이어트 fallback: 조건/전략 문턱 변경 없음',
        ]
        if not rows:
            lines += [
                '- 현재 표시할 랭크 스냅샷 없음',
                '- 캐시 워커가 준비 중이거나 다이어트로 무거운 rank_watch 경로가 제외됨',
                '자세히: /cache_status /check /errorlog'
            ]
            return '\n'.join(lines)
        lines.append('')
        lines.append('상위 스냅샷')
        for i, r in enumerate(rows[:lim], 1):
            tk = str(r.get('ticker') or r.get('symbol') or r.get('code') or '?').upper().replace('KRW-','')
            price = r.get('price') or r.get('close') or r.get('trade_price') or r.get('current_price') or ''
            chg1 = r.get('change_1m') or r.get('ret_1m') or r.get('minute1_change') or r.get('m1') or ''
            chg3 = r.get('change_3m') or r.get('ret_3m') or r.get('m3') or ''
            money = r.get('money_amount') or r.get('trade_amount_1m') or r.get('amount') or ''
            brief = []
            if price != '': brief.append(f'가격 {price}')
            if chg1 != '': brief.append(f'1분 {chg1}')
            if chg3 != '': brief.append(f'3분 {chg3}')
            if money != '': brief.append(f'돈 {money}')
            lines.append(f'{i}. {tk}' + ((' / ' + ' · '.join(map(str, brief))) if brief else ''))
        return '\n'.join(lines)
