def load_paper_state_v258():
    """v336: 기본 paper 상태는 새 파일만 로드한다. 기존 파일은 legacy로 격리한다."""
    global paper_positions, paper_trade_log, paper_entry_attempts_v336, paper_reject_log_v336
    try:
        pos_raw = load_json_file(PAPER_V336_POSITIONS_FILE, {})
        if isinstance(pos_raw, dict) and isinstance(pos_raw.get("positions"), dict):
            new_positions = dict(pos_raw.get("positions") or {})
        elif isinstance(pos_raw, dict):
            new_positions = dict(pos_raw)
        else:
            new_positions = {}
        new_log = _v336_load_json_list(PAPER_V336_TRADE_LOG_FILE)
        new_attempts = _v336_load_json_list(PAPER_V336_ATTEMPTS_FILE)
        new_rejects = _v336_load_json_list(PAPER_V336_REJECT_LOG_FILE)
        with PAPER_STATE_LOCK:
            paper_positions = {str(k): dict(v) for k, v in new_positions.items() if isinstance(v, dict)}
            paper_trade_log = [dict(x) for x in new_log if isinstance(x, dict)][-PAPER_V336_MAX_LOG:]
            paper_entry_attempts_v336 = [dict(x) for x in new_attempts if isinstance(x, dict)][-PAPER_V336_MAX_ATTEMPTS:]
            paper_reject_log_v336 = [dict(x) for x in new_rejects if isinstance(x, dict)][-PAPER_V336_MAX_REJECTS:]
        PAPER_V258_STATS["loaded_positions"] = len(paper_positions)
        PAPER_V258_STATS["loaded_logs"] = len(paper_trade_log)
        PAPER_V258_STATS["last_note"] = "v336 clean paper 파일 로드 / 기존 paper는 legacy 격리"
        _v336_inc("load", f"v336 로드 pos{len(paper_positions)} log{len(paper_trade_log)}")
        _v336_inc("legacy_isolated", "기존 paper 파일 legacy 격리")
    except Exception as e:
        append_runtime_error_log("load_paper_state_v336", str(e), exc=e, include_traceback=True)
        with PAPER_STATE_LOCK:
            paper_positions = {}
            paper_trade_log = []
            paper_entry_attempts_v336 = []
            paper_reject_log_v336 = []
