def _v339_status(row: dict) -> str:
    return str((row or {}).get('status', '') or '').upper()
def _v339_row_time(row: dict) -> float:
    if not isinstance(row, dict):
        return 0.0
    for k in ("close_ts", "exit_ts", "cancel_ts", "created_ts", "entry_ts", "ts", "time"):
        try:
            v = safe_float(row.get(k, 0), 0)
            if v > 0:
                return v
        except Exception:
            pass
    return 0.0
def _v339_ctx(row: dict) -> dict:
    if not isinstance(row, dict):
        return {}
    for k in ("v337_entry_context", "v336_entry_context", "entry_context", "context"):
        v = row.get(k)
        if isinstance(v, dict):
            return v
    return {}
def _v339_ctx_source(row: dict) -> str:
    ctx = _v339_ctx(row)
    for k in ("context_source", "v337_central_row_source", "v336_context_source", "source"):
        v = str(ctx.get(k, "") or row.get(k, "") or "").strip()
        if v:
            if v == "hub":
                return "hub_legacy"
            return v
    return "?"
def _v339_grade(row: dict) -> str:
    ctx = _v339_ctx(row)
    for k in ("signal_grade", "original_grade", "grade", "v336_grade"):
        v = str(row.get(k, "") or ctx.get(k, "") or "").strip()
        if v:
            return v
    return "?"
def _v339_lane(row: dict) -> str:
    ctx = _v339_ctx(row)
    for k in ("lane", "route", "v336_route", "primary_reason", "trigger"):
        v = str(row.get(k, "") or ctx.get(k, "") or "").strip()
        if v:
            return v
    return "?"
def _v339_reason(row: dict) -> str:
    if not isinstance(row, dict):
        return ""
    for k in ("close_reason", "cancel_reason", "reject_reason", "register_reason", "reason"):
        v = str(row.get(k, "") or "").strip()
        if v:
            return _v339_sanitize_reason(v)
    return ""
def _v339_sanitize_reason(reason: str) -> str:
    s = str(reason or "")
    try:
        parts = [p.strip() for p in s.replace(" / ", "|").split("|") if p.strip()]
        out = []
        seen = set()
        for p in parts:
            p2 = p
            while p2.startswith("원래 "):
                p2 = p2[3:].strip()
            key = p2[:120]
            if key in seen:
                continue
            seen.add(key)
            out.append(p2)
        if out:
            s = " / 원래 ".join(out[:2]) if len(out) > 1 else out[0]
    except Exception:
        pass
    return s[:260]
def _v339_pnl(row: dict) -> str:
    try:
        return f"{safe_float((row or {}).get('pnl_pct', 0), 0):+.2f}%"
    except Exception:
        return "+0.00%"
def _v339_pct(row: dict, *keys, default=0.0) -> float:
    for k in keys:
        try:
            if isinstance(row, dict) and k in row:
                return safe_float(row.get(k, default), default)
        except Exception:
            pass
    return default
def _v339_reject_group(reason: str) -> str:
    blob = str(reason or "").lower()
    if "허브오래됨" in blob or "stale" in blob or "central_row_stale" in blob:
        return "stale"
    if "row_only" in blob or "rank_cache" in blob or "display" in blob:
        return "row_only"
    if "active_duplicate" in blob or "이미" in blob and "진행" in blob:
        return "duplicate"
    if "recent_closed_cooldown" in blob or "cooldown" in blob:
        return "cooldown"
    if "preview_command_only" in blob or "v272" in blob or "미리볼" in blob or "명령어 전용" in blob:
        return "preview"
    if "blocked_v267" in blob or "v267" in blob or "진짜버림" in blob or "늦은진입" in blob:
        return "blocked"
    if "매도반전" in blob or "식는 체결" in blob or "sell_reversal" in blob:
        return "sell_reversal"
    if "final_decision_not_buy" in blob or "grade_not_buy" in blob or "c등급" in blob or "매수아님" in blob:
        return "not_buy"
    return "other"
def _v339_group_label(group: str) -> str:
    return {
        "preview": "미리볼/명령어전용",
        "blocked": "v267 버림/늦은진입",
        "not_buy": "최종판정 매수아님/C등급",
        "stale": "오래된 중앙 row",
        "row_only": "중앙허브 미연결 row_only",
        "duplicate": "이미 진행중 중복",
        "cooldown": "최근 청산 쿨다운",
        "sell_reversal": "매도반전/식는 체결",
        "other": "기타",
    }.get(str(group or "other"), str(group or "기타"))
def _v339_reject_summary(rows: list, max_items: int = 7) -> list:
    buckets = {}
    try:
        for r in rows:
            if not isinstance(r, dict):
                continue
            reason = _v339_reason(r)
            g = _v339_reject_group(reason)
            b = buckets.setdefault(g, {"count": 0, "sample": ""})
            b["count"] += 1
            if not b["sample"]:
                b["sample"] = str(r.get("ticker", "?") or "?")
        _v339_inc("reject_summary_built", "reject summary")
        return sorted([(g, v["count"], v["sample"]) for g, v in buckets.items()], key=lambda x: x[1], reverse=True)[:max_items]
    except Exception:
        return []
def _v339_is_breakout_loss(row: dict) -> bool:
    if not isinstance(row, dict) or _v339_status(row) != "CLOSED":
        return False
    blob = " ".join([_v339_lane(row), _v339_grade(row), _v339_reason(row)]).lower()
    pnl = safe_float(row.get('pnl_pct', 0), 0)
    maxp = _v339_pct(row, 'max_profit_pct', 'max_pnl_pct', 'max_profit', default=0.0)
    return pnl <= 0 and ("breakout" in blob or "돌파" in blob or "order_flow" in blob or "v274" in blob or "v275" in blob or "breakout_wait" in blob) and maxp <= 0.08
def _v339_format_closed(i: int, row: dict) -> str:
    ticker = str((row or {}).get("ticker", "?") or "?")
    reason = _v339_reason(row)
    lane = _v339_lane(row)
    grade = _v339_grade(row)
    src = _v339_ctx_source(row)
    maxp = _v339_pct(row, 'max_profit_pct', 'max_pnl_pct', 'max_profit', default=0.0)
    minp = _v339_pct(row, 'min_profit_pct', 'min_pnl_pct', 'min_profit', default=0.0)
    line = f"{i}. {ticker} / {_v339_pnl(row)} / {reason[:80]} / {lane[:44]} / 등급 {grade} / ctx {src} / 최고 {maxp:+.2f}% / 최저 {minp:+.2f}%"
    if _v339_is_breakout_loss(row):
        line += " / 원인표본: 돌파대기·체결흐름 무진행"
        _v339_inc("breakout_loss_shown", ticker)
    _v339_inc("closed_shown", ticker)
    return line[:620]
def _v339_format_active(i: int, row: dict) -> str:
    ticker = str((row or {}).get("ticker", "?") or "?")
    status = str((row or {}).get("status", "?") or "?").upper()
    entry = safe_float((row or {}).get('entry_price', 0), 0)
    last = safe_float((row or {}).get('last_price', entry), entry)
    pnl = _paper_pct_v258(entry, last) if entry > 0 and last > 0 and status == "OPEN" else 0.0
    line = f"{i}. {ticker} / {status} / {pnl:+.2f}% / {_v339_lane(row)[:44]} / 등급 {_v339_grade(row)} / ctx {_v339_ctx_source(row)}"
    _v339_inc("active_shown", ticker)
    return line[:500]
def build_paper_recent_full_text_v277(limit: int = 20):
    try:
        _v339_inc("display_recent_full", "paper_recent_full")
        rows = _v339_load_rows()
        active = _v339_load_positions()
        closed = sorted([r for r in rows if _v339_status(r) == "CLOSED"], key=_v339_row_time, reverse=True)
        rejected = sorted([r for r in rows if _v339_status(r) == "REJECTED"], key=_v339_row_time, reverse=True)
        active_sorted = sorted([p for p in active if str(p.get('status','')).upper() in {"OPEN", "PENDING"}], key=_v339_row_time, reverse=True)
        lines = [
            "🧾 최근 모의매매 /paper_recent_full",
            "- v339: 실제 표본 먼저 / reject 원본은 아래에 일부 표시",
            "- 조건·paper 게이트 로직 변경 없음",
            "",
        ]
        if active_sorted:
            lines.append("✅ 현재 진행")
            for i, p in enumerate(active_sorted[:10], start=1):
                lines.append(_v339_format_active(i, p))
            lines.append("")
        lines.append("✅ 최근 실제 청산")
        if closed:
            for i, r in enumerate(closed[:12], start=1):
                lines.append(_v339_format_closed(i, r))
        else:
            lines.append("- 아직 실제 청산 표본 없음")
        lines.append("")
        lines.append("🧯 진입보류 요약")
        summary = _v339_reject_summary(rejected[:1000], max_items=10)
        if summary:
            for i, (g, c, sample) in enumerate(summary, start=1):
                lines.append(f"{i}. {_v339_group_label(g)}: {c}건 / 예: {sample}")
        else:
            lines.append("- 최근 진입보류 없음")
        lines.append("")
        lines.append("📄 최근 reject 원본 일부")
        for i, r in enumerate(rejected[:max(1, min(int(limit or 20), 20))], start=1):
            reason = _v339_reason(r)
            lines.append(f"{i}. {r.get('ticker','?')} / {_v339_group_label(_v339_reject_group(reason))} / {reason[:150]} / 등급 {_v339_grade(r)} / ctx {_v339_ctx_source(r)}")
        return "\n".join(lines)
    except Exception as e:
        return f"🧾 최근 모의매매 /paper_recent_full\n- v339 생성 오류: {e.__class__.__name__}: {str(e)[:120]}"
