def _paper_classify_for_register_v258(row: dict):
    try:
        if isinstance(row, dict) and bool(row.get("v340_reconfirm_ok")):
            cls = dict(row)
            cls.setdefault("ticker", _v340_ticker(row))
            cls["grade"] = str(row.get("grade") or "BREAKOUT_WAIT")
            cls["decision"] = str(row.get("decision") or "돌파 2차확인 통과")
            cls["paper_entry_rule_v259"] = str(row.get("paper_entry_rule_v259") or "breakout")
            cls["paper_original_grade"] = cls.get("grade")
            cls["score"] = safe_float(row.get("score", row.get("snapshot_rank_score", 0)), 0)
            cls["money_amount"] = safe_float(row.get("money_amount", row.get("turnover", row.get("trade_amount", 0))), 0)
            cls["trade_count"] = int(safe_float(row.get("trade_count", row.get("ws_trade_count_60s", 0)), 0))
            cls["buy_ratio"] = safe_float(row.get("buy_ratio", row.get("ws_trade_buy_ratio_60s", 0)), 0)
            _v340_inc("classify_override", f"v340분류통과 {cls.get('ticker')}")
            return True, "v340_breakout_reconfirm", str(row.get("v340_reconfirm_reason") or "v340 돌파 2차확인 통과"), cls
    except Exception:
        pass
    if callable(_BASE_PAPER_CLASSIFY_V340):
        return _BASE_PAPER_CLASSIFY_V340(row)
    return False, "v340_classify_missing", "기존 분류기 없음", {}
try:
    _BASE_PAPER_REGISTER_V340 = globals().get('paper_register_candidate_v258')
except Exception:
    _BASE_PAPER_REGISTER_V340 = None
def paper_register_candidate_v258(row: dict, trigger: str = "auto") -> bool:
    """v340: 기존 paper 조건은 유지하되, 돌파/체결흐름 후보는 거절 후 대기실에 남겨 재확인한다."""
    try:
        if str(trigger or "") != "v340_reconfirm":
            _v340_process_recheck_queue(force=False)
        ok = bool(_BASE_PAPER_REGISTER_V340(row, trigger=trigger)) if callable(_BASE_PAPER_REGISTER_V340) else False
        if ok:
            _v340_inc("base_passthrough", f"기존통과 {_v340_ticker(row)}")
            return True
        _v340_inc("base_reject_seen", f"기존거절 {_v340_ticker(row)}")
        if str(trigger or "") == "v340_reconfirm":
            return False
        ctx = {}
        merged = row if isinstance(row, dict) else {}
        try:
            ctx, merged, _invalid = _v337_build_entry_context(row if isinstance(row, dict) else {}, trigger="v340_wait_detect")
        except Exception:
            ctx = {}
            merged = row if isinstance(row, dict) else {}
        _v340_enqueue_recheck(merged if isinstance(merged, dict) else row, ctx if isinstance(ctx, dict) else {}, trigger=trigger, reason="base_reject_to_recheck")
        return False
    except Exception as e:
        try: append_runtime_error_log("paper_register_candidate_v340", str(e), exc=e, include_traceback=True)
        except Exception: pass
        try:
            return bool(_BASE_PAPER_REGISTER_V340(row, trigger=trigger)) if callable(_BASE_PAPER_REGISTER_V340) else False
        except Exception:
            return False
