def _v341_should_bridge_register_row(row: dict, trigger: str = "") -> tuple[bool, str]:
    try:
        text = _v341_text_blob(row, trigger)
        lower = text.lower()
        if any(k in lower for k in ["buy_ok", "v340_reconfirm", "v341_review_watch_bridge"]):
            return False, "direct_or_already_bridge"
        if any(k in text for k in ["초입 강세", "재출발 확인", "고점 재돌파 유지", "고점 재접근", "BREAKOUT_WAIT", "v274", "v275", "체결흐름"]):
            if any(k in text for k in ["진짜버림", "늦은진입 차단"]) and not any(k in text for k in ["초입", "재출발", "고점 재돌파", "v274", "v275"]):
                return False, "hard_discard"
            return True, "register_bridge_recheck"
    except Exception:
        pass
    return False, "not_register_bridge"
def paper_register_candidate_v258(row: dict, trigger: str = "auto") -> bool:
    try:
        ok = bool(_BASE_PAPER_REGISTER_V341(row, trigger=trigger)) if callable(_BASE_PAPER_REGISTER_V341) else False
        if ok:
            return True
        if str(trigger or "") == "v340_reconfirm":
            return False
        bridge_ok, why = _v341_should_bridge_register_row(row if isinstance(row, dict) else {}, trigger=trigger)
        if not bridge_ok:
            return False
        _v341_inc("register_bridge_try", f"등록거절브릿지 {_v341_ticker(row)}/{why}")
        ctx = {}
        merged = row if isinstance(row, dict) else {}
        try:
            ctx, merged, invalid = _v337_build_entry_context(row if isinstance(row, dict) else {}, trigger="v341_register_bridge")
        except Exception:
            invalid = ["context_error"]
        if invalid and not merged:
            _v341_inc("row_bridge_fail", f"등록브릿지중앙없음 {_v341_ticker(row)}")
            return False
        if isinstance(merged, dict):
            merged = dict(merged)
            merged.setdefault("route", "v341_register_bridge")
            merged.setdefault("lane", "v341_register_bridge")
            merged.setdefault("final_decision", "등록거절 후 2차확인 대기")
            merged.setdefault("decision", "등록거절 후 2차확인 대기")
        if callable(globals().get("_v340_enqueue_recheck")) and _v340_enqueue_recheck(merged if isinstance(merged, dict) else {}, ctx if isinstance(ctx, dict) else {}, trigger="v341_register_bridge", reason=why):
            _v341_inc("row_bridge_success", f"등록브릿지대기 {_v341_ticker(merged)}")
        else:
            _v341_inc("row_bridge_fail", f"등록브릿지실패 {_v341_ticker(row)}")
        return False
    except Exception as e:
        try: append_runtime_error_log("paper_register_candidate_v341", str(e), exc=e, include_traceback=True)
        except Exception: pass
        try:
            return bool(_BASE_PAPER_REGISTER_V341(row, trigger=trigger)) if callable(_BASE_PAPER_REGISTER_V341) else False
        except Exception:
            return False
