try:
    BOT_VERSION = "수익형 v2.10.8"
except Exception:
    pass
PAPER_V342_SCHEMA = "paper_v342_good_pullback_routes"
PAPER_V342_QUEUE_FILE = data_file("paper_good_pullback_queue_v342.json")
PAPER_V342_HISTORY_FILE = data_file("paper_good_pullback_history_v342.json")
V342_FIRST_CHECK_SEC = 30.0
V342_SECOND_CHECK_SEC = 90.0
V342_MAX_KEEP_SEC = 240.0
V342_MIN_RETRY_GAP_SEC = 18.0
V342_MAX_QUEUE = 120
V342_MAX_HISTORY = 500
V342_ALERT_COOLDOWN_SEC = 45 * 60
V342_QUEUE = {}
V342_HISTORY = []
V342_STATE = {"processed": {}, "alerted": {}, "last_scan_ts": 0.0}
V342_STATS = {
    "scan": 0,
    "register_seen": 0,
    "register_good": 0,
    "enqueue": 0,
    "enqueue_duplicate": 0,
    "enqueue_v313": 0,
    "enqueue_review": 0,
    "enqueue_register": 0,
    "central_missing": 0,
    "central_stale": 0,
    "process": 0,
    "check_30s": 0,
    "check_90s": 0,
    "reupgrade_try": 0,
    "reupgrade_success": 0,
    "reupgrade_reject": 0,
    "review_move": 0,
    "dead_pullback": 0,
    "alert_sent": 0,
    "alert_skip_cooldown": 0,
    "classify_override": 0,
    "v313_rows_seen": 0,
    "watch_rows_seen": 0,
    "last_note": "v342 대기",
}
def _v342_now() -> float:
    try:
        return time.time()
    except Exception:
        return 0.0
def _v342_inc(key: str, note: str = ""):
    try:
        V342_STATS[key] = int(safe_float(V342_STATS.get(key, 0), 0)) + 1
        if note:
            V342_STATS["last_note"] = str(note)[:240]
    except Exception:
        pass
def _v342_ticker(row=None) -> str:
    try:
        if callable(globals().get("_v340_ticker")):
            return _v340_ticker(row)
    except Exception:
        pass
    try:
        if isinstance(row, str):
            t = row
        else:
            row = row if isinstance(row, dict) else {}
            t = str(row.get("ticker", row.get("symbol", "")) or "")
        t = t.upper().strip()
        if t.startswith("KRW-"):
            t = t.split("-", 1)[1]
        return t
    except Exception:
        return ""
def _v342_load_state():
    global V342_QUEUE, V342_HISTORY, V342_STATE
    try:
        q = load_json_file(PAPER_V342_QUEUE_FILE, {})
        if isinstance(q, dict) and isinstance(q.get("queue"), dict):
            q = q.get("queue")
        if isinstance(q, dict):
            now_ts = _v342_now()
            V342_QUEUE = {}
            for k, v in q.items():
                if not isinstance(v, dict):
                    continue
                first_ts = safe_float(v.get("first_ts", now_ts), now_ts)
                if now_ts - first_ts <= V342_MAX_KEEP_SEC:
                    V342_QUEUE[str(k).upper()] = dict(v)
        h = load_json_file(PAPER_V342_HISTORY_FILE, [])
        if isinstance(h, dict) and isinstance(h.get("rows"), list):
            h = h.get("rows")
        if isinstance(h, list):
            V342_HISTORY = [dict(x) for x in h if isinstance(x, dict)][-V342_MAX_HISTORY:]
        s = load_json_file(data_file("paper_good_pullback_state_v342.json"), {})
        if isinstance(s, dict):
            V342_STATE.update({k: v for k, v in s.items() if k in {"processed", "alerted", "last_scan_ts"}})
            if not isinstance(V342_STATE.get("processed"), dict):
                V342_STATE["processed"] = {}
            if not isinstance(V342_STATE.get("alerted"), dict):
                V342_STATE["alerted"] = {}
    except Exception as e:
        try: append_runtime_error_log("v342_load_state", str(e), exc=e, include_traceback=False)
        except Exception: pass
def _v342_save_state():
    try:
        now_ts = _v342_now()
        q = {}
        for t, rec in list((V342_QUEUE or {}).items()):
            if not isinstance(rec, dict):
                continue
            if now_ts - safe_float(rec.get("first_ts", now_ts), now_ts) <= V342_MAX_KEEP_SEC:
                q[str(t).upper()] = dict(rec)
        save_json_file(PAPER_V342_QUEUE_FILE, {"schema": PAPER_V342_SCHEMA, "updated_ts": now_ts, "queue": q})
        save_json_file(PAPER_V342_HISTORY_FILE, [dict(x) for x in list(V342_HISTORY or [])[-V342_MAX_HISTORY:] if isinstance(x, dict)])
        proc = V342_STATE.get("processed", {}) if isinstance(V342_STATE, dict) else {}
        if isinstance(proc, dict) and len(proc) > 900:
            proc = dict(list(proc.items())[-900:])
        alerted = V342_STATE.get("alerted", {}) if isinstance(V342_STATE, dict) else {}
        if isinstance(alerted, dict):
            alerted = {k: v for k, v in alerted.items() if now_ts - safe_float(v, 0) <= V342_ALERT_COOLDOWN_SEC * 2}
        save_json_file(data_file("paper_good_pullback_state_v342.json"), {
            "schema": PAPER_V342_SCHEMA,
            "updated_ts": now_ts,
            "processed": proc if isinstance(proc, dict) else {},
            "alerted": alerted if isinstance(alerted, dict) else {},
            "last_scan_ts": safe_float(V342_STATE.get("last_scan_ts", 0), 0) if isinstance(V342_STATE, dict) else 0,
        })
    except Exception as e:
        try: append_runtime_error_log("v342_save_state", str(e), exc=e, include_traceback=False)
        except Exception: pass
def _v342_blob(*objs) -> str:
    keys = [
        "ticker", "route", "lane", "easy_lane", "grade", "signal_grade", "original_grade", "mode",
        "trigger", "source", "paper_type", "entry_rule", "paper_entry_rule_v259", "v270_entry_rule",
        "v266_entry_rule", "v326_route_class", "decision", "final_decision", "signal_decision",
        "register_reason", "reason", "why", "primary_reason", "close_reason", "cancel_reason",
        "trace_reason", "watch_reason", "result_type", "status", "note", "v312_route", "v313_route", "v314_route",
    ]
    parts = []
    try:
        for obj in objs:
            if isinstance(obj, dict):
                for k in keys:
                    v = obj.get(k)
                    if v not in (None, "", [], {}):
                        parts.append(str(v))
                try:
                    parts.extend([str(x) for x in list(obj.get("reasons", []) or [])[:8]])
                except Exception:
                    pass
            elif obj is not None:
                parts.append(str(obj))
    except Exception:
        pass
    return " / ".join(parts)[:4000]
def _v342_is_good_pullback_route(row: dict = None, ctx: dict = None, trigger: str = "") -> tuple[bool, str]:
    """성과가 좋았던 눌림 route만 인식한다. PULLBACK_WAIT 전체 복구가 아니다."""
    try:
        blob = _v342_blob(row if isinstance(row, dict) else {}, ctx if isinstance(ctx, dict) else {}, trigger)
        b = blob.lower()
        if "cancel_reentry_forced_v313" in b:
            if any(x in b for x in ["pullback", "눌림", "눌림형", "눌림감시", "v313_p"]):
                return True, "v313_pullback_good_route"
            return False, "v313_not_pullback"
        if "cancel_watch_force_v313" in b and any(x in b for x in ["pullback", "눌림", "눌림감시"]):
            return True, "v313_cancel_watch_pullback"
        if str(trigger or "").lower().startswith("v313") and any(x in b for x in ["mode / pullback", "pullback", "눌림", "눌림감시", "눌림 재진입"]):
            return True, "v313_state_pullback"
        if "strong_reentry_pullback" in b:
            return True, "strong_reentry_pullback_route"
        if "pullback_watch_v311" in b or "cancel_pullback_v312" in b:
            return True, "old_strong_miss_pullback_route"
        if ("강한놓침" in blob or "강한 놓침" in blob or "취소후 강한놓침" in blob) and any(x in blob for x in ["눌림감시", "눌림 재진입", "눌림형", "추격금지"]):
            return True, "strong_miss_pullback_korean"
        if any(x in blob for x in ["취소 후 재출발 눌림", "취소후 재출발 눌림", "취소후 눌림재진입", "눌림 재진입 감시"]):
            return True, "cancel_restart_pullback"
        return False, "not_good_pullback_route"
    except Exception:
        return False, "route_check_error"
def _v342_central_row_for_ticker(ticker: str) -> tuple:
    try:
        t = str(ticker or "").upper().strip()
        if not t:
            return {}, "missing", 0, ["no_ticker"]
        if callable(globals().get("_v337_get_central_entry_row")):
            return _v337_get_central_entry_row(t, allow_refresh=True)
    except Exception as e:
        try: append_runtime_error_log("v342_central_row", str(e), exc=e, include_traceback=False)
        except Exception: pass
    return {}, "missing", 0, ["central_missing"]
def _v342_origin_route(row: dict = None, ctx: dict = None, fallback: str = "v342_good_pullback_reconfirm") -> str:
    try:
        for obj in [ctx if isinstance(ctx, dict) else {}, row if isinstance(row, dict) else {}]:
            for k in ["lane", "route", "easy_lane", "v326_route_class", "trigger"]:
                v = str(obj.get(k, "") or "").strip()
                if v:
                    return v[:120]
    except Exception:
        pass
    return fallback
def _v342_enqueue_good_pullback(row: dict, ctx: dict = None, trigger: str = "", reason: str = "") -> bool:
    global V342_QUEUE
    try:
        row = row if isinstance(row, dict) else {}
        ctx = ctx if isinstance(ctx, dict) else {}
        ok, why = _v342_is_good_pullback_route(row, ctx, trigger)
        if not ok:
            return False
        ticker = _v342_ticker(ctx) or _v342_ticker(row)
        if not ticker:
            return False
        try:
            if callable(globals().get("_v336_has_active_ticker")) and _v336_has_active_ticker(ticker):
                _v342_inc("enqueue_duplicate", f"이미진행중 {ticker}")
                return False
        except Exception:
            pass
        central, src, ts, invalid = _v342_central_row_for_ticker(ticker)
        if not isinstance(central, dict) or not central:
            _v342_inc("central_missing", f"중앙row없음 {ticker}")
            return False
        if invalid and any("stale" in str(x).lower() or "오래" in str(x) or "old" in str(x).lower() for x in invalid):
            _v342_inc("central_stale", f"중앙row오래됨 {ticker}")
            return False
        now_ts = _v342_now()
        price = safe_float(central.get("current_price", central.get("price", central.get("last_price", 0))), 0)
        if price <= 0:
            try:
                price = _v340_price(central) if callable(globals().get("_v340_price")) else 0
            except Exception:
                price = 0
        origin = _v342_origin_route(row, ctx)
        rec = V342_QUEUE.get(ticker)
        if isinstance(rec, dict):
            rec["last_seen_ts"] = now_ts
            rec["seen_count"] = int(safe_float(rec.get("seen_count", 1), 1)) + 1
            rec["last_reason"] = str(reason or why)[:180]
            V342_QUEUE[ticker] = rec
            _v342_inc("enqueue_duplicate", f"눌림대기실중복 {ticker}")
            _v342_save_state()
            return True
        if len(V342_QUEUE or {}) >= V342_MAX_QUEUE:
            old = sorted((V342_QUEUE or {}).items(), key=lambda kv: safe_float((kv[1] or {}).get("first_ts", now_ts), now_ts))[:10]
            for old_t, old_rec in old[:max(1, len(V342_QUEUE) - V342_MAX_QUEUE + 1)]:
                V342_QUEUE.pop(old_t, None)
        rec = {
            "schema": PAPER_V342_SCHEMA,
            "ticker": ticker,
            "first_ts": now_ts,
            "last_seen_ts": now_ts,
            "next_check_ts": now_ts + V342_FIRST_CHECK_SEC,
            "deadline_ts": now_ts + V342_SECOND_CHECK_SEC,
            "expire_ts": now_ts + V342_MAX_KEEP_SEC,
            "start_price": price,
            "last_price": price,
            "best_pct": 0.0,
            "checks": 0,
            "status": "WAIT_PULLBACK_RECHECK",
            "route": origin,
            "origin_route": origin,
            "reason": str(reason or why)[:240],
            "why": why,
            "source": str(trigger or "v342")[:80],
            "central_source": str(src or "factory_stage2")[:80],
            "grade": "PULLBACK_WAIT",
            "entry_rule": "pullback",
        }
        V342_QUEUE[ticker] = rec
        _v342_inc("enqueue", f"좋은눌림대기실 {ticker}/{why}")
        if "v313" in why or "v313" in origin:
            _v342_inc("enqueue_v313")
        elif "watch" in str(trigger).lower() or "review" in str(trigger).lower():
            _v342_inc("enqueue_review")
        else:
            _v342_inc("enqueue_register")
        _v342_save_state()
        return True
    except Exception as e:
        try: append_runtime_error_log("v342_enqueue_good_pullback", str(e), exc=e, include_traceback=False)
        except Exception: pass
        return False
def _v342_eval_pullback_recheck(rec: dict, row: dict) -> tuple[str, str, dict]:
    try:
        now_ts = _v342_now()
        price = safe_float(row.get("current_price", row.get("price", row.get("last_price", 0))), 0)
        if price <= 0 and callable(globals().get("_v340_price")):
            price = _v340_price(row)
        start = safe_float((rec or {}).get("start_price", 0), 0)
        if start <= 0:
            start = price
        pct = ((price - start) / start * 100.0) if start > 0 and price > 0 else 0.0
        age = now_ts - safe_float((rec or {}).get("first_ts", now_ts), now_ts)
        blob = _v342_blob(row, rec)
        b = blob.lower()
        grade = str(row.get("grade", row.get("signal_grade", "")) or "").upper()
        chg1 = safe_float(row.get("change_1", row.get("change_1m", 0)), 0)
        chg3 = safe_float(row.get("change_3", row.get("change_3m", 0)), 0)
        chg5 = safe_float(row.get("change_5", row.get("change_5m", 0)), 0)
        buy_ratio = safe_float(row.get("ws_trade_buy_ratio_60s", row.get("buy_ratio", 0)), 0)
        trade_count = int(safe_float(row.get("ws_trade_count_60s", row.get("trade_count", 0)), 0))
        severe = pct <= -2.20 or chg5 <= -1.70 or chg3 <= -1.20
        sell_reversal = any(x in blob for x in ["매도반전", "식는 체결", "식는중", "진짜버림", "늦은진입 차단"])
        route_ok, why = _v342_is_good_pullback_route(row, rec, "eval")
        route_ok = route_ok or bool((rec or {}).get("why"))
        flow_ok = (trade_count >= 5 and buy_ratio >= 38) or buy_ratio >= 55
        detail = {"price": price, "pct": pct, "age": age, "grade": grade, "chg1": chg1, "chg3": chg3, "chg5": chg5, "buy_ratio": buy_ratio, "trade_count": trade_count, "route_ok": route_ok, "flow_ok": flow_ok, "severe": severe, "sell_reversal": sell_reversal}
        if age < V342_FIRST_CHECK_SEC:
            return "WAIT", "30초 확인 전", detail
        if severe:
            return "DEAD_PULLBACK", "성과좋던 눌림 route지만 현재 급약화 → 복기", detail
        if sell_reversal and not (pct >= 0.25 or flow_ok):
            if age >= V342_SECOND_CHECK_SEC:
                return "REVIEW", "매도반전/식는 체결 유지 → 복기", detail
            return "WAIT", "매도반전 표시, 90초까지 재확인", detail
        if route_ok and (grade == "PULLBACK_WAIT" or pct >= -0.65 or flow_ok):
            return "REUPGRADE_PULLBACK", "성과좋던 눌림 route 30초 생존 → 눌림대기 연결", detail
        if age >= V342_SECOND_CHECK_SEC:
            return "REVIEW", "90초 안에 눌림 route 생존 확인 실패", detail
        return "WAIT", "눌림 route 유지 애매 → 다음 확인", detail
    except Exception as e:
        return "WAIT", f"평가오류 {e.__class__.__name__}", {}
def _v342_send_pullback_alert(row: dict, rec: dict, detail: dict):
    try:
        ticker = _v342_ticker(row) or str((rec or {}).get("ticker", ""))
        if not ticker:
            return
        now_ts = _v342_now()
        alerted = V342_STATE.setdefault("alerted", {})
        last = safe_float(alerted.get(ticker, 0), 0) if isinstance(alerted, dict) else 0
        if now_ts - last < V342_ALERT_COOLDOWN_SEC:
            _v342_inc("alert_skip_cooldown", f"눌림알림쿨다운 {ticker}")
            return
        price = safe_float(detail.get("price", 0), 0)
        pct = safe_float(detail.get("pct", 0), 0)
        route = str((rec or {}).get("origin_route", (rec or {}).get("route", "성과좋던 눌림 route")) or "")
        lines = [
            "🟡 눌림대기 신호",
            f"코인: {ticker}",
            f"유형: 성과 좋던 눌림 route 재확인 통과",
            f"현재가: {fmt_price(price) if callable(globals().get('fmt_price')) else price}",
            f"30초 확인: {pct:+.2f}%",
            f"route: {route[:80]}",
            "뜻: 바로 시장가 매수 신호 아님. 눌림/재출발 확인용.",
        ]
        if callable(globals().get("send")):
            send("\n".join(lines))
            alerted[ticker] = now_ts
            _v342_inc("alert_sent", f"눌림대기알림 {ticker}")
            _v342_save_state()
    except Exception as e:
        try: append_runtime_error_log("v342_send_pullback_alert", str(e), exc=e, include_traceback=False)
        except Exception: pass
def _v342_process_queue(force: bool = False) -> int:
    global V342_QUEUE, V342_HISTORY
    processed = 0
    try:
        now_ts = _v342_now()
        for t, rec in list((V342_QUEUE or {}).items()):
            if not isinstance(rec, dict):
                V342_QUEUE.pop(t, None)
                continue
            if not force and now_ts < safe_float(rec.get("next_check_ts", 0), 0):
                continue
            if now_ts > safe_float(rec.get("expire_ts", now_ts + V342_MAX_KEEP_SEC), now_ts + V342_MAX_KEEP_SEC):
                rec["status"] = "EXPIRED"
                rec["closed_ts"] = now_ts
                V342_HISTORY.append(dict(rec)); V342_HISTORY = V342_HISTORY[-V342_MAX_HISTORY:]
                V342_QUEUE.pop(t, None)
                _v342_inc("review_move", f"눌림대기만료 {t}")
                processed += 1
                continue
            row, src, ts, invalid = _v342_central_row_for_ticker(t)
            if not isinstance(row, dict) or not row:
                rec["next_check_ts"] = min(now_ts + V342_MIN_RETRY_GAP_SEC, safe_float(rec.get("deadline_ts", now_ts + V342_SECOND_CHECK_SEC), now_ts + V342_SECOND_CHECK_SEC))
                V342_QUEUE[t] = rec
                _v342_inc("central_missing", f"대기실중앙없음 {t}")
                continue
            if invalid and any("stale" in str(x).lower() or "오래" in str(x) or "old" in str(x).lower() for x in invalid):
                rec["next_check_ts"] = min(now_ts + V342_MIN_RETRY_GAP_SEC, safe_float(rec.get("deadline_ts", now_ts + V342_SECOND_CHECK_SEC), now_ts + V342_SECOND_CHECK_SEC))
                V342_QUEUE[t] = rec
                _v342_inc("central_stale", f"대기실중앙오래됨 {t}")
                continue
            status, reason, detail = _v342_eval_pullback_recheck(rec, row)
            rec["checks"] = int(safe_float(rec.get("checks", 0), 0)) + 1
            rec["last_check_ts"] = now_ts
            rec["last_check_status"] = status
            rec["last_check_reason"] = str(reason)[:180]
            rec["last_price"] = safe_float(detail.get("price", 0), safe_float(rec.get("last_price", 0), 0))
            rec["best_pct"] = max(safe_float(rec.get("best_pct", 0), 0), safe_float(detail.get("pct", 0), 0))
            if safe_float(detail.get("age", 0), 0) >= V342_FIRST_CHECK_SEC:
                _v342_inc("check_30s", f"눌림30초 {t}/{status}")
            if safe_float(detail.get("age", 0), 0) >= V342_SECOND_CHECK_SEC:
                _v342_inc("check_90s", f"눌림90초 {t}/{status}")
            if status == "REUPGRADE_PULLBACK":
                enriched = dict(row or {})
                origin = str(rec.get("origin_route", rec.get("route", "v342_good_pullback_reconfirm")) or "")
                route = origin if any(x in origin for x in ["cancel_reentry_forced_v313", "pullback_watch", "cancel_pullback", "strong_reentry_pullback"]) else "v342_good_pullback_reconfirm"
                enriched.update({
                    "ticker": t,
                    "v342_good_pullback_ok": True,
                    "v342_good_pullback_reason": reason,
                    "v342_origin_route": origin,
                    "v342_start_price": rec.get("start_price"),
                    "v342_recheck_pct": safe_float(detail.get("pct", 0), 0),
                    "v342_wait_age_sec": safe_float(detail.get("age", 0), 0),
                    "grade": "PULLBACK_WAIT",
                    "signal_grade": "PULLBACK_WAIT",
                    "paper_entry_rule_v259": "pullback",
                    "v270_entry_rule": "pullback",
                    "decision": "성과좋던 눌림 route 재확인 통과",
                    "final_decision": "성과좋던 눌림 route 재확인 통과",
                    "route": route,
                    "lane": route,
                    "primary_reason": f"v342 성과좋던 눌림 route 복구: {origin[:100]}",
                })
                _v342_inc("reupgrade_try", f"눌림재승격시도 {t}")
                ok = False
                try:
                    ok = bool(_BASE_PAPER_REGISTER_V342(enriched, trigger="v342_pullback_reconfirm")) if callable(globals().get("_BASE_PAPER_REGISTER_V342")) else False
                except Exception as e:
                    try: append_runtime_error_log("v342_reupgrade_register", str(e), exc=e, include_traceback=False)
                    except Exception: pass
                if ok:
                    rec["status"] = "REUPGRADED_PULLBACK"
                    rec["closed_ts"] = now_ts
                    V342_HISTORY.append(dict(rec)); V342_HISTORY = V342_HISTORY[-V342_MAX_HISTORY:]
                    V342_QUEUE.pop(t, None)
                    _v342_inc("reupgrade_success", f"눌림재승격성공 {t}")
                    _v342_send_pullback_alert(enriched, rec, detail)
                else:
                    rec["status"] = "REUPGRADE_REJECTED"
                    rec["next_check_ts"] = min(now_ts + V342_MIN_RETRY_GAP_SEC, safe_float(rec.get("deadline_ts", now_ts + V342_SECOND_CHECK_SEC), now_ts + V342_SECOND_CHECK_SEC))
                    V342_QUEUE[t] = rec
                    _v342_inc("reupgrade_reject", f"눌림재승격거절 {t}")
                processed += 1
            elif status == "DEAD_PULLBACK":
                rec["status"] = "DEAD_PULLBACK"
                rec["closed_ts"] = now_ts
                V342_HISTORY.append(dict(rec)); V342_HISTORY = V342_HISTORY[-V342_MAX_HISTORY:]
                V342_QUEUE.pop(t, None)
                _v342_inc("dead_pullback", f"죽은눌림복기 {t}")
                processed += 1
            elif status == "REVIEW":
                rec["status"] = "REVIEW_ONLY"
                rec["closed_ts"] = now_ts
                V342_HISTORY.append(dict(rec)); V342_HISTORY = V342_HISTORY[-V342_MAX_HISTORY:]
                V342_QUEUE.pop(t, None)
                _v342_inc("review_move", f"눌림복기전환 {t}")
                processed += 1
            else:
                rec["status"] = "WAIT_PULLBACK_RECHECK"
                rec["next_check_ts"] = min(now_ts + V342_MIN_RETRY_GAP_SEC, safe_float(rec.get("deadline_ts", now_ts + V342_SECOND_CHECK_SEC), now_ts + V342_SECOND_CHECK_SEC))
                V342_QUEUE[t] = rec
                processed += 1
        if processed:
            _v342_inc("process", f"눌림대기실처리 {processed}")
        _v342_save_state()
    except Exception as e:
        try: append_runtime_error_log("v342_process_queue", str(e), exc=e, include_traceback=False)
        except Exception: pass
    return processed
try:
    _BASE_PAPER_CLASSIFY_V342 = globals().get('_paper_classify_for_register_v258')
except Exception:
    _BASE_PAPER_CLASSIFY_V342 = None
def _paper_classify_for_register_v258(row: dict):
    try:
        if isinstance(row, dict) and bool(row.get("v342_good_pullback_ok")):
            cls = dict(row)
            t = _v342_ticker(row)
            if t:
                cls["ticker"] = t
            cls["grade"] = "PULLBACK_WAIT"
            cls["signal_grade"] = "PULLBACK_WAIT"
            cls["decision"] = str(row.get("decision") or "성과좋던 눌림 route 재확인 통과")
            cls["paper_entry_rule_v259"] = "pullback"
            cls["paper_original_grade"] = "PULLBACK_WAIT"
            cls["score"] = safe_float(row.get("score", row.get("snapshot_rank_score", 0)), 0)
            cls["money_amount"] = safe_float(row.get("money_amount", row.get("turnover", row.get("trade_amount", 0))), 0)
            cls["trade_count"] = int(safe_float(row.get("trade_count", row.get("ws_trade_count_60s", 0)), 0))
            cls["buy_ratio"] = safe_float(row.get("buy_ratio", row.get("ws_trade_buy_ratio_60s", 0)), 0)
            route = str(row.get("route") or row.get("lane") or "v342_good_pullback_reconfirm")
            _v342_inc("classify_override", f"v342눌림분류통과 {cls.get('ticker')}")
            return True, route, str(row.get("v342_good_pullback_reason") or "v342 성과좋던 눌림 route 재확인 통과"), cls
    except Exception:
        pass
    if callable(_BASE_PAPER_CLASSIFY_V342):
        return _BASE_PAPER_CLASSIFY_V342(row)
    return False, "v342_classify_missing", "기존 분류기 없음", {}
try:
    _BASE_PAPER_REGISTER_V342 = globals().get('paper_register_candidate_v258')
except Exception:
    _BASE_PAPER_REGISTER_V342 = None
def paper_register_candidate_v258(row: dict, trigger: str = "auto") -> bool:
    """v342: 기존 조건은 유지하고, 성과 좋던 눌림 route만 대기실→재확인으로 되살린다."""
    try:
        ok = bool(_BASE_PAPER_REGISTER_V342(row, trigger=trigger)) if callable(_BASE_PAPER_REGISTER_V342) else False
        if ok:
            return True
        if str(trigger or "") == "v342_pullback_reconfirm":
            return False
        _v342_inc("register_seen", f"등록거절확인 {_v342_ticker(row)}")
        if _v342_is_good_pullback_route(row if isinstance(row, dict) else {}, {}, trigger)[0]:
            _v342_inc("register_good", f"좋은눌림route거절 {_v342_ticker(row)}")
            _v342_enqueue_good_pullback(row if isinstance(row, dict) else {}, {}, trigger=f"register:{trigger}", reason="register_reject_good_pullback")
        _v342_process_queue(force=False)
        return False
    except Exception as e:
        try: append_runtime_error_log("paper_register_candidate_v342", str(e), exc=e, include_traceback=True)
        except Exception: pass
        try:
            return bool(_BASE_PAPER_REGISTER_V342(row, trigger=trigger)) if callable(_BASE_PAPER_REGISTER_V342) else False
        except Exception:
            return False
def _v342_row_key(row: dict, prefix: str = "") -> str:
    try:
        t = _v342_ticker(row)
        ts = safe_float((row or {}).get("registered_ts", (row or {}).get("created_ts", (row or {}).get("closed_at", (row or {}).get("saved_at", (row or {}).get("ts", 0))))), 0)
        return f"{prefix}:{t}:{int(ts)}:{str((row or {}).get('key',''))[:40]}"
    except Exception:
        return f"{prefix}:unknown:{int(_v342_now())}"
def _v342_mark_processed(key: str):
    try:
        V342_STATE.setdefault("processed", {})[str(key)] = _v342_now()
    except Exception:
        pass
def _v342_is_processed(key: str) -> bool:
    try:
        return str(key) in (V342_STATE.get("processed", {}) if isinstance(V342_STATE, dict) else {})
    except Exception:
        return False
def _v342_scan_good_pullback_sources(force: bool = False) -> int:
    """v313/review_watch에 남아 있던 성과 좋던 눌림 route를 새 paper 경로로 되살린다."""
    linked = 0
    try:
        now_ts = _v342_now()
        if not force and now_ts - safe_float(V342_STATE.get("last_scan_ts", 0), 0) < 18.0:
            return 0
        V342_STATE["last_scan_ts"] = now_ts
        _v342_inc("scan", "v342 좋은눌림 route 스캔")
        rows = []
        try:
            if callable(globals().get("_v313_active_queue_rows")):
                for r in list(_v313_active_queue_rows(limit=30) or []):
                    if isinstance(r, dict):
                        rows.append(("v313", r))
                        _v342_inc("v313_rows_seen")
        except Exception:
            pass
        try:
            active, logs = _get_internal_watch_state_parts() if callable(globals().get("_get_internal_watch_state_parts")) else ({}, [])
            active_rows = [x for x in (active.values() if isinstance(active, dict) else []) if isinstance(x, dict)]
            for r in active_rows[:20]:
                rows.append(("review_active", r)); _v342_inc("watch_rows_seen")
            try:
                log_rows = dedupe_internal_watch_logs(logs) if callable(globals().get("dedupe_internal_watch_logs")) else logs
            except Exception:
                log_rows = logs
            log_rows = [x for x in (log_rows or []) if isinstance(x, dict)]
            log_rows = sorted(log_rows, key=lambda x: safe_float(x.get("closed_at", x.get("saved_at", 0)), 0), reverse=True)[:30]
            for r in log_rows:
                rows.append(("review_log", r)); _v342_inc("watch_rows_seen")
        except Exception:
            pass
        for src, r in rows[:80]:
            key = _v342_row_key(r, src)
            if _v342_is_processed(key):
                continue
            ok, why = _v342_is_good_pullback_route(r, {}, src)
            if not ok:
                continue
            if _v342_enqueue_good_pullback(r, {}, trigger=src, reason=why):
                linked += 1
                _v342_mark_processed(key)
        if linked:
            _v342_save_state()
            _v342_process_queue(force=False)
        else:
            _v342_save_state()
    except Exception as e:
        try: append_runtime_error_log("v342_scan_good_pullback_sources", str(e), exc=e, include_traceback=False)
        except Exception: pass
    return linked
