def _v343_process_queue(force: bool = False) -> int:
    global V343_QUEUE, V343_HISTORY
    processed = 0
    direct_count = 0
    try:
        now_ts = _v343_now()
        for t, rec in list((V343_QUEUE or {}).items()):
            if direct_count >= V343_MAX_DIRECT_PER_CYCLE:
                break
            if not isinstance(rec, dict):
                V343_QUEUE.pop(t, None)
                continue
            if not force and now_ts < safe_float(rec.get("next_check_ts", 0), 0):
                continue
            age = now_ts - safe_float(rec.get("first_ts", now_ts), now_ts)
            if age > V343_MAX_KEEP_SEC:
                rec["status"] = "EXPIRED_REVIEW"; rec["closed_ts"] = now_ts
                V343_HISTORY.append(dict(rec)); V343_HISTORY = V343_HISTORY[-V343_MAX_HISTORY:]
                V343_QUEUE.pop(t, None)
                _v343_inc("review_move", f"눌림복구만료 {t}")
                processed += 1
                continue
            row, src, ts, invalid = _v343_central_row(t)
            if not isinstance(row, dict) or not row:
                rec["status"] = "WAIT_CENTRAL_ROW"
                rec["next_check_ts"] = now_ts + min(18.0, max(5.0, V343_FIRST_CHECK_SEC))
                V343_QUEUE[t] = rec
                _v343_inc("central_missing_wait", f"중앙대기 {t}")
                continue
            if invalid and any("stale" in str(x).lower() or "오래" in str(x) or "old" in str(x).lower() for x in invalid):
                rec["status"] = "WAIT_FRESH_CENTRAL"
                rec["next_check_ts"] = now_ts + min(18.0, max(5.0, V343_FIRST_CHECK_SEC))
                V343_QUEUE[t] = rec
                _v343_inc("central_stale_wait", f"중앙최신대기 {t}")
                continue
            price = safe_float(row.get("current_price", row.get("price", row.get("last_price", 0))), 0)
            start = safe_float(rec.get("start_price", price), price)
            pct = ((price - start) / start) * 100.0 if start > 0 and price > 0 else 0.0
            chg5 = safe_float(row.get("change_5", row.get("change_5m", 0)), 0)
            blob = _v343_blob(row, rec)
            sell_reversal = any(x in blob for x in ["매도반전", "식는 체결", "진짜버림", "늦은진입 차단"])
            severe = pct <= -2.20 or chg5 <= -1.70
            rec["last_price"] = price
            rec["best_pct"] = max(safe_float(rec.get("best_pct", 0), 0), pct)
            rec["checks"] = int(safe_float(rec.get("checks", 0), 0)) + 1
            if age >= V343_FIRST_CHECK_SEC:
                _v343_inc("check_12s", f"12초확인 {t}")
            if age >= V343_SECOND_CHECK_SEC:
                _v343_inc("check_35s", f"35초확인 {t}")
            if severe:
                rec["status"] = "DEAD_PULLBACK"; rec["closed_ts"] = now_ts; rec["last_reason"] = "급약화 복기"
                V343_HISTORY.append(dict(rec)); V343_HISTORY = V343_HISTORY[-V343_MAX_HISTORY:]
                V343_QUEUE.pop(t, None)
                _v343_inc("dead_pullback", f"급약화복기 {t}")
                processed += 1
                continue
            if age < V343_FIRST_CHECK_SEC:
                rec["status"] = "WAIT_FIRST_CHECK"; rec["next_check_ts"] = now_ts + max(3.0, V343_FIRST_CHECK_SEC - age)
                V343_QUEUE[t] = rec
                continue
            if sell_reversal and age < V343_SECOND_CHECK_SEC and pct < 0.10:
                rec["status"] = "WAIT_SELL_REVERSAL_HOLD"; rec["next_check_ts"] = now_ts + 8.0
                V343_QUEUE[t] = rec
                processed += 1
                continue
            _v343_inc("direct_try", f"눌림직접복구시도 {t}")
            if _v343_direct_pending(rec, row, src):
                rec["status"] = "DIRECT_PENDING"; rec["closed_ts"] = now_ts; rec["last_reason"] = "v343 직접 PENDING 연결"
                V343_HISTORY.append(dict(rec)); V343_HISTORY = V343_HISTORY[-V343_MAX_HISTORY:]
                V343_QUEUE.pop(t, None)
                processed += 1
                direct_count += 1
            else:
                rec["status"] = "DIRECT_WAIT_RETRY"; rec["next_check_ts"] = now_ts + 15.0
                V343_QUEUE[t] = rec
                processed += 1
        if processed:
            _v343_save_state()
    except Exception as e:
        try: append_runtime_error_log("v343_process_queue", str(e), exc=e, include_traceback=False)
        except Exception: pass
    return processed
def _v343_cycle(force: bool = False):
    try:
        _v343_scan_sources(force=force)
        _v343_process_queue(force=force)
    except Exception as e:
        try: append_runtime_error_log("v343_cycle", str(e), exc=e, include_traceback=False)
        except Exception: pass
