def _v337_get_central_entry_row(ticker: str, allow_refresh: bool = True) -> tuple:
    if callable(_BASE_V337_GET_CENTRAL_ENTRY_ROW_V344):
        row, src, ts, invalid = _BASE_V337_GET_CENTRAL_ENTRY_ROW_V344(ticker, allow_refresh=allow_refresh)
    else:
        row, src, ts, invalid = {}, "missing", 0.0, ["central_hub_missing"]
    try:
        if (not isinstance(row, dict) or not row) or invalid:
            _v344_record_row_only(ticker, {}, src=src, invalid=invalid)
    except Exception:
        pass
    return row, src, ts, invalid
