def _v337_build_entry_context(row: dict, trigger: str = "") -> tuple:
    ctx, merged, invalid = _BASE_V337_BUILD_ENTRY_CONTEXT_V344(row if isinstance(row, dict) else {}, trigger=trigger) if callable(_BASE_V337_BUILD_ENTRY_CONTEXT_V344) else ({}, dict(row or {}) if isinstance(row, dict) else {}, ["v344_no_base_context"])
    try:
        if invalid or str((ctx or {}).get("context_source", "")).lower() in {"central_missing", "missing", "missing_ticker"}:
            ok, why = _v344_is_good_pullback_source(row if isinstance(row, dict) else {}, trigger)
            _v344_record_row_only(_v344_ticker(row), row if isinstance(row, dict) else {}, src=str((ctx or {}).get("context_source", "")), invalid=invalid, good_pullback=ok)
            if ok and isinstance(ctx, dict):
                ctx["v344_good_pullback_row_only_wait"] = True
                ctx["v344_good_pullback_reason"] = str(why)[:180]
    except Exception:
        pass
    return ctx, merged, invalid
def _v344_collect_sources() -> list:
    rows = []
    try:
        for src, r in list(_v343_collect_sources() if callable(globals().get("_v343_collect_sources")) else []):
            if isinstance(r, dict):
                rows.append(("v343_" + str(src), r))
                if "cancel" in str(src): _v344_inc("source_cancel")
                elif "v313" in str(src): _v344_inc("source_v313")
                elif "review" in str(src): _v344_inc("source_review")
    except Exception:
        pass
    try:
        rows_file = _v339_load_rows() if callable(globals().get("_v339_load_rows")) else []
        for r in list(rows_file or [])[-V344_MAX_SOURCE_ROWS:]:
            if isinstance(r, dict):
                rows.append(("paper_log", r)); _v344_inc("source_paper")
    except Exception:
        pass
    try:
        attempts = _v339_load_attempts() if callable(globals().get("_v339_load_attempts")) else []
        for r in list(attempts or [])[-V344_MAX_SOURCE_ROWS:]:
            if isinstance(r, dict):
                rows.append(("paper_attempt", r)); _v344_inc("source_attempt")
    except Exception:
        pass
    try:
        active, logs = _get_internal_watch_state_parts() if callable(globals().get("_get_internal_watch_state_parts")) else ({}, [])
        for r in list((active or {}).values())[:80] if isinstance(active, dict) else []:
            if isinstance(r, dict): rows.append(("internal_active", r)); _v344_inc("source_review")
        for r in list(logs or [])[-160:]:
            if isinstance(r, dict): rows.append(("internal_log", r)); _v344_inc("source_review")
    except Exception:
        pass
    try:
        for r in list(globals().get("COMMAND_DISPLAY_CACHE_LAST_RANK_ROWS", []) or [])[-120:]:
            if isinstance(r, dict): rows.append(("rank_cache_diagnostic", r)); _v344_inc("source_rank")
    except Exception:
        pass
    return rows
def _v344_force_good_source(row: dict, src: str, why: str) -> bool:
    try:
        row = dict(row or {})
        ticker = _v344_ticker(row)
        if not ticker:
            return False
        row.setdefault("ticker", ticker)
        row["v344_good_pullback_source"] = True
        row["route"] = str(row.get("route", row.get("lane", "")) or "v344_good_pullback_source")
        row["lane"] = str(row.get("lane", row.get("route", "")) or "v344_good_pullback_source")
        row["v344_reason"] = str(why)[:220]
        row["grade"] = str(row.get("grade", row.get("signal_grade", "PULLBACK_WAIT")) or "PULLBACK_WAIT")
        if row["grade"] in {"DISCARD", "UNKNOWN_EXPLICIT", "C", "C등급"}:
            row["grade"] = "PULLBACK_WAIT"
        row["signal_grade"] = row["grade"]
        row.setdefault("final_decision", "v344 좋은 눌림 route 강제수집 / 중앙허브 재확인 대기")
        row.setdefault("decision", row.get("final_decision"))
        _v344_inc("force_try", f"좋은눌림강제수집 {ticker}/{why}")
        ok = False
        if callable(globals().get("_v343_enqueue")):
            ok = bool(_v343_enqueue(row, "v344_" + str(src), why))
        if ok:
            _v344_inc("force_success", f"v343입구투입 {ticker}")
            return True
        _v344_inc("force_fail", f"v343입구실패 {ticker}")
        return False
    except Exception as e:
        _v344_inc("force_fail", f"강제수집오류 {e.__class__.__name__}")
        try: append_runtime_error_log("v344_force_good_source", str(e), exc=e, include_traceback=False)
        except Exception: pass
        return False
def _v344_scan_sources(force: bool = False) -> int:
    linked = 0
    try:
        now_ts = _v344_now()
        if not force and now_ts - safe_float(V344_STATE.get("last_scan_ts", 0), 0) < V344_SCAN_INTERVAL_SEC:
            return 0
        V344_STATE["last_scan_ts"] = now_ts
        _v344_inc("scan", "v344 소스/row_only 스캔")
        count = 0
        for src, row in _v344_collect_sources():
            if count >= V344_MAX_SOURCE_ROWS:
                break
            if not isinstance(row, dict):
                continue
            count += 1
            key = _v344_source_key(row, src)
            if _v344_is_processed(key):
                continue
            blob = _v344_blob(row, src).lower()
            if "row_only" in blob or "central_hub_missing" in blob or "rank_cache_not_allowed" in blob:
                ok_gp, why_gp = _v344_is_good_pullback_source(row, src)
                _v344_record_row_only(_v344_ticker(row), row, src=src, invalid=["row_only_from_source"], good_pullback=ok_gp)
            ok, why = _v344_is_good_pullback_source(row, src)
            if not ok:
                continue
            _v344_inc("good_candidate", f"좋은눌림후보 {_v344_ticker(row)}/{why}")
            if _v344_force_good_source(row, src, why):
                linked += 1
                _v344_mark_processed(key, _v344_ticker(row), why)
                if linked >= V344_MAX_FORCE_PER_CYCLE:
                    break
        _v344_save_state()
    except Exception as e:
        try: append_runtime_error_log("v344_scan_sources", str(e), exc=e, include_traceback=False)
        except Exception: pass
    return linked
def _v344_cycle(force: bool = False):
    try:
        _v344_scan_sources(force=force)
        if callable(globals().get("_v343_process_queue")):
            _v343_process_queue(force=False)
    except Exception as e:
        try: append_runtime_error_log("v344_cycle", str(e), exc=e, include_traceback=False)
        except Exception: pass
