def _v337_build_entry_context(row: dict, trigger: str = "") -> tuple:
    ctx, merged, invalid = ({}, dict(row or {}) if isinstance(row, dict) else {}, ["v345_no_base_context"])
    try:
        if callable(_BASE_V337_BUILD_ENTRY_CONTEXT_V345):
            ctx, merged, invalid = _BASE_V337_BUILD_ENTRY_CONTEXT_V345(row if isinstance(row, dict) else {}, trigger=trigger)
    except Exception as e:
        try: append_runtime_error_log("v345_build_context_base", str(e), exc=e, include_traceback=False)
        except Exception: pass
        ctx, merged, invalid = ({"schema": PAPER_V345_SCHEMA, "error": str(e)[:120]}, dict(row or {}) if isinstance(row, dict) else {}, ["v345_context_base_error"])
    try:
        t = _v345_ticker((ctx or {}).get("ticker") or (merged or {}).get("ticker") or row)
        hint = _v345_find_route_hint(t, row if isinstance(row, dict) else {}, str(trigger or "context"))
        if hint:
            _v345_inc("ctx_patch_try", f"context route보강시도 {t}")
            merged2, ch_m = _v345_enrich_row_with_hint(merged if isinstance(merged, dict) else {}, hint, "merged")
            ctx2, ch_c = _v345_enrich_row_with_hint(ctx if isinstance(ctx, dict) else {}, hint, "ctx")
            if ch_m or ch_c:
                if isinstance(ctx2, dict):
                    if not _v345_missing_text(ctx2.get("route")):
                        ctx2["route"] = str(ctx2.get("route"))[:120]
                    if not _v345_missing_text(ctx2.get("final_decision")):
                        ctx2["final_decision"] = str(ctx2.get("final_decision"))[:180]
                    ctx2["v345_route_decision_boost"] = True
                    ctx2["v345_boost_source"] = str(hint.get("src", "") or "")[:80]
                if isinstance(merged2, dict):
                    merged2["v345_route_decision_boost"] = True
                _v345_apply_hint_to_central_tables(t, hint)
                _v345_record_sample(t, hint, "context", True)
                _v345_inc("ctx_patch_success", f"context route보강 {t}/{hint.get('src','')}")
                return ctx2, merged2, list(dict.fromkeys([str(x) for x in (invalid or []) if x]))
            _v345_inc("ctx_patch_fail", f"context route보강불필요 {t}")
    except Exception as e:
        _v345_inc("ctx_patch_fail", f"context route보강오류 {e.__class__.__name__}")
        try: append_runtime_error_log("v345_context_patch", str(e), exc=e, include_traceback=False)
        except Exception: pass
    return ctx, merged, invalid
def _v336_build_entry_context(row: dict, trigger: str = "") -> tuple:
    try:
        return _v337_build_entry_context(row if isinstance(row, dict) else {}, trigger=trigger)
    except Exception as e:
        try: append_runtime_error_log("v345_v336_build_entry_context", str(e), exc=e, include_traceback=False)
        except Exception: pass
        return {"schema": PAPER_V345_SCHEMA, "error": str(e)[:120], "trigger": str(trigger or "")}, dict(row or {}) if isinstance(row, dict) else {}, ["v345_context_error"]
