def _v346_now() -> float:
    try:
        return time.time()
    except Exception:
        return 0.0
def _v346_inc(key: str, note: str = ""):
    try:
        V346_STATS[key] = int(safe_float(V346_STATS.get(key, 0), 0)) + 1
        if note:
            V346_STATS["last_note"] = str(note)[:260]
    except Exception:
        pass
def _v346_ticker(row=None) -> str:
    try:
        if callable(globals().get("_v345_ticker")):
            return _v345_ticker(row)
        if callable(globals().get("_v343_ticker")):
            return _v343_ticker(row)
    except Exception:
        pass
    try:
        if isinstance(row, str):
            t = row
        elif isinstance(row, dict):
            t = row.get("ticker", row.get("symbol", row.get("market", "")))
        else:
            t = ""
        t = str(t or "").upper().strip()
        if t.startswith("KRW-"):
            t = t.split("-", 1)[1]
        if t.endswith("_KRW"):
            t = t[:-4]
        return t.strip()
    except Exception:
        return ""
def _v346_blob(*objs) -> str:
    try:
        if callable(globals().get("_v345_blob")):
            return _v345_blob(*objs)
    except Exception:
        pass
    parts = []
    try:
        for obj in objs:
            if isinstance(obj, dict):
                for k in ["ticker", "status", "route", "lane", "trigger", "reason", "why", "note", "decision", "final_decision", "signal_decision", "register_reason", "close_reason", "cancel_reason"]:
                    v = obj.get(k)
                    if v not in (None, "", [], {}):
                        parts.append(str(v))
                try: parts.extend([str(x) for x in list(obj.get("reasons", []) or [])[:8]])
                except Exception: pass
            elif obj is not None:
                parts.append(str(obj))
    except Exception:
        pass
    return " / ".join(parts)[:6000]
def _v346_load_state():
    global V346_STATE
    try:
        data = load_json_file(PAPER_V346_STATE_FILE, {})
        if isinstance(data, dict):
            bridged = data.get("bridged", {}) if isinstance(data.get("bridged", {}), dict) else {}
            samples = data.get("samples", []) if isinstance(data.get("samples", []), list) else []
            now_ts = _v346_now()
            clean = {}
            for k, v in list(bridged.items())[-1200:]:
                ts = safe_float((v or {}).get("ts", v if not isinstance(v, dict) else 0), 0) if not isinstance(v, (int, float)) else safe_float(v, 0)
                if ts <= 0 or now_ts - ts <= 4 * 3600:
                    clean[str(k)] = v
            V346_STATE = {"last_scan_ts": safe_float(data.get("last_scan_ts", 0), 0), "bridged": clean, "samples": samples[-V346_MAX_SAMPLES:]}
    except Exception as e:
        try: append_runtime_error_log("v346_load_state", str(e), exc=e, include_traceback=False)
        except Exception: pass
        V346_STATE = {"last_scan_ts": 0.0, "bridged": {}, "samples": []}
def _v346_save_state():
    try:
        samples = V346_STATE.get("samples", []) if isinstance(V346_STATE, dict) else []
        if isinstance(samples, list):
            V346_STATE["samples"] = samples[-V346_MAX_SAMPLES:]
        save_json_file(PAPER_V346_STATE_FILE, {"schema": PAPER_V346_SCHEMA, "updated_ts": _v346_now(), **(V346_STATE if isinstance(V346_STATE, dict) else {})})
    except Exception as e:
        try: append_runtime_error_log("v346_save_state", str(e), exc=e, include_traceback=False)
        except Exception: pass
