def _v343_is_good_pullback_source(row: dict, trigger: str = "") -> tuple:
    try:
        row = row if isinstance(row, dict) else {}
        if bool(row.get("v346_from_v340_pullback_recheck")) or bool(row.get("v346_big_repair")):
            return True, "v346_big_repair_pullback_bridge"
        ok, why = _v346_is_v340_pullback_candidate(row)
        if ok:
            return True, "v346:" + str(why)
    except Exception:
        pass
    try:
        if callable(_BASE_V343_IS_GOOD_PULLBACK_SOURCE_V346):
            return _BASE_V343_IS_GOOD_PULLBACK_SOURCE_V346(row if isinstance(row, dict) else {}, trigger)
    except Exception:
        pass
    return False, "not_good_pullback_v346"
def _v346_live_row_lookup(ticker: str) -> tuple:
    """중앙 row가 빈 껍데기일 때 가격/차트는 실시간 중앙공장/공유캐시에서만 복구한다."""
    t = _v346_ticker(ticker)
    if not t:
        return {}, "missing", 0.0, ["ticker_missing"]
    now_ts = _v346_now()
    try:
        for table_name, src_name, max_age in [
            ("DATA_FACTORY_V294_STAGE2", "factory_stage2_v346", safe_float(globals().get("V337_CENTRAL_MAX_AGE_SEC", 90), 90)),
            ("DATA_FACTORY_V294_STAGE1", "factory_stage1_v346", safe_float(globals().get("V337_CENTRAL_MAX_AGE_SEC", 90), 90)),
        ]:
            table = globals().get(table_name, {})
            if not isinstance(table, dict):
                continue
            row = None
            for k in [t, t.upper(), "KRW-" + t, t + "_KRW"]:
                if isinstance(table.get(k), dict) and table.get(k):
                    row = dict(table.get(k)); break
            if isinstance(row, dict) and row:
                ts = _v337_row_ts(row) if callable(globals().get("_v337_row_ts")) else safe_float(row.get("ts", row.get("updated_ts", 0)), 0)
                price = safe_float(row.get("current_price", row.get("price", row.get("last_price", 0))), 0)
                if price > 0 and (ts <= 0 or now_ts - ts <= max_age * 2.0):
                    row.setdefault("ticker", t)
                    return row, src_name, ts or now_ts, []
    except Exception as e:
        try: append_runtime_error_log("v346_live_row_factory", str(e), exc=e, include_traceback=False)
        except Exception: pass
    try:
        cache = globals().get("shared_market_cache", {})
        if isinstance(cache, dict):
            row = None
            for k in [t, t.upper(), "KRW-" + t, t + "_KRW"]:
                if isinstance(cache.get(k), dict) and cache.get(k):
                    row = dict(cache.get(k)); break
            if isinstance(row, dict) and row:
                ts = safe_float(row.get("ts", row.get("updated_ts", globals().get("shared_market_cache_time", 0))), 0)
                price = safe_float(row.get("current_price", row.get("price", row.get("last_price", 0))), 0)
                if price > 0 and (ts <= 0 or now_ts - ts <= safe_float(globals().get("V337_SHARED_MAX_AGE_SEC", 45), 45) * 3.0):
                    row.setdefault("ticker", t)
                    return row, "shared_market_cache_v346", ts or now_ts, []
    except Exception as e:
        try: append_runtime_error_log("v346_live_row_shared", str(e), exc=e, include_traceback=False)
        except Exception: pass
    return {}, "missing", 0.0, ["central_live_row_missing"]
try:
    _BASE_V343_CENTRAL_ROW_V346 = globals().get('_v343_central_row')
except Exception:
    _BASE_V343_CENTRAL_ROW_V346 = None
def _v343_central_row(ticker: str) -> tuple:
    t = _v346_ticker(ticker)
    row, src, ts, invalid = ({}, "missing", 0.0, ["central_missing"])
    try:
        if callable(_BASE_V343_CENTRAL_ROW_V346):
            row, src, ts, invalid = _BASE_V343_CENTRAL_ROW_V346(t)
    except Exception as e:
        try: append_runtime_error_log("v346_v343_central_base", str(e), exc=e, include_traceback=False)
        except Exception: pass
        row, src, ts, invalid = {}, "missing", 0.0, ["central_error"]
    try:
        hint = _v345_find_route_hint(t, row if isinstance(row, dict) else {}, "v346_central") if callable(globals().get("_v345_find_route_hint")) else {}
        if isinstance(row, dict) and row:
            if hint and callable(globals().get("_v345_enrich_row_with_hint")):
                row2, changed = _v345_enrich_row_with_hint(row, hint, "v346_central")
                if changed:
                    _v346_inc("route_hint_force", f"중앙힌트보강 {t}")
                    row = row2
            price = safe_float(row.get("current_price", row.get("price", row.get("last_price", 0))), 0)
            inv_text = " ".join([str(x).lower() for x in (invalid or [])])
            routeish_bad = any(x in inv_text for x in ["route", "decision", "row_only", "central_hub_missing"]) and not any(x in inv_text for x in ["stale", "old", "오래", "price"])
            if price > 0 and routeish_bad and hint:
                _v346_inc("row_only_repair_success", f"row_only보강해제 {t}")
                return row, src or "v346_repaired_central", ts or _v346_now(), []
            return row, src, ts, invalid
        _v346_inc("central_salvage_try", f"중앙빈row복구 {t}")
        live, lsrc, lts, linvalid = _v346_live_row_lookup(t)
        if isinstance(live, dict) and live:
            hint = _v345_find_route_hint(t, live, "v346_live") if callable(globals().get("_v345_find_route_hint")) else {}
            if hint and callable(globals().get("_v345_enrich_row_with_hint")):
                live2, changed = _v345_enrich_row_with_hint(live, hint, "v346_live")
                live = live2 if isinstance(live2, dict) else live
                if changed:
                    _v346_inc("route_hint_force", f"live힌트보강 {t}")
            _v346_inc("central_salvage_success", f"중앙빈row복구성공 {t}/{lsrc}")
            _v346_mark_sample(t, "central_salvage", lsrc, src)
            return live, lsrc, lts or _v346_now(), list(linvalid or [])
        _v346_inc("central_salvage_fail", f"중앙빈row복구실패 {t}")
    except Exception as e:
        _v346_inc("central_salvage_fail", f"중앙복구오류 {t}/{e.__class__.__name__}")
        try: append_runtime_error_log("v346_v343_central_row", str(e), exc=e, include_traceback=False)
        except Exception: pass
    return row, src, ts, invalid
def _v346_enqueue_to_v343(row: dict, src: str, why: str) -> bool:
    try:
        row = dict(row or {})
        t = _v346_ticker(row)
        if not t:
            return False
        key = _v346_bridge_key(t, src, row)
        if _v346_already_bridged(key):
            _v346_inc("v340_to_v343_duplicate", f"브릿지중복 {t}")
            return False
        row.setdefault("ticker", t)
        row["v346_big_repair"] = True
        row.setdefault("v346_from_v340_pullback_recheck", True)
        row.setdefault("route", "v346_v340_pullback_recheck")
        row.setdefault("lane", "v346_v340_pullback_recheck")
        row.setdefault("signal_grade", "PULLBACK_WAIT")
        row.setdefault("grade", "PULLBACK_WAIT")
        row.setdefault("decision", "바로매수 아님 / 눌림대기 표본 복구")
        row.setdefault("final_decision", "v346 큰 묶음 수리: 눌림대기 연결 복구")
        row.setdefault("register_reason", "v346 큰 묶음 수리: v340/v341 눌림재확인 후보를 v343 PENDING 대기실로 연결")
        _v346_inc("v340_to_v343_try", f"v343연결시도 {t}")
        ok = bool(_v343_enqueue(row, "v346_" + str(src or "bridge"), str(why or "v346_big_repair"))) if callable(globals().get("_v343_enqueue")) else False
        if ok:
            _v346_mark_bridged(key, t, why)
            _v346_inc("v340_to_v343_success", f"v343연결성공 {t}")
            _v346_mark_sample(t, "v340_to_v343", why, src)
            return True
        _v346_inc("v340_to_v343_fail", f"v343연결실패 {t}")
    except Exception as e:
        _v346_inc("v340_to_v343_fail", f"v343연결오류 {e.__class__.__name__}")
        try: append_runtime_error_log("v346_enqueue_to_v343", str(e), exc=e, include_traceback=False)
        except Exception: pass
    return False
def _v346_scan_v340_queue(force: bool = False) -> int:
    count = 0
    try:
        if not force and _v346_now() - safe_float(V346_STATE.get("last_scan_ts", 0), 0) < V346_SCAN_INTERVAL_SEC:
            return 0
        V346_STATE["last_scan_ts"] = _v346_now()
        rows = []
        q = globals().get("V340_QUEUE", {})
        if isinstance(q, dict):
            for t, rec in list(q.items()):
                if isinstance(rec, dict):
                    r = dict(rec); r.setdefault("ticker", t); rows.append(("v340_queue", r))
        h = globals().get("V340_HISTORY", [])
        if isinstance(h, list):
            for rec in list(h)[-80:]:
                if isinstance(rec, dict): rows.append(("v340_history", dict(rec)))
        try:
            active, logs = _get_internal_watch_state_parts() if callable(globals().get("_get_internal_watch_state_parts")) else ({}, [])
            if isinstance(active, dict):
                for r in list(active.values())[-60:]:
                    if isinstance(r, dict): rows.append(("review_active", dict(r)))
            for r in list(logs or [])[-100:]:
                if isinstance(r, dict): rows.append(("review_log", dict(r)))
        except Exception:
            pass
        for src, rec in rows[:220]:
            if count >= V346_MAX_QUEUE_BRIDGE_PER_CYCLE:
                break
            _v346_inc("v340_seen")
            ok, why = _v346_is_v340_pullback_candidate(rec)
            if not ok:
                blob = _v346_blob(rec)
                max_up = 0.0
                try:
                    if callable(globals().get("_v344_extract_watch_result")):
                        max_up, end_up = _v344_extract_watch_result(rec)
                    else:
                        end_up = 0.0
                except Exception:
                    end_up = 0.0
                if any(x in blob for x in ["최종 승격 놓침", "초입/회복 확인 후보", "초입 강세", "강세 후 유지", "재출발 확인"]) and max_up >= 0.70:
                    ok, why = True, f"review_alert_dry_good:{max_up:+.2f}/{end_up:+.2f}"
                    _v346_inc("alert_dry_rescue_try", f"알림마름복구 { _v346_ticker(rec) }")
                else:
                    continue
            t = _v346_ticker(rec)
            row = _v346_row_from_v340_rec(t, rec, why)
            if _v346_enqueue_to_v343(row, src, why):
                count += 1
        if count:
            _v346_save_state()
    except Exception as e:
        try: append_runtime_error_log("v346_scan_v340_queue", str(e), exc=e, include_traceback=False)
        except Exception: pass
    return count
