def _v347_now() -> float:
    try:
        return time.time()
    except Exception:
        return 0.0
def _v347_inc(key: str, note: str = ""):
    try:
        V347_STATS[key] = int(safe_float(V347_STATS.get(key, 0), 0)) + 1
        if note:
            V347_STATS["last_note"] = str(note)[:260]
    except Exception:
        pass
def _v347_ticker(row=None) -> str:
    try:
        if callable(globals().get("_v346_ticker")):
            return _v346_ticker(row)
        if callable(globals().get("_v345_ticker")):
            return _v345_ticker(row)
    except Exception:
        pass
    try:
        if isinstance(row, str):
            t = row
        elif isinstance(row, dict):
            t = row.get("ticker", row.get("symbol", row.get("market", "")))
        else:
            t = ""
        t = str(t or "").upper().strip()
        if t.startswith("KRW-"):
            t = t.split("-", 1)[1]
        if t.endswith("_KRW"):
            t = t[:-4]
        return t.strip()
    except Exception:
        return ""
def _v347_blob(*objs) -> str:
    try:
        if callable(globals().get("_v346_blob")):
            return _v346_blob(*objs)
    except Exception:
        pass
    parts = []
    try:
        for obj in objs:
            if isinstance(obj, dict):
                for k in ["ticker", "status", "route", "lane", "trigger", "reason", "last_reason", "why", "note", "decision", "final_decision", "signal_decision", "register_reason", "close_reason", "cancel_reason", "kind", "grade"]:
                    v = obj.get(k)
                    if v not in (None, "", [], {}):
                        parts.append(str(v))
                try:
                    parts.extend([str(x) for x in list(obj.get("reasons", []) or [])[:8]])
                except Exception:
                    pass
            elif obj is not None:
                parts.append(str(obj))
    except Exception:
        pass
    return " / ".join(parts)[:6000]
def _v347_load_state():
    global V347_STATE
    try:
        data = load_json_file(PAPER_V347_STATE_FILE, {})
        if isinstance(data, dict):
            now_ts = _v347_now()
            bridged = data.get("bridged", {}) if isinstance(data.get("bridged", {}), dict) else {}
            clean = {}
            for k, v in list(bridged.items())[-1500:]:
                ts = safe_float((v or {}).get("ts", 0), 0) if isinstance(v, dict) else safe_float(v, 0)
                if ts <= 0 or now_ts - ts <= 4 * 3600:
                    clean[str(k)] = v
            samples = data.get("samples", []) if isinstance(data.get("samples", []), list) else []
            V347_STATE = {
                "last_scan_ts": safe_float(data.get("last_scan_ts", 0), 0),
                "last_heavy_ts": safe_float(data.get("last_heavy_ts", 0), 0),
                "bridged": clean,
                "samples": samples[-V347_MAX_SAMPLES:],
            }
    except Exception as e:
        try: append_runtime_error_log("v347_load_state", str(e), exc=e, include_traceback=False)
        except Exception: pass
        V347_STATE = {"last_scan_ts": 0.0, "last_heavy_ts": 0.0, "bridged": {}, "samples": []}
def _v347_save_state():
    try:
        samples = V347_STATE.get("samples", []) if isinstance(V347_STATE, dict) else []
        if isinstance(samples, list):
            V347_STATE["samples"] = samples[-V347_MAX_SAMPLES:]
        save_json_file(PAPER_V347_STATE_FILE, {"schema": PAPER_V347_SCHEMA, "updated_ts": _v347_now(), **(V347_STATE if isinstance(V347_STATE, dict) else {})})
    except Exception as e:
        try: append_runtime_error_log("v347_save_state", str(e), exc=e, include_traceback=False)
        except Exception: pass
def _v347_key(src: str, ticker: str, rec: dict) -> str:
    try:
        rec = rec if isinstance(rec, dict) else {}
        t = _v347_ticker(ticker or rec) or "UNKNOWN"
        first_ts = int(safe_float(rec.get("first_ts", rec.get("created_ts", rec.get("ts", rec.get("updated_ts", 0)))), 0))
        status = str(rec.get("status", rec.get("route", rec.get("lane", ""))))[:80]
        return f"{src}:{t}:{first_ts}:{status}"
    except Exception:
        return f"{src}:{_v347_ticker(ticker)}:{int(_v347_now())}"
def _v347_already(key: str) -> bool:
    try:
        return str(key) in (V347_STATE.get("bridged", {}) if isinstance(V347_STATE, dict) else {})
    except Exception:
        return False
def _v347_mark(key: str, ticker: str, why: str):
    try:
        V347_STATE.setdefault("bridged", {})[str(key)] = {"ts": _v347_now(), "ticker": _v347_ticker(ticker), "why": str(why)[:220]}
    except Exception:
        pass
def _v347_sample(ticker: str, kind: str, detail: str = "", src: str = ""):
    try:
        arr = V347_STATE.setdefault("samples", [])
        sample = {"ts": _v347_now(), "ticker": _v347_ticker(ticker), "kind": str(kind)[:80], "detail": str(detail)[:220], "src": str(src)[:80]}
        if isinstance(arr, list):
            arr.append(sample)
            V347_STATE["samples"] = arr[-V347_MAX_SAMPLES:]
    except Exception:
        pass
def _v347_status_kind(rec: dict, src: str = "") -> tuple:
    """실제 v340 대기열/히스토리에서 눌림 연결해야 할 row인지 판단한다. 문턱 강화가 아니라 상태 연결용."""
    try:
        rec = rec if isinstance(rec, dict) else {}
        status = str(rec.get("status", "") or "").upper().strip()
        blob = _v347_blob(rec, src)
        b = blob.lower()
        if status == "PULLBACK_RECHECK":
            _v347_inc("pullback_seen")
            return True, "v340_real_pullback_recheck"
        if status == "WAIT_RECHECK":
            _v347_inc("wait_seen")
            return True, "v340_real_wait_recheck"
        if "pullback_recheck" in b or "눌림재확인" in blob or "눌림 재확인" in blob:
            _v347_inc("history_pullback_seen")
            return True, "v340_history_pullback_text"
        if status in {"EXPIRED", "REVIEW_ONLY", "REUPGRADED"} and any(x in blob for x in ["약화/매도반전 표시", "바로 삭제 대신 눌림", "눌림 재확인"]):
            _v347_inc("history_pullback_seen")
            return True, "v340_history_was_pullback"
        if any(x in b for x in ["preview_command_only", "blocked_v267", "discard"]) and any(x in blob for x in ["고점 재돌파", "유지 확인", "초입", "강세", "순위권 정밀검토"]):
            _v347_inc("wait_seen")
            return True, "renamed_wait_recheck"
    except Exception:
        pass
    return False, "not_v347_bridge"
def _v347_make_pullback_row(ticker: str, rec: dict, why: str, src: str) -> dict:
    try:
        if callable(globals().get("_v346_row_from_v340_rec")):
            row = _v346_row_from_v340_rec(ticker, rec if isinstance(rec, dict) else {}, why)
        else:
            row = dict(rec or {})
        t = _v347_ticker(ticker or row)
        price = safe_float(row.get("last_price", row.get("current_price", row.get("price", row.get("start_price", 0)))), 0)
        row.update({
            "ticker": t,
            "v347_real_queue_bridge": True,
            "v346_big_repair": True,
            "v346_from_v340_pullback_recheck": True,
            "route": "v347_real_v340_pullback_bridge",
            "lane": "v347_real_v340_pullback_bridge",
            "trigger": "v347_real_queue_bridge",
            "signal_grade": "PULLBACK_WAIT",
            "grade": "PULLBACK_WAIT",
            "decision": "바로매수 아님 / 눌림대기 표본 복구",
            "final_decision": "v347 실제 v340 대기열을 v343 눌림대기로 연결",
            "signal_decision": "v347 실제 v340 대기열을 v343 눌림대기로 연결",
            "register_reason": "v347: 실제 V340_RECHECK_QUEUE/HISTORY의 PULLBACK_RECHECK/WAIT_RECHECK 연결",
            "v347_bridge_reason": str(why)[:220],
            "source": str(src or "v340_real_queue")[:80],
            "current_price": price,
            "price": price,
            "last_price": price,
            "reasons": ["v347 실제 v340 대기열→v343 눌림대기 연결", str(why)[:160]],
        })
        return row
    except Exception:
        return {"ticker": _v347_ticker(ticker), "v346_big_repair": True, "v347_real_queue_bridge": True, "route": "v347_real_v340_pullback_bridge", "grade": "PULLBACK_WAIT"}
def _v347_enqueue_v343(row: dict, src: str, why: str) -> bool:
    try:
        t = _v347_ticker(row)
        if not t:
            return False
        key = _v347_key(src, t, row)
        if _v347_already(key):
            _v347_inc("bridge_duplicate", f"중복 {t}")
            return False
        _v347_inc("bridge_try", f"v347연결시도 {t}")
        ok = False
        try:
            if callable(globals().get("_v346_enqueue_to_v343")):
                ok = bool(_v346_enqueue_to_v343(row, "v347_" + str(src or "queue"), why))
            elif callable(globals().get("_v343_enqueue")):
                ok = bool(_v343_enqueue(row, "v347_" + str(src or "queue"), why))
        except Exception as e:
            try: append_runtime_error_log("v347_enqueue_v343_base", str(e), exc=e, include_traceback=False)
            except Exception: pass
            ok = False
        if ok:
            _v347_mark(key, t, why)
            _v347_inc("bridge_success", f"v347연결성공 {t}")
            _v347_sample(t, "bridge_success", why, src)
            return True
        _v347_inc("bridge_fail", f"v347연결실패 {t}")
    except Exception as e:
        _v347_inc("bridge_fail", f"v347연결오류 {e.__class__.__name__}")
        try: append_runtime_error_log("v347_enqueue_v343", str(e), exc=e, include_traceback=False)
        except Exception: pass
    return False
def _v347_scan_real_v340(force: bool = False) -> int:
    linked = 0
    try:
        now_ts = _v347_now()
        if not force and now_ts - safe_float(V347_STATE.get("last_scan_ts", 0), 0) < V347_SCAN_INTERVAL_SEC:
            _v347_inc("skip_throttle")
            return 0
        V347_STATE["last_scan_ts"] = now_ts
        rows = []
        q = globals().get("V340_RECHECK_QUEUE", {})
        if isinstance(q, dict):
            for t, rec in list(q.items()):
                if isinstance(rec, dict):
                    r = dict(rec); r.setdefault("ticker", t); rows.append(("v340_real_queue", r)); _v347_inc("real_queue_seen")
        h = globals().get("V340_RECHECK_HISTORY", [])
        if isinstance(h, list):
            for rec in list(h)[-100:]:
                if isinstance(rec, dict):
                    rows.append(("v340_real_history", dict(rec))); _v347_inc("real_history_seen")
        for src, rec in rows[:240]:
            if linked >= V347_MAX_BRIDGE_PER_CYCLE:
                break
            ok, why = _v347_status_kind(rec, src)
            if not ok:
                continue
            t = _v347_ticker(rec)
            row = _v347_make_pullback_row(t, rec, why, src)
            if _v347_enqueue_v343(row, src, why):
                linked += 1
        if linked > 0:
            _v347_inc("pending_after_bridge", f"v343대기연결 {linked}")
        _v347_save_state()
    except Exception as e:
        try: append_runtime_error_log("v347_scan_real_v340", str(e), exc=e, include_traceback=False)
        except Exception: pass
    return linked
