def send_watch_alert_bundle(header: str, entries, section_key: str = ""):
    try:
        section = str(section_key or "").lower().strip()
        allowed = []
        for entry in list(entries or []):
            item = entry[0] if isinstance(entry, (list, tuple)) and entry else entry
            if not isinstance(item, dict):
                continue
            _v348_mark_record_context(item, section, "watch_bundle")
            ticker = _v348_ticker(item)
            wait_block, wait_reason = _v348_is_wait_or_record_context(item, section, "watch_bundle")
            weak_block, weak_reason = _v348_is_weak_context(item, section, "watch_bundle")
            if wait_block:
                _v348_inc("pending_push_blocked", f"대기성 푸시차단 {ticker}/{wait_reason}")
                _v348_inc("buy_ready_blocked_before_send")
                _v348_sample("pending_push_blocked", ticker, wait_reason)
                continue
            if weak_block:
                key = "data_push_blocked" if weak_reason == "data_bad_text" else "weak_push_blocked"
                _v348_inc(key, f"약한후보 푸시차단 {ticker}/{weak_reason}")
                _v348_inc("buy_ready_blocked_before_send")
                _v348_sample(key, ticker, weak_reason)
                continue
            if section not in V348_ALLOW_USER_SECTIONS:
                _v348_inc("router_drop", f"비사용자섹션 푸시차단 {ticker}/{section or 'none'}")
                _v348_sample("router_drop", ticker, section or "none")
                continue
            _v348_inc("actual_buy_push_try", f"BUY_READY 후보 {ticker}/{section}")
            _v348_inc("buy_ready_before_send")
            allowed.append(entry)
        if not allowed:
            _v348_save_state()
            return None
        _v348_inc("actual_buy_push_allowed", f"BUY_READY 번들 {section} {len(allowed)}개")
        return _BASE_SEND_WATCH_ALERT_BUNDLE_V348(header, allowed, section_key=section_key) if callable(_BASE_SEND_WATCH_ALERT_BUNDLE_V348) else None
    except Exception as e:
        _v348_inc("router_drop", f"watch_bundle 오류 {e.__class__.__name__}")
        try: append_runtime_error_log("v348_send_watch_bundle", str(e), exc=e, include_traceback=False)
        except Exception: pass
        return _BASE_SEND_WATCH_ALERT_BUNDLE_V348(header, entries, section_key=section_key) if callable(_BASE_SEND_WATCH_ALERT_BUNDLE_V348) else None
