def _signal_v257_collect_rows(source_limit: int = None) -> list:
    try:
        source_limit = int(source_limit or globals().get('SIGNAL_COMMAND_SOURCE_LIMIT_V257', 140) or 140)
    except Exception:
        source_limit = 140
    rows = []
    def add_many(seq, source):
        try:
            for x in list(seq or []):
                if isinstance(x, dict):
                    r = dict(x)
                    r.setdefault('signal_v257_source', source)
                    rows.append(r)
        except Exception:
            pass
    try:
        add_many(globals().get('COMMAND_DISPLAY_CACHE_LAST_RANK_ROWS', []) or [], 'rank_cache')
    except Exception:
        pass
    try:
        if callable(globals().get('get_light_snapshot_rank_rows')):
            add_many(get_light_snapshot_rank_rows(limit=max(source_limit, 80), min_move_pct=globals().get('REALTIME_RANK_MIN_RECORD_MOVE_PCT', 0.0)) or [], 'light_rank')
    except Exception:
        pass
    try:
        sc = globals().get('shared_market_cache', {}) or {}
        if isinstance(sc, dict):
            add_many(list(sc.values())[:source_limit], 'shared_market_cache')
    except Exception:
        pass
    out, seen = [], set()
    for row in rows:
        tk = _v282_ticker(row)
        if not tk or tk in seen:
            continue
        seen.add(tk)
        out.append(row)
        if len(out) >= source_limit:
            break
    try:
        SIGNAL_V257_STATS['source_rows'] = len(out)
    except Exception:
        pass
    return out
def paper_auto_register_from_signal_snapshot_v258(trigger: str = "worker") -> int:
    if not bool(globals().get('PAPER_TRADING_ON', True)):
        return 0
    added = 0
    try:
        rows = _signal_v257_collect_rows(source_limit=80)
        ranked = []
        weight = {"BUY_OK": 4, "BREAKOUT_WAIT": 3, "PULLBACK_WAIT": 2, "DISCARD": 1}
        for row in list(rows or []):
            try:
                cls = _signal_v257_classify(row) if callable(globals().get('_signal_v257_classify')) else {}
                ranked.append((weight.get(str(cls.get('grade', '')), 0), safe_float(cls.get('score', 0), 0), safe_float(cls.get('money_amount', 0), 0), row))
            except Exception:
                continue
        ranked.sort(key=lambda x: (x[0], x[1], x[2]), reverse=True)
        max_new = int(safe_float(globals().get('PAPER_MAX_NEW_PER_SCAN', 3), 3))
        for _w, _score, _money, row in ranked[:30]:
            if added >= max_new:
                break
            try:
                if paper_register_candidate_v258(row, trigger=trigger):
                    added += 1
            except Exception:
                continue
        try:
            PAPER_V258_STATS['auto_scans'] = int(safe_float(PAPER_V258_STATS.get('auto_scans', 0), 0)) + 1
            PAPER_V258_STATS['last_auto_ts'] = time.time()
            PAPER_V258_STATS['last_note'] = f"v282 자동등록 {added}개"
        except Exception:
            pass
    except Exception as e:
        try: append_runtime_error_log('paper_auto_register_v282', str(e), exc=e, include_traceback=False)
        except Exception: pass
    return added
