def build_command_display_cache_once():
    """v2.9.0: 명령어 캐시는 빠른 운영판만 만든다. review_dump/review_pack/rank_compare는 생성하지 않는다."""
    global COMMAND_DISPLAY_CACHE_LAST_REFRESH_TS, COMMAND_DISPLAY_CACHE_DONE, COMMAND_DISPLAY_CACHE_FAIL, COMMAND_DISPLAY_CACHE_LAST_ERROR
    global COMMAND_DISPLAY_CACHE_WORKER_HEARTBEAT_TS, COMMAND_DISPLAY_CACHE_WORKER_BUILDING, COMMAND_DISPLAY_CACHE_LAST_BUILD_START_TS, COMMAND_DISPLAY_CACHE_LAST_BUILD_FINISH_TS
    global COMMAND_DISPLAY_READONLY_BUILDING, COMMAND_DISPLAY_CACHE_ACTIVE_BUILD_GENERATION
    global COMMAND_DISPLAY_CACHE_LAST_RANK_SNAPSHOT_TS, COMMAND_DISPLAY_CACHE_LAST_RANK_SNAPSHOT_COUNT, COMMAND_DISPLAY_CACHE_LAST_RANK_SNAPSHOT_NOTE
    global COMMAND_DISPLAY_CACHE_LAST_RANK_ROWS, COMMAND_DISPLAY_CACHE_LAST_RANK_SNAPSHOT_META
    now_ts = time.time()
    try:
        if callable(globals().get('_reset_command_cache_stage_timing')):
            _reset_command_cache_stage_timing()
    except Exception:
        pass
    COMMAND_DISPLAY_CACHE_WORKER_HEARTBEAT_TS = now_ts
    COMMAND_DISPLAY_CACHE_WORKER_BUILDING = True
    COMMAND_DISPLAY_READONLY_BUILDING = True
    COMMAND_DISPLAY_CACHE_LAST_BUILD_START_TS = now_ts
    COMMAND_DISPLAY_CACHE_ACTIVE_BUILD_GENERATION = int(safe_float(globals().get("COMMAND_DISPLAY_CACHE_GENERATION", 0), 0)) + 1
    try:
        try:
            if callable(globals().get('_set_command_cache_build_stage')):
                _set_command_cache_build_stage("v290_rank_source")
        except Exception:
            pass
        rank_rows = []
        try:
            source_limit = max(20, min(int(safe_float(globals().get("REALTIME_RANK_WATCH_SOURCE_LIMIT", 90), 90)), int(safe_float(globals().get("COMMAND_DISPLAY_RANK_SOURCE_LIMIT", 60), 60))))
            rank_rows = get_light_snapshot_rank_rows(limit=source_limit, min_move_pct=globals().get("REALTIME_RANK_MIN_RECORD_MOVE_PCT", 0.0))
        except Exception as e:
            try: append_runtime_event_log("v290_command_cache_rank_error", "rank source 오류", extra={"error": str(e)[:160]})
            except Exception: pass
            rank_rows = []
        try:
            if callable(globals().get('_maybe_register_rank_precision_rows_from_snapshot')):
                _maybe_register_rank_precision_rows_from_snapshot(rank_rows, now_ts=now_ts)
        except Exception as e:
            try: append_runtime_event_log("v290_rank_precision_register_error", "정밀차트 등록 오류", extra={"error": str(e)[:160]})
            except Exception: pass
        try:
            rank_rows = freeze_rank_rows_for_command_snapshot(rank_rows)
        except Exception:
            pass
        rank_snapshot_meta = {"generation": COMMAND_DISPLAY_CACHE_ACTIVE_BUILD_GENERATION, "created_ts": now_ts, "rank_rows": len(rank_rows) if isinstance(rank_rows, list) else 0, "cache_split": "v290_fast_only"}
        COMMAND_DISPLAY_CACHE_LAST_RANK_SNAPSHOT_TS = now_ts
        COMMAND_DISPLAY_CACHE_LAST_RANK_SNAPSHOT_COUNT = len(rank_rows) if isinstance(rank_rows, list) else 0
        COMMAND_DISPLAY_CACHE_LAST_RANK_SNAPSHOT_NOTE = f"v2.9.0 fast_only / 원본 {COMMAND_DISPLAY_CACHE_LAST_RANK_SNAPSHOT_COUNT}개"
        COMMAND_DISPLAY_CACHE_LAST_RANK_ROWS = list(rank_rows or [])
        COMMAND_DISPLAY_CACHE_LAST_RANK_SNAPSHOT_META = dict(rank_snapshot_meta)
        try:
            rank_limit = int(safe_float(globals().get("RANK_WATCH_SHORT_LIMIT", 8), 8))
            rank_tickers = [r.get("ticker") for r in (rank_rows or [])[:rank_limit] if isinstance(r, dict)]
        except Exception:
            rank_tickers = []
        try:
            if callable(globals().get('_set_command_cache_build_stage')):
                _set_command_cache_build_stage("v290_fast_text")
        except Exception:
            pass
        try:
            rank_text = build_rank_watch_short_text(limit=globals().get("RANK_WATCH_SHORT_LIMIT", 8), rank_rows_override=rank_rows, snapshot_meta=rank_snapshot_meta)
        except Exception as e:
            rank_text = f"📈 순위 압축 /rank_short\n- 생성 오류: {e.__class__.__name__}: {str(e)[:120]}"
        try:
            scan_health_text = build_scan_health_cached_text()
        except Exception as e:
            scan_health_text = f"🩺 스캔 상태 /scan_health\n- 생성 오류: {e.__class__.__name__}: {str(e)[:120]}"
        try:
            watch_text = build_review_watch_text(active_limit=globals().get("REVIEW_WATCH_ACTIVE_LIMIT", 5), done_limit=globals().get("REVIEW_WATCH_DONE_LIMIT", 2))
        except Exception as e:
            watch_text = f"🧪 내부감시 /review_watch\n- 생성 오류: {e.__class__.__name__}: {str(e)[:120]}"
        try:
            work_text = build_work_check_text_from_cached_parts(rank_text_override=rank_text, watch_text_override=watch_text, scan_health_text_override=scan_health_text)
        except Exception as e:
            work_text = f"⚡ 일하는 중 압축 /work_check\n- 생성 오류: {e.__class__.__name__}: {str(e)[:120]}"
        try:
            check_text = build_check_text_v282()
        except Exception:
            try:
                check_text = build_check_text_v280()
            except Exception as e:
                check_text = f"🧭 통합 점검 /check\n- 생성 오류: {e.__class__.__name__}: {str(e)[:120]}"
        try:
            set_command_display_cache_bundle({
                "rank_short": {"text": rank_text, "tickers": rank_tickers[:8], "snapshot_meta": rank_snapshot_meta},
                "review_watch": {"text": watch_text, "tickers": [], "snapshot_meta": rank_snapshot_meta},
                "work_check": {"text": work_text, "tickers": rank_tickers[:8], "snapshot_meta": rank_snapshot_meta},
                "scan_health": {"text": scan_health_text, "tickers": [], "snapshot_meta": rank_snapshot_meta},
                "check": {"text": check_text, "tickers": rank_tickers[:8], "snapshot_meta": rank_snapshot_meta},
            })
        except Exception:
            pass
        try:
            if callable(globals().get('_mark_command_fast_cache_complete')):
                _mark_command_fast_cache_complete(globals().get("COMMAND_DISPLAY_CACHE_GENERATION", 0))
        except Exception:
            pass
        COMMAND_DISPLAY_CACHE_DONE = int(safe_float(globals().get("COMMAND_DISPLAY_CACHE_DONE", 0), 0)) + 1
        COMMAND_DISPLAY_CACHE_LAST_REFRESH_TS = time.time()
        COMMAND_DISPLAY_CACHE_LAST_ERROR = ""
    except Exception as e:
        COMMAND_DISPLAY_CACHE_FAIL = int(safe_float(globals().get("COMMAND_DISPLAY_CACHE_FAIL", 0), 0)) + 1
        COMMAND_DISPLAY_CACHE_LAST_ERROR = f"v290 fast cache: {str(e)[:160]}"
        try: append_runtime_event_log("v290_command_display_cache_error", "fast cache 오류", extra={"error": str(e)[:160]})
        except Exception: pass
    finally:
        COMMAND_DISPLAY_CACHE_LAST_BUILD_FINISH_TS = time.time()
        COMMAND_DISPLAY_CACHE_WORKER_BUILDING = False
        COMMAND_DISPLAY_READONLY_BUILDING = False
        try:
            if callable(globals().get('_set_command_cache_build_stage')):
                _set_command_cache_build_stage("대기")
        except Exception:
            pass
        COMMAND_DISPLAY_CACHE_WORKER_HEARTBEAT_TS = time.time()

