def _v291_make_timed_handler(command: str, fn):
    def _wrapped(update=None, context=None):
        st = time.time()
        err = ""
        try:
            return fn(update, context)
        except Exception as e:
            err = f"{e.__class__.__name__}: {str(e)[:120]}"
            try:
                append_runtime_error_log(f"cmd_{command}", str(e), exc=e, include_traceback=True)
            except Exception:
                pass
            try:
                send(f"⚠️ /{command} 처리 오류: {err}")
            except Exception:
                pass
        finally:
            try:
                _v291_record_timing("direct", command, time.time() - st, err)
            except Exception:
                pass
    try:
        _wrapped.__name__ = f"timed_{command}_handler_v293"
    except Exception:
        pass
    return _wrapped

def _v280_add_handler(dispatcher, command, func_name):
    try:
        command = str(command or "").strip().lstrip("/")

        if not re.match(r"^[A-Za-z0-9_]+$", command):
            return False
        fn = globals().get(func_name)
        if callable(fn):
            dispatcher.add_handler(CommandHandler(command, _v291_make_timed_handler(command, fn)))
            return True
    except Exception as e:
        try: append_runtime_error_log("v293_add_handler", f"/{command} -> {func_name}: {e}", exc=e, include_traceback=False)
        except Exception: pass
    return False

