def _v294_trigger_auto_deploy_script(script_path: str) -> tuple[bool, str]:
    try:
        sp = __import__("subprocess")
        log_path = data_file("upgradebot_manual_trigger.log")
        with open(log_path, "a", encoding="utf-8", errors="ignore") as log:
            log.write(f"\n[{_runtime_log_ts()}] /upgradebot trigger: {script_path}\n")
            proc = sp.Popen(["bash", script_path], cwd=BASE_DIR, stdout=log, stderr=sp.STDOUT)
        try:
            _v290_set_upgrade_state("자동배포요청", f"script={script_path} pid={getattr(proc, 'pid', 0)}", url="AUTO_DEPLOY_SCRIPT")
        except Exception:
            pass
        return True, f"자동배포 스크립트 실행 요청됨 / pid {getattr(proc, 'pid', 0)} / log {os.path.basename(log_path)}"
    except Exception as e:
        try:
            append_runtime_error_log("v294_auto_deploy_trigger", str(e), exc=e, include_traceback=True)
        except Exception:
            pass
        return False, f"자동배포 스크립트 실행 실패: {e.__class__.__name__}: {str(e)[:180]}"

