def _v295_allowed_seed_ticker(ticker: str) -> bool:
    try:
        t = str(ticker or "").upper().strip()
        if not t or t == "BTC" or is_watch_excluded_ticker(t):
            return False
        return True
    except Exception:
        return False

def _v295_bulk_seed_row(ticker: str, price: float, rank: int, now_ts: float) -> dict:
    row = {
        "ticker": ticker, "price": price, "current_price": price,
        "df_1m": None, "df_3m": None, "turnover": 0.0,
        "surge_score": 0.0, "leader_score": 0.0,
        "turnover_rank": rank, "surge_rank": rank,
        "change_1": 0.0, "change_3": 0.0, "change_5": 0.0, "change_15": 0.0, "change_30": 0.0, "change_60": 0.0,
        "vol_ratio": 0.0, "range_pct": 0.0, "rsi": 0.0,
        "cache_updated_at": now_ts, "cache_source": "v295_bulk_seed",
    }
    try:
        row = apply_light_snapshot_metrics_to_item(row)
    except Exception:
        pass
    return row

def v295_seed_market_cache_from_bulk(force: bool = False, limit: int = None) -> int:
    """시장캐시가 0일 때만 쓰는 허브 보충. 후보 판단 문턱은 바꾸지 않고 가격 허브만 되살린다."""
    global shared_market_cache, shared_market_cache_time, shared_cache_row_times, last_shared_cache_success_ts
    global market_universe, market_universe_time
    try:
        limit = max(20, int(safe_float(limit if limit is not None else V295_HUB_SEED_LIMIT, V295_HUB_SEED_LIMIT)))
        bulk = get_bulk_current_price_snapshot(force=bool(force)) if callable(globals().get("get_bulk_current_price_snapshot")) else {}
        if not isinstance(bulk, dict) or not bulk:
            V295_HUB_REFILL_STATS.update({"seed_fail": V295_HUB_REFILL_STATS.get("seed_fail", 0) + 1, "last_note": "bulk 없음", "last_ts": time.time()})
            return 0
        now_ts = time.time()
        rows = []

        preferred = [str(x).upper().strip() for x in list(globals().get("DEFAULT_MARKET_TICKERS", []) or [])]
        seen = set()
        ordered = []
        for t in preferred + [str(x).upper().strip() for x in bulk.keys()]:
            if t in seen or not _v295_allowed_seed_ticker(t):
                continue
            p = safe_float(bulk.get(t, 0), 0)
            if p <= 0:
                continue
            seen.add(t); ordered.append((t, p))
            if len(ordered) >= limit:
                break
        for idx, (t, p) in enumerate(ordered, start=1):
            rows.append(_v295_bulk_seed_row(t, p, idx, now_ts))
            try:
                record_light_price_snapshot(t, p, turnover_hint=0.0, source="v295_hub_seed", now_ts=now_ts)
            except Exception:
                pass
        if not rows:
            return 0
        cache = {r["ticker"]: r for r in rows if isinstance(r, dict) and r.get("ticker")}
        times = {t: now_ts for t in cache.keys()}
        shared_market_cache = cache
        shared_cache_row_times = times
        shared_market_cache_time = now_ts
        last_shared_cache_success_ts = now_ts
        market_universe = [{"ticker": r["ticker"], "last_price": r.get("price", 0), "turnover_recent": 0.0, "surge_score": 0.0, "leader_score": 0.0, "snapshot_seed": True} for r in rows]
        market_universe_time = now_ts
        try:
            update_scan_debug_snapshot(shared_market_cache, note="v2.9.5 bulk seed market cache")
        except Exception:
            pass
        V295_HUB_REFILL_STATS.update({"seed_ok": V295_HUB_REFILL_STATS.get("seed_ok", 0) + 1, "last_note": f"bulk seed {len(cache)}개", "last_ts": now_ts, "last_seed_count": len(cache)})
        return len(cache)
    except Exception as e:
        try: append_runtime_error_log("v295_seed_market_cache", str(e), exc=e, include_traceback=False)
        except Exception: pass
        V295_HUB_REFILL_STATS.update({"seed_fail": V295_HUB_REFILL_STATS.get("seed_fail", 0) + 1, "last_note": f"seed 오류 {e.__class__.__name__}", "last_ts": time.time()})
        return 0


