    while True:
        sleep_sec = max(4.0, safe_float(globals().get("V295_HUB_REFILL_SLEEP_SEC", 4.0), 4.0))
        try:
            now_ts = time.time(); cache = globals().get("shared_market_cache", {}); n = len(cache) if isinstance(cache, dict) else 0
            ts = safe_float(globals().get("shared_market_cache_time", 0), 0); age = now_ts - ts if ts > 0 else 999999.0
            if n > 0: empty_since = now_ts
            if n <= 0 and now_ts - empty_since >= safe_float(globals().get("V295_HUB_FORCE_SEED_AFTER_SEC", 8.0), 8.0):
                seeded = v295_seed_market_cache_from_bulk(force=True, limit=V295_HUB_SEED_LIMIT)
                if seeded > 0: empty_since = now_ts
                try:
                    request_market_refresh(force=True, reason="v297_empty_hub_refill"); V295_HUB_REFILL_STATS["refresh_req"] = V295_HUB_REFILL_STATS.get("refresh_req", 0) + 1; V297_IDLE_STATS["hub_refresh"] += 1
                except Exception: pass
                V297_IDLE_STATS["hub_seed"] += 1; sleep_sec = 2.0
            elif n > 0 and age >= safe_float(globals().get("V297_HUB_STALE_REFRESH_SEC", 18.0), 18.0):
                try:
                    request_market_refresh(force=False, reason="v297_hub_stale"); V295_HUB_REFILL_STATS["refresh_req"] = V295_HUB_REFILL_STATS.get("refresh_req", 0) + 1; V297_IDLE_STATS["hub_refresh"] += 1
                    V295_HUB_REFILL_STATS.update({"last_note": f"refresh 요청 {int(age)}초", "last_ts": now_ts})
                except Exception: pass
                sleep_sec = 4.0
            else:
                V297_IDLE_STATS["hub_sleep"] += 1; V295_HUB_REFILL_STATS.update({"last_note": f"정상이라 쉼 {n}개/{int(age)}초", "last_ts": now_ts}); sleep_sec = max(sleep_sec, safe_float(globals().get("V297_HUB_HEALTHY_SLEEP_SEC", 12.0), 12.0))
        except Exception as e:
            try: append_runtime_error_log("v297_hub_refill_loop", str(e), exc=e, include_traceback=False)
            except Exception: pass
        time.sleep(sleep_sec)

