def _v298_record_worker(name: str, sec: float = 0.0, error: str = ""):
    try:
        st = V298_WORKER_STATS.setdefault(str(name), {"count": 0, "last_sec": 0.0, "max_sec": 0.0, "last_ts": 0.0, "error": ""})
        st["count"] = int(st.get("count", 0)) + 1
        st["last_sec"] = round(float(sec or 0), 4)
        st["max_sec"] = max(float(st.get("max_sec", 0) or 0), float(sec or 0))
        st["last_ts"] = _v298_now()
        if error:
            st["error"] = str(error)[:160]
    except Exception:
        pass


