def request_market_refresh(*args, **kwargs):
    st = _v298_now()
    try:
        if callable(_BASE_REQUEST_MARKET_REFRESH_V298):
            res = _BASE_REQUEST_MARKET_REFRESH_V298(*args, **kwargs)
        else:
            res = None
        _v298_record_worker("market_refresh", _v298_now() - st)
        return res
    except Exception as e:
        _v298_record_worker("market_refresh", _v298_now() - st, f"{e.__class__.__name__}: {str(e)[:120]}")
        raise

