def _v298_num_from_row(row, keys, default=0.0):
    try:
        if not isinstance(row, dict):
            return default
        for k in keys:
            if k in row:
                v = safe_float(row.get(k), default)
                if v != default:
                    return v
        return default
    except Exception:
        return default

def _v298_ticker_from_market(key, row):
    try:
        if isinstance(row, dict):
            return str(row.get("ticker") or row.get("symbol") or row.get("market") or key or "?").upper().replace("KRW-", "")
        return str(key or "?").upper().replace("KRW-", "")
    except Exception:
        return "?"

def _v298_market_cache_rank_rows(limit: int = None) -> list:
    st = _v298_now()
    try:
        limit = int(limit or V298_RANK_FALLBACK_LIMIT)
        cache = globals().get("shared_market_cache", {}) or {}
        if not isinstance(cache, dict) or not cache:
            return []
        rows = []
        for key, val in list(cache.items()):
            row = val if isinstance(val, dict) else {}
            ticker = _v298_ticker_from_market(key, row)
            if ticker in {"BTC", "USDT", "USDC", "BUSD", "DAI"}:
                continue
            price = _v298_num_from_row(row, ["current_price", "price", "trade_price", "close", "last", "last_price"], 0.0)
            chg = _v298_num_from_row(row, ["change_pct", "change_rate", "chg_pct", "signed_change_rate", "fluctate_rate", "rate"], 0.0)
            if abs(chg) > 100 and abs(chg) <= 10000:
                chg = chg / 100.0
            turnover = _v298_num_from_row(row, ["acc_trade_value_24h", "turnover", "trade_value", "value", "amount", "volume_krw"], 0.0)
            rows.append({
                "ticker": ticker,
                "current_price": price,
                "price": price,
                "change_pct": round(chg, 4),
                "chg_1m": _v298_num_from_row(row, ["chg_1m", "change_1m", "change_1"], 0.0),
                "chg_3m": _v298_num_from_row(row, ["chg_3m", "change_3m", "change_3"], 0.0),
                "chg_5m": _v298_num_from_row(row, ["chg_5m", "change_5m", "change_5"], 0.0),
                "chg_15m": _v298_num_from_row(row, ["chg_15m", "change_15m", "change_15"], 0.0),
                "turnover": turnover,
                "_v298_fallback": True,
            })
        rows.sort(key=lambda r: (abs(safe_float(r.get("change_pct", 0), 0)), safe_float(r.get("turnover", 0), 0)), reverse=True)
        rows = rows[:max(1, limit)]
        V298_RANK_FALLBACK_STATS.update({"used": int(V298_RANK_FALLBACK_STATS.get("used",0))+1, "last_ts": _v298_now(), "last_count": len(rows), "last_source": "market_cache", "last_sec": round(_v298_now()-st,4)})
        _v298_record_worker("rank_rows", _v298_now() - st)
        return rows
    except Exception as e:
        V298_RANK_FALLBACK_STATS.update({"last_ts": _v298_now(), "last_source": f"error:{e.__class__.__name__}", "last_sec": round(_v298_now()-st,4)})
        _v298_record_worker("rank_rows", _v298_now() - st, f"{e.__class__.__name__}: {str(e)[:120]}")
        return []

def _v297_rank_rows():
    st = _v298_now()
    try:
        rows = globals().get("COMMAND_DISPLAY_CACHE_LAST_RANK_ROWS", []) or []
        if isinstance(rows, list) and rows:
            _v298_record_worker("rank_rows", _v298_now() - st)
            return rows
        if callable(_BASE_GET_LIGHT_SNAPSHOT_RANK_ROWS_V298):
            try:
                rows2 = _BASE_GET_LIGHT_SNAPSHOT_RANK_ROWS_V298(limit=V298_RANK_FALLBACK_LIMIT, min_move_pct=0.0)
                if isinstance(rows2, list) and rows2:
                    V298_RANK_FALLBACK_STATS.update({"used": int(V298_RANK_FALLBACK_STATS.get("used",0))+1, "last_ts": _v298_now(), "last_count": len(rows2), "last_source": "light_snapshot", "last_sec": round(_v298_now()-st,4)})
                    _v298_record_worker("rank_rows", _v298_now() - st)
                    return rows2
            except Exception as e:
                V298_RANK_FALLBACK_STATS.update({"last_source": f"light_error:{e.__class__.__name__}", "last_ts": _v298_now()})
        return _v298_market_cache_rank_rows(V298_RANK_FALLBACK_LIMIT)
    except Exception as e:
        _v298_record_worker("rank_rows", _v298_now() - st, f"{e.__class__.__name__}: {str(e)[:120]}")
        return []

def _v298_text_contains_reject(text: str) -> bool:
    t = str(text or "").lower()
    bad = ["reject", "blocked", "block", "classify_reject", "max_active", "active_duplicate", "cooldown", "보류", "거절", "차단", "v336_entry_reject"]
    return any(x in t for x in bad)

def _v298_is_reject_row(row: dict) -> bool:
    try:
        if not isinstance(row, dict):
            return True
        joined = " ".join(str(row.get(k, "")) for k in ("reason", "close_reason", "exit_reason", "entry_rule", "trigger", "status", "event", "type"))
        return _v298_text_contains_reject(joined)
    except Exception:
        return True

def _v298_is_real_closed_row(row: dict) -> bool:
    try:
        if not isinstance(row, dict) or _v298_is_reject_row(row):
            return False
        status = str(row.get("status") or "").upper()
        if status in {"REJECT", "REJECTED", "PENDING", "WATCH", "READY", "OPEN"}:
            return False
        has_close_ts = any(safe_float(row.get(k, 0), 0) > 0 for k in ("close_ts", "closed_ts", "exit_ts", "sell_ts"))
        has_close_reason = any(str(row.get(k, "") or "").strip() for k in ("close_reason", "exit_reason", "sell_reason"))
        if status in {"CLOSED", "CLOSE", "EXIT", "EXITED", "SOLD", "DONE"}:
            return True
        if has_close_ts and has_close_reason:
            return True
        return False
    except Exception:
        return False

def _v298_reject_rows_from_logs(logs, attempts, rejects):
    out = []
    try:
        out.extend([r for r in list(rejects or []) if isinstance(r, dict)])
        out.extend([r for r in list(attempts or []) if isinstance(r, dict) and _v298_is_reject_row(r)])
        out.extend([r for r in list(logs or []) if isinstance(r, dict) and _v298_is_reject_row(r)])
    except Exception:
        pass
    return out[-160:]

