def _v299_row_text(row: dict) -> str:
    try:
        if not isinstance(row, dict):
            return ""
        keys = [
            "strategy", "strategy_label", "route", "route_name", "entry_rule", "trigger", "reason", "entry_reason",
            "close_reason", "exit_reason", "sell_reason", "bucket", "label", "grade", "tier", "ctx", "context",
            "primary_reason", "one_liner", "rank_watch_low_route", "low_structure_route_v244",
            "low_structure_summary_v2", "low_defense_v2_label", "low_rising_label_v2", "pattern_tags", "tags",
            "source", "factory_stage", "paper_route", "paper_strategy",
        ]
        parts = []
        for k in keys:
            v = row.get(k)
            if isinstance(v, (list, tuple, set)):
                parts.extend([str(x) for x in v])
            elif isinstance(v, dict):
                parts.extend([str(x) for x in v.values()])
            elif v is not None:
                parts.append(str(v))
        return " ".join(parts).lower()
    except Exception:
        return ""

def v299_classify_core_strategy(row: dict) -> tuple[str, str]:
    """핵심 paper 집계용 전략 분류.
    - pullback 단어 하나만으로는 핵심전략 취급하지 않는다.
    - M2 눌림 재확인 / 저점선점 보조 근거가 들어온 행만 집계한다.
    """
    try:
        txt = _v299_row_text(row)
        if not txt:
            return "", "route 정보 없음"
        m2_words = [
            "m2", "눌림재확인", "눌림 재확인", "pullback_recheck", "recheck_pullback",
            "m2_pullback", "m2 recheck", "m2-recheck", "recheck", "재확인",
        ]
        low_words = [
            "저점선점", "low_first", "low-first", "low_preempt", "preempt_low", "early_low",
            "저점방어", "저점높임", "저가회복", "가짜하락회복", "하락복구", "저점 구조",
            "low_defense", "low rising", "low_rising", "low_structure", "restart_low",
            "저점방어 재출발형", "저점높임 재출발형",
        ]
        if any(w in txt for w in m2_words):
            return "M2 눌림 재확인", "M2/눌림 재확인 근거"
        if any(w in txt for w in low_words):
            return "저점선점 보조", "저점방어/저점높임 근거"
        return "", "핵심 2전략 근거 없음"
    except Exception as e:
        return "", f"분류오류:{e.__class__.__name__}"

