def paper_register_candidate_v258(row: dict, trigger: str = "auto") -> bool:
    """v2.9.9: paper 신규 등록은 핵심 2전략만 허용.
    비핵심은 삭제가 아니라 paper 통계 오염 방지용으로 등록 차단한다.
    """
    try:
        if not V299_CORE_PAPER_ONLY_ON:
            return _BASE_PAPER_REGISTER_CANDIDATE_V299(row, trigger=trigger) if callable(_BASE_PAPER_REGISTER_CANDIDATE_V299) else False
        name, why = v299_classify_core_strategy(row if isinstance(row, dict) else {})
        if not name:
            V299_CORE_PAPER_STATS["blocked"] = int(V299_CORE_PAPER_STATS.get("blocked", 0)) + 1
            V299_CORE_PAPER_STATS["last_blocked"] = f"{(row or {}).get('ticker','?') if isinstance(row,dict) else '?'} / {why}"
            V299_CORE_PAPER_STATS["last_ts"] = time.time()
            return False
        if isinstance(row, dict):
            row = dict(row)
            row["v299_core_strategy"] = name
            row["v299_core_reason"] = why
        ok = _BASE_PAPER_REGISTER_CANDIDATE_V299(row, trigger=trigger) if callable(_BASE_PAPER_REGISTER_CANDIDATE_V299) else False
        if ok:
            V299_CORE_PAPER_STATS["accepted"] = int(V299_CORE_PAPER_STATS.get("accepted", 0)) + 1
            V299_CORE_PAPER_STATS["last_core"] = str((row or {}).get("ticker", "?")) if isinstance(row, dict) else "?"
            V299_CORE_PAPER_STATS["last_strategy"] = name
            V299_CORE_PAPER_STATS["last_ts"] = time.time()
        return bool(ok)
    except Exception as e:
        try: append_runtime_error_log("v299_core_paper_register", str(e), exc=e, include_traceback=False)
        except Exception: pass
        return False

