def main():
    updater = Updater(token=TELEGRAM_TOKEN, use_context=True); dispatcher = updater.dispatcher
    try:
        register_bot_commands(updater.bot)
    except TypeError:
        try: register_bot_commands()
        except Exception: pass
    except Exception:
        pass
    for cmd, fn in [
        ("main", "main_command"), ("summary", "main_command"),
        ("monitor", "monitor_command"), ("monitor_on", "monitor_on_command"), ("monitor_off", "monitor_off_command"),
        ("startupcheck", "startupcheck_command"), ("startup_check", "startupcheck_command"),
        ("pullback", "pullback_command"), ("pb", "pullback_command"),
        ("focus", "focus_command"),
        ("dev", "dev_command"),
        ("prune_check", "prune_check_command"),
        ("errorlog", "errorlog_command"), ("errorlog_full", "errorlog_full_command"),
        ("batch", "batch_command"), ("run", "batch_command"),
        ("upgradebot", "upgrade_bot_command"), ("upgrade_bot", "upgrade_bot_command"),
        ("register_commands", "register_commands_command"), ("refreshcommands", "register_commands_command"),
        ("upgradestatus", "upgrade_status_command"), ("upgrade_status", "upgrade_status_command"),
    ]:
        _v280_add_handler(dispatcher, cmd, fn)
    try: dispatcher.add_handler(CallbackQueryHandler(price_check_callback, pattern=r"^pc:"))
    except Exception: pass
    safe_start_polling(updater); print(f"📡 {BOT_VERSION} 텔레그램 수신 시작 / {TIMEZONE}", flush=True)
    try: send_receiver_ready_message()
    except Exception: pass
    threading.Thread(target=register_bot_commands, daemon=True, name="register_bot_commands").start()
    for fn in ["load_runtime_settings", "force_autobuy_off_on_startup", "load_positions", "load_pending_sells", "load_pending_buys", "load_price_check_state", "load_market_pulse_state", "load_internal_watch_track_state", "load_paper_state_v258", "recover_positions_from_exchange", "cleanup_pending_buy_candidates", "save_positions", "save_pending_sells", "save_pending_buys", "persist_price_check_state", "persist_market_pulse_state", "persist_internal_watch_track_state"]:
        try: _v280_safe_call(fn)
        except Exception as e:
            try: append_runtime_error_log(f"v299_start_{fn}", str(e), exc=e, include_traceback=False)
            except Exception: pass
    try: reset_auto_pause_state(bypass_sec=900, reason="restart")
    except Exception: pass
    try: mark_main_loop_heartbeat(stage="startup_ready_v299")
    except Exception: pass
    worker_names = [("scan_watchdog", "scan_watchdog_loop"), ("v295_hub_refill", "v295_market_hub_refill_loop"), ("v296_paper_cache", "v296_paper_command_cache_worker_loop"), ("v297_quality_cache", "v297_quality_cache_worker_loop"), ("command_display_cache", "command_display_cache_worker_loop"), ("light_snapshot_worker", "light_snapshot_worker_loop"), ("precision_minute1_chart_worker", "precision_minute1_chart_worker_loop"), ("ws_ticker_worker", "websocket_ticker_worker_loop"), ("ws_trade_worker", "websocket_trade_worker_loop"), ("paper_trade_worker_v258", "paper_trade_worker_loop_v258")]
    for tname, fname in worker_names:
        fn = globals().get(fname)
        if callable(fn):
            try: threading.Thread(target=fn, daemon=True, name=tname).start()
            except Exception as e:
                try: append_runtime_error_log(f"v299_worker_{fname}", str(e), exc=e, include_traceback=False)
                except Exception: pass
    try: request_market_refresh(force=True, reason="startup_v299")
    except Exception: pass
    try: v295_seed_market_cache_from_bulk(force=False, limit=V295_HUB_SEED_LIMIT)
    except Exception: pass
    send_startup_message(); print(f"🚀 {BOT_VERSION} 실행 / {TIMEZONE} / core-paper diet", flush=True)
    last_scan_cycle_time = 0; last_position_cycle_time = 0; last_market_refresh_time = 0
    while True:
        loop_started = time.time(); now_ts = loop_started
        try:
            try: mark_main_loop_heartbeat(stage="loop_idle_v299")
            except Exception: pass
            V297_IDLE_STATS["main_idle"] = V297_IDLE_STATS.get("main_idle",0) + 1
            try: update_active_price_check_refs(now_ts); process_scheduled_price_checks(now_ts)
            except Exception: pass
            need_scan_cycle = (now_ts - last_scan_cycle_time) >= SCAN_INTERVAL; need_position_cycle = (now_ts - last_position_cycle_time) >= POSITION_CHECK_INTERVAL
            cache_empty = not bool(shared_market_cache); market_refresh_gap = MARKET_REFRESH_EMPTY_RETRY_SEC if cache_empty else MARKET_REFRESH_INTERVAL_SEC
            if cache_empty:
                try: v295_seed_market_cache_from_bulk(force=False, limit=V295_HUB_SEED_LIMIT)
                except Exception: pass
            if (need_scan_cycle or need_position_cycle or cache_empty) and ((now_ts - last_market_refresh_time) >= market_refresh_gap):
                try: request_market_refresh(force=cache_empty, reason=("empty_cache_v299" if cache_empty else "loop_refresh_v299"))
                except Exception: pass
                last_market_refresh_time = now_ts
            shared_cache = shared_market_cache if isinstance(shared_market_cache, dict) else None
            if need_scan_cycle:
                V297_IDLE_STATS["scan_cycle"] = V297_IDLE_STATS.get("scan_cycle",0) + 1
                try: mark_main_loop_heartbeat(stage="scan_watchlist_v299"); scan_watchlist(shared_cache=shared_cache)
                except Exception as e:
                    try: log_exception_details("v299_loop_scan_watchlist", e, prefix="[v299] scan_watchlist")
                    except Exception: pass
                if _v291_should_run_auto_trade_cycle():
                    try: mark_main_loop_heartbeat(stage="pending_promote_v299"); process_pending_buy_promotions(shared_cache=shared_cache)
                    except Exception as e:
                        try: log_exception_details("v299_pending_promotion", e, prefix="[v299] pending")
                        except Exception: pass
                    try: mark_main_loop_heartbeat(stage="auto_trade_v299"); scan_and_auto_trade(shared_cache=shared_cache)
                    except Exception as e:
                        try: log_exception_details("v299_auto_trade", e, prefix="[v299] auto_trade")
                        except Exception: pass
                else:
                    V297_IDLE_STATS["pending_skip_autobuy_off"] = V297_IDLE_STATS.get("pending_skip_autobuy_off",0) + 1
                    try: mark_main_loop_heartbeat(stage="auto_order_skip_autobuy_off_v299")
                    except Exception: pass
                last_scan_cycle_time = now_ts
            if need_position_cycle:
                V297_IDLE_STATS["position_cycle"] = V297_IDLE_STATS.get("position_cycle",0) + 1
                try: mark_main_loop_heartbeat(stage="position_check_v299"); check_pending_sells(); cleanup_pending_buy_candidates(); monitor_positions()
                except Exception as e:
                    try: log_exception_details("v299_position_cycle", e, prefix="[v299] position")
                    except Exception: pass
                last_position_cycle_time = now_ts
            try: flush_position_state(force=False)
            except Exception: pass
            try: V291_MAIN_LOOP_TIMINGS["loop_total"] = round(time.time() - loop_started, 4); mark_main_loop_heartbeat(stage="loop_sleep_v299")
            except Exception: pass
        except Exception as e:
            try: log_exception_details("v299_main_loop", e, prefix="[v299 메인 루프 오류]")
            except Exception: pass
        time.sleep(LOOP_SLEEP)

