def _v210_row_text(row: dict) -> str:
    try:
        if callable(globals().get('_v299_row_text')):
            return _v299_row_text(row)
        if not isinstance(row, dict):
            return ""
        return " ".join(str(v) for v in row.values() if v is not None).lower()
    except Exception:
        return ""

def _v210_has_any(txt: str, words) -> bool:
    try:
        return any(str(w).lower() in txt for w in list(words or []))
    except Exception:
        return False

def v210_classify_strategy(row: dict) -> tuple[str, str, str]:
    """v2.10.8: paper route를 차단하지 않고 3구역으로 분류한다.
    - 350 본선 추정 route는 강하게 표시한다.
    - 이름이 애매하면 분류대기로 남기고, 신규등록은 막지 않는다.
    """
    try:
        txt = _v210_row_text(row)
        if not txt:
            return "unknown", V210_UNKNOWN_LABEL, "route 정보 없음"
        m2_words = [
            "m2", "눌림재확인", "눌림 재확인", "pullback_recheck", "recheck_pullback",
            "m2_pullback", "m2 recheck", "m2-recheck", "recheck", "재확인",
        ]
        low_words = [
            "저점선점", "low_first", "low-first", "low_preempt", "preempt_low", "early_low",
            "저점방어", "저점높임", "저가회복", "가짜하락회복", "하락복구", "저점 구조",
            "low_defense", "low rising", "low_rising", "low_structure", "restart_low",
            "저점방어 재출발형", "저점높임 재출발형",
        ]
        main_words = [
            "cancel_reentry_forced", "v313", "v343", "pullback_wait", "pullback wait",
            "factory_stage1", "factory_stage2", "factory_stage", "central_missing",
            "paper_route", "pullback", "눌림", "good_pullback",
        ]
        if _v210_has_any(txt, m2_words):
            return "m2", V210_M2_LABEL, "M2/눌림 재확인 근거"
        if _v210_has_any(txt, low_words):
            return "low", V210_LOW_LABEL, "저점방어/저점높임 근거"
        if _v210_has_any(txt, main_words):
            if "pullback" in txt and not _v210_has_any(txt, ["cancel_reentry", "v313", "v343", "pullback_wait", "factory_stage", "central_missing"]):
                return "main_guess", V210_MAIN_STRATEGY_LABEL, "pullback 계열 route라 350 본선 후보로 표시"
            return "main_guess", V210_MAIN_STRATEGY_LABEL, "350 본선 route 흔적"
        return "legacy", V210_UNKNOWN_LABEL, "350 본선 근거 불충분"
    except Exception as e:
        return "unknown", V210_UNKNOWN_LABEL, f"분류오류:{e.__class__.__name__}"

def _v210_is_non_entry_close(row: dict) -> bool:
    try:
        txt = _v210_row_text(row)
        bad = [
            "pending_timeout", "chase_over_before_entry", "before_entry", "entry_reject", "no_entry",
            "classify_reject", "active_duplicate", "max_active_limit", "blocked_v", "reject", "rejected",
            "stale_quarantine", "recent_closed_cooldown",
        ]
        if _v210_has_any(txt, bad):
            return True
        status = str((row or {}).get("status") or "").upper()
        if status in {"REJECT", "REJECTED", "PENDING", "WATCH", "READY"}:
            return True
        return False
    except Exception:
        return True

def _v210_is_actual_trade_closed(row: dict) -> bool:
    try:
        return bool(_v298_is_real_closed_row(row)) and not _v210_is_non_entry_close(row)
    except Exception:
        return False

def _v210_bucket_rows(rows):
    buckets = {"main": [], "m2": [], "low": [], "legacy": [], "unknown": []}
    for r in list(rows or []):
        if not isinstance(r, dict):
            continue
        key, label, why = v210_classify_strategy(r)
        rr = dict(r)
        rr["v210_strategy_key"] = key
        rr["v210_strategy_label"] = label
        rr["v210_strategy_reason"] = why
        if key == "m2":
            buckets["m2"].append(rr); buckets["main"].append(rr)
        elif key == "low":
            buckets["low"].append(rr); buckets["main"].append(rr)
        elif key == "main_guess":
            buckets["main"].append(rr)
        elif key == "legacy":
            buckets["legacy"].append(rr)
        else:
            buckets["unknown"].append(rr)
    return buckets

def _v210_row_line(row: dict, idx: int = 1) -> str:
    try:
        key, label, why = v210_classify_strategy(row)
        return f"{idx}. {_v296_ticker(row)} / {_v296_status(row)} / {_v296_rule(row)} / {label} / {why}"
    except Exception:
        return f"{idx}. ? / row 표시 오류"

def _v210_active_lines(rows, limit=6):
    out = []
    for i, r in enumerate(list(rows or [])[:max(1, int(limit))], 1):
        out.append(_v210_row_line(r, i))
    return out

def _v210_closed_lines(rows, limit=6):
    out = []
    for i, r in enumerate(list(rows or [])[:max(1, int(limit))], 1):
        try:
            key, label, why = v210_classify_strategy(r)
            out.append(f"{i}. {_v296_ticker(r)} / {_v296_pnl(r):+.2f}% / {_v296_reason(r)} / {_v296_rule(r)} / {label}")
        except Exception:
            out.append(f"{i}. ? / closed 표시 오류")
    return out

