def _v2102_now():
    try:
        return time.time()
    except Exception:
        return 0.0

def _v2102_normalize_paper_cache(cache: dict, started: float = 0.0) -> dict:
    """v2.10.8: v2.10.8은 paper cache에 ts만 넣고 created_ts/stats를 누락했다.
    core_check/strategy_map은 ts 계열을 보는데 paper_stats는 created_ts를 봐서 '준비중'이 떴다.
    여기서 단일 캐시 형태로 통일한다.
    """
    try:
        if not isinstance(cache, dict):
            return {}
        now_ts = _v2102_now()
        ts = safe_float(cache.get("created_ts", cache.get("ts", now_ts)), now_ts)
        cache["created_ts"] = ts
        cache["ts"] = ts
        cache["paper_cache_version"] = "v2.10.8_unified"
        cache["paper_cache_note"] = "350본선 paper 캐시 단일화"
        if "stats" not in cache: cache["stats"] = "🧪 paper 캐시 준비중\n- stats 텍스트 없음"
        if "flow" not in cache: cache["flow"] = "🧪 paper 캐시 준비중\n- flow 텍스트 없음"
        if "recent" not in cache: cache["recent"] = "🧪 paper 캐시 준비중\n- recent 텍스트 없음"
        sec = round(max(0.0, _v2102_now() - safe_float(started, now_ts)), 4) if started else safe_float(cache.get("last_build_sec", 0), 0)
        cache["last_build_sec"] = sec
        try:
            V296_PAPER_COMMAND_CACHE_STATS.update({
                "done": int(V296_PAPER_COMMAND_CACHE_STATS.get("done", 0)) + 1,
                "last_ts": ts,
                "last_duration": sec,
                "last_error": "",
            })
        except Exception:
            pass
        try:
            _v298_record_worker("paper_cache", sec)
        except Exception:
            pass
        return cache
    except Exception:
        return cache if isinstance(cache, dict) else {}

def v296_rebuild_paper_command_cache(force=False):
    """v2.10.8: paper_stats/paper_flow/paper_recent/core_check/strategy_map이 같은 캐시를 본다.
    원본 파일 재스캔 경로를 새로 만들지 않고, 기존 paper worker 메모리 snapshot 기반 builder만 정규화한다.
    """
    st = _v2102_now()
    try:
        if callable(_BASE_REBUILD_PAPER_CACHE_V2102):
            _BASE_REBUILD_PAPER_CACHE_V2102(force=force)
        cache = globals().get("V296_PAPER_COMMAND_CACHE", {})
        if not isinstance(cache, dict):
            cache = {}
        cache = _v2102_normalize_paper_cache(dict(cache), started=st)
        try:
            with V296_PAPER_COMMAND_CACHE_LOCK:
                V296_PAPER_COMMAND_CACHE.clear()
                V296_PAPER_COMMAND_CACHE.update(cache)
        except Exception:
            globals()["V296_PAPER_COMMAND_CACHE"] = cache
        return cache
    except Exception as e:
        try:
            V296_PAPER_COMMAND_CACHE_STATS.update({"fail": int(V296_PAPER_COMMAND_CACHE_STATS.get("fail",0))+1, "last_ts": _v2102_now(), "last_error": f"{e.__class__.__name__}: {str(e)[:120]}"})
            _v298_record_worker("paper_cache", _v2102_now()-st, f"{e.__class__.__name__}: {str(e)[:120]}")
            append_runtime_error_log("v2102_paper_cache", str(e), exc=e, include_traceback=False)
        except Exception:
            pass
        return {}

