def _v2103_rebuild_core_paper_cache(force=False):
    """v2.10.8: /strategy_map과 /paper_*가 같은 350 본선 캐시를 보도록 직접 재생성한다.
    명령어가 원본 파일을 훑지 않고, paper 직원이 이미 메모리에 올린 snapshot만 사용한다.
    """
    st = _v2103_now()
    try:
        positions, logs, attempts, rejects = _v2103_paper_snapshot()
        now_ts = _v2103_now()
        raw_closed = _v2103_safe_list(logs)
        attempts = _v2103_safe_list(attempts)
        rejects = _v2103_safe_list(rejects)
        positions = _v2103_safe_list(positions)
        try:
            reject_rows = _v298_reject_rows_from_logs(raw_closed, attempts, rejects)
        except Exception:
            reject_rows = rejects
        actual_closed = []
        non_entry_closed = []
        for r in raw_closed:
            try:
                if _v298_is_real_closed_row(r):
                    if _v210_is_non_entry_close(r):
                        non_entry_closed.append(r)
                    else:
                        actual_closed.append(r)
            except Exception:
                pass
        actual_closed.sort(key=lambda r: _v296_row_ts(r), reverse=True)
        closed_b = _v210_bucket_rows(actual_closed)
        main_closed = closed_b.get("main", [])
        m2_closed = closed_b.get("m2", [])
        low_closed = closed_b.get("low", [])
        legacy_closed = closed_b.get("legacy", []) + closed_b.get("unknown", [])
        active_all = [r for r in positions if _v296_status(r) in {"PENDING", "OPEN", "WATCH", "READY", "?"}]
        active_b = _v210_bucket_rows(active_all)
        main_active = active_b.get("main", [])
        m2_active = active_b.get("m2", [])
        low_active = active_b.get("low", [])
        legacy_active = active_b.get("legacy", []) + active_b.get("unknown", [])
        open_n = sum(1 for r in main_active if _v296_status(r) == "OPEN")
        pending_n = sum(1 for r in main_active if _v296_status(r) == "PENDING")
        w6 = [r for r in main_closed if now_ts - _v296_row_ts(r) <= 6*3600]
        w12 = [r for r in main_closed if now_ts - _v296_row_ts(r) <= 12*3600]
        w30 = [r for r in main_closed if now_ts - _v296_row_ts(r) <= 30*60]
        attempts30 = [r for r in attempts if now_ts - _v296_row_ts(r) <= 30*60]
        rejects30 = [r for r in reject_rows if now_ts - _v296_row_ts(r) <= 30*60]
        elapsed = round(max(0.0, _v2103_now() - st), 4)
        gen = f"- 캐시생성: {now_kst().strftime('%H:%M:%S')} / 350 본선 분류표시 / 직원 메모리 snapshot 사용 / 소요 {elapsed:.3f}s"
        stats = [
            "📊 350 본선 모의매매 /paper_stats",
            f"- 버전: {BOT_VERSION} / v2.10.8 350기준 캐시 단일화",
            "- 집계대상: 350 자동매매 본선 추정 route의 실제 진입 후 청산",
            "- 표시구분: 🔥 350 본선 추정 / 🔥 M2 눌림 / 🔥 저점선점 / ⚠️ 분류대기",
            "- 제외대상: reject, active_duplicate, max_active_limit, 진입 전 pending_timeout, chase_over_before_entry",
            gen,
            f"- 진행 중 350 본선 추정: OPEN {open_n} / PENDING {pending_n} / 전체 {len(main_active)}",
            _v296_stats_line("최근 6시간 350 본선 실제청산", w6),
            _v296_stats_line("최근 12시간 350 본선 실제청산", w12),
            "", "🔥 M2 눌림 재확인(350 본선 확정 근거)",
            "- " + _v296_stats_line("최근 6시간", [r for r in m2_closed if now_ts-_v296_row_ts(r)<=6*3600]).replace("📊 ", ""),
            "🔥 저점선점 보조(350 본선 확정 근거)",
            "- " + _v296_stats_line("최근 6시간", [r for r in low_closed if now_ts-_v296_row_ts(r)<=6*3600]).replace("📊 ", ""),
            "", "[최근 350 본선 실제 청산 표본]",
        ]
        stats += (_v210_closed_lines(main_closed, 8) or ["- 350 본선 실제 청산 표본 없음", "- 표본이 0이면 전략 삭제보다 route 분류 키워드 부족을 먼저 의심"])
        stats += [
            "", "[v2.10.8 집계 기준]",
            f"- raw closed {len(raw_closed)}개 / 실제진입 청산 {len(actual_closed)}개 / 350 본선 추정 {len(main_closed)}개 / 분류대기 {len(legacy_closed)}개",
            f"- 현재 진행 raw {len(active_all)}개 / 350 본선 추정 {len(main_active)}개 / 분류대기 {len(legacy_active)}개",
            f"- 진입 전 만료·reject성 closed 제외 {len(non_entry_closed)}개 / reject·보류 {len(reject_rows)}개",
            "- 350에서 승률 좋았던 본선 route는 차단하지 않고, 먼저 표시·분류만 함.",
        ]
        flow = [
            "🧪 350 본선 모의매매 흐름 /paper_flow",
            "- 기준: 최근 30분 / v2.10.8 350기준 캐시 단일화",
            gen,
            f"- attempts {len(attempts30)} / rejected {len(rejects30)} / 350 본선 진행 {len(main_active)} / 분류대기 진행 {len(legacy_active)}",
            _v296_stats_line("최근 30분 350 본선 실제청산", w30),
            "", "🔥 현재 진행 350 본선 추정",
        ]
        flow += (_v210_active_lines(main_active, 8) or ["- 현재 진행 350 본선 추정 없음"])
        if legacy_active:
            flow += ["", "⚠️ 현재 진행 분류대기/legacy"] + _v210_active_lines(legacy_active, 4)
        flow += ["", "🔥 최근 350 본선 실제 청산"]
        flow += (_v210_closed_lines(w30 or main_closed, 6) or ["- 최근 350 본선 실제 청산 없음"])
        try:
            rej = _v296_reject_summary(rejects30 or reject_rows, 5)
        except Exception:
            rej = []
        if rej:
            flow += ["", "🧯 보류/거절 요약"] + rej
        flow += ["", "📌 원칙: 350 본선일 수 있는 route는 차단하지 않고 강하게 표시. 손익은 실제진입 청산만 반영."]
        recent = [
            "🧾 최근 350 본선 모의매매 /paper_recent",
            "- v2.10.8 350기준 캐시 단일화 / 실제 주문 아님",
            gen,
            "", "🔥 현재 진행 350 본선 추정",
        ]
        recent += (_v210_active_lines(main_active, 8) or ["- 현재 진행 350 본선 추정 없음"])
        if legacy_active:
            recent += ["", "⚠️ 현재 진행 분류대기/legacy"] + _v210_active_lines(legacy_active, 4)
        recent += ["", "🔥 최근 350 본선 실제 청산"]
        recent += (_v210_closed_lines(main_closed, 8) or ["- 최근 350 본선 실제 청산 없음"])
        try:
            rej2 = _v296_reject_summary(reject_rows, 4)
        except Exception:
            rej2 = []
        if rej2:
            recent += ["", "🧯 최근 보류/거절 요약"] + rej2
        cache = {
            "created_ts": now_ts, "ts": now_ts,
            "paper_cache_version": "v2.10.8_350_unified",
            "paper_cache_note": "350본선 paper 캐시 직접복구",
            "stats": "\n".join(stats), "flow": "\n".join(flow), "recent": "\n".join(recent),
            "active": len(main_active), "open": open_n, "pending": pending_n,
            "closed_cache": len(main_closed), "reject_cache": len(reject_rows), "attempt_cache": len(attempts),
            "excluded_active": len(legacy_active), "excluded_closed": len(legacy_closed),
            "v210_main_active": len(main_active), "v210_main_closed": len(main_closed),
            "v210_legacy_active": len(legacy_active), "v210_legacy_closed": len(legacy_closed),
            "v210_non_entry_closed": len(non_entry_closed), "last_build_sec": elapsed,
        }
        try:
            with V296_PAPER_COMMAND_CACHE_LOCK:
                V296_PAPER_COMMAND_CACHE.clear(); V296_PAPER_COMMAND_CACHE.update(cache)
        except Exception:
            globals()["V296_PAPER_COMMAND_CACHE"] = cache
        try:
            V296_PAPER_COMMAND_CACHE_STATS.update({"done": int(V296_PAPER_COMMAND_CACHE_STATS.get("done",0))+1, "last_ts": now_ts, "last_duration": elapsed, "last_error": ""})
        except Exception:
            pass
        try:
            _v298_record_worker("paper_cache", elapsed)
        except Exception:
            pass
        return cache
    except Exception as e:
        try:
            append_runtime_error_log("v2103_paper_cache", str(e), exc=e, include_traceback=False)
            V296_PAPER_COMMAND_CACHE_STATS.update({"fail": int(V296_PAPER_COMMAND_CACHE_STATS.get("fail",0))+1, "last_ts": _v2103_now(), "last_error": f"{e.__class__.__name__}: {str(e)[:120]}"})
        except Exception:
            pass
        return {}

