def scan_watchlist(shared_cache=None):
    """v2.10.8: 350 본선 조건은 유지하고, scan 내부 작업대상/legacy 추적만 줄인다."""
    global V2104_SCAN_LAST_NOTE
    started_at = _v2104_now()
    try:
        mark_main_loop_heartbeat(stage="scan_watchlist_v2104")
    except Exception:
        pass
    cache = shared_cache if isinstance(shared_cache, dict) and shared_cache else (shared_market_cache if isinstance(globals().get("shared_market_cache", None), dict) and shared_market_cache else None)
    if not cache:
        try:
            v295_seed_market_cache_from_bulk(force=False, limit=V295_HUB_SEED_LIMIT)
            cache = shared_market_cache if isinstance(shared_market_cache, dict) and shared_market_cache else None
        except Exception:
            pass
    if not cache:
        try:
            request_market_refresh(force=True, reason="empty_cache_v2104")
        except Exception:
            pass
        try:
            _save_fast_scan_state([], note="시장 허브 보충 중", stage="scan_watchlist_empty_v2104", cache_age=None)
        except Exception:
            pass
        try:
            mark_main_loop_heartbeat(stage="scan_watchlist_empty_done_v2104")
        except Exception:
            pass
        _v2104_record_stage("total", _v2104_now() - started_at)
        V2104_SCAN_LAST_NOTE = "시장캐시 없음 / 허브보충 요청"
        return
    cache_age = int(started_at - shared_market_cache_time) if globals().get("shared_market_cache_time", 0) else None
    if cache_age is not None and cache_age >= max(FAST_SCAN_BUILD_CACHE_MAX_AGE_SEC, V295_HUB_STALE_SEC * 2):
        try:
            request_market_refresh(force=False, reason="scan_watchlist_cache_stale_v2104")
        except Exception:
            pass
    try:
        st = _v2104_now()
        work_cache = _v2104_limit_scan_cache(cache)
        _v2104_record_stage("cache_select", _v2104_now() - st)
    except Exception:
        work_cache = cache
    try:
        st = _v2104_now()
        work_cache = enrich_cache_with_light_snapshots(work_cache)
        _v2104_record_stage("snapshot_enrich", _v2104_now() - st)
    except Exception:
        pass
    try:
        st = _v2104_now()
        items = build_fast_scan_candidates_from_cache(work_cache, limit=FAST_SCAN_RESULT_MAX)
        _v2104_record_stage("candidate_build", _v2104_now() - st)
    except Exception as e:
        items = []
        try:
            append_runtime_error_log("v2104_fast_scan_build", str(e), exc=e, include_traceback=False)
        except Exception:
            pass

    try:
        st = _v2104_now()
        _v2148_restore_350_internal_watch_bridge(items, now_ts=_v2104_now())
        _v2104_record_stage("internal_watch_bridge", _v2104_now() - st)
    except Exception:
        pass

    try:
        st = _v2104_now()
        _save_fast_scan_state(items, note="v2.10.48 350흐름 빠른 후보 스캔", stage="scan_watchlist_v2148", cache_age=cache_age)
        _v2104_record_stage("state_save", _v2104_now() - st)
    except Exception:
        pass
    try:
        st = _v2104_now()
        _send_fast_scan_alerts(items, started_at)
        _v2104_record_stage("alert_send", _v2104_now() - st)
    except Exception as e:
        try:
            append_runtime_error_log("v2104_fast_scan_alert", str(e), exc=e, include_traceback=False)
        except Exception:
            pass
    try:
        total_sec = _v2104_now() - started_at
        _v2104_record_stage("total", total_sec)
        _v298_record_worker("scan_watchlist", total_sec)
        V291_SCAN_STAGE_TIMINGS["scan_total"] = round(total_sec, 4)
        V2104_SCAN_LAST_NOTE = f"작업대상 {len(work_cache) if isinstance(work_cache, dict) else 0}개 → 후보 {len(items or [])}개"
        mark_main_loop_heartbeat(stage="scan_watchlist_done_v2104")
    except Exception:
        pass

