def batch_command(update=None, context=None):
    try:
        text=_update_text(update); rows=_extract_batch_command_lines(text, skip_batch_header=True)
        if not rows:
            args=list(getattr(context,'args',[]) or []); joined=' '.join(args).strip()
            if joined.startswith('/'): rows=[joined]
        return run_batch_command_lines(rows, source_label='/batch')
    except Exception as e:
        try: send(f"⚠️ /batch 오류: {e.__class__.__name__}: {str(e)[:160]}")
        except Exception: pass

