def _v2107_record_candidate_stage(name: str, sec: float, add_total: bool = False, skipped: bool = False):
    try:
        row = V2107_CANDIDATE_STAGE_STATS.setdefault(str(name), {"last_sec": 0.0, "max_sec": 0.0, "count": 0, "last_ts": 0.0})
        sec = max(0.0, float(sec or 0.0))
        row["last_sec"] = round(sec, 4)
        row["max_sec"] = round(max(float(row.get("max_sec", 0) or 0), sec), 4)
        row["count"] = int(row.get("count", 0) or 0) + 1
        row["last_ts"] = _v2107_now()
        if add_total:
            row["total_sec"] = round(float(row.get("total_sec", 0) or 0) + sec, 4)
        if skipped:
            row["skipped"] = int(row.get("skipped", 0) or 0) + 1
    except Exception:
        pass

def _v2107_stage_state(sec: float) -> str:
    try:
        sec = float(sec or 0)
    except Exception:
        sec = 0.0
    if sec >= 2.0:
        return "bad"
    if sec >= 0.5:
        return "warn"
    return "ok"

