def _v2109_upper_ticker(row) -> str:
    try:
        if not isinstance(row, dict):
            return ""
        for k in ("ticker", "symbol", "market", "coin", "code"):
            v = row.get(k)
            if v:
                t = str(v).upper().replace("KRW-", "").strip()
                if t:
                    return t
        if callable(globals().get('_v336_ticker')):
            return str(_v336_ticker(row) or "").upper().replace("KRW-", "").strip()
    except Exception:
        pass
    return ""

def _v2109_active_count() -> int:
    try:
        if callable(globals().get('_paper_open_rows_v258')):
            return len(_paper_open_rows_v258() or [])
    except Exception:
        pass
    try:
        with PAPER_STATE_LOCK:
            return sum(1 for v in (paper_positions or {}).values() if isinstance(v, dict) and str(v.get('status','')).upper() in {'PENDING','OPEN'})
    except Exception:
        return 0

def _v2109_note_fast_skip(reason: str, ticker: str):
    try:
        reason = str(reason or 'skip')
        V2109_FAST_SKIP_STATS[reason] = int(V2109_FAST_SKIP_STATS.get(reason, 0) or 0) + 1
        V2109_FAST_SKIP_STATS['last_reason'] = reason
        V2109_FAST_SKIP_STATS['last_ticker'] = str(ticker or '?')
        V2109_FAST_SKIP_STATS['last_ts'] = _v2109_now()
        _v2109_record_stage('paper_register_fast_skip', 0.0, add_total=True)
    except Exception:
        pass

def _v2109_paper_fast_block(row, trigger: str = 'auto'):
    """깊은 paper 등록 전에 결과가 이미 거절로 확정되는 사유만 빠르게 걸러낸다.
    350 본선 조건 변경이 아니라, 기존 v336 엔진도 어차피 False 처리하던 hard-block만 선차단한다.
    """
    st = _v2109_now()
    try:
        if not globals().get('PAPER_TRADING_ON', True):
            return True, 'paper_off', ''
        rr = row if isinstance(row, dict) else {}
        ticker = _v2109_upper_ticker(rr)
        if not ticker:

            V2109_FAST_SKIP_STATS['missing_ticker'] = int(V2109_FAST_SKIP_STATS.get('missing_ticker', 0) or 0) + 1
            return False, '', ''

        try:
            if callable(globals().get('_v336_has_active_ticker')) and _v336_has_active_ticker(ticker):
                return True, 'active_duplicate', ticker
        except Exception:
            pass

        try:
            now_ts = _v2109_now()
            if callable(globals().get('_paper_recent_closed_cooldown_v258')) and _paper_recent_closed_cooldown_v258(ticker, now_ts):
                return True, 'recent_closed_cooldown', ticker
        except Exception:
            pass

        try:
            max_active = int(globals().get('PAPER_MAX_ACTIVE', 0) or 0)
            if max_active > 0 and _v2109_active_count() >= max_active:
                return True, 'max_active_limit', ticker
        except Exception:
            pass
        return False, '', ticker
    finally:
        _v2109_record_stage('paper_register_precheck', _v2109_now() - st, add_total=True)

