if callable(_BASE_PAPER_REGISTER_CANDIDATE_V2109):
    def paper_register_candidate_v258(row: dict, trigger: str = 'auto') -> bool:
        try:
            blocked, reason, ticker = _v2109_paper_fast_block(row, trigger=trigger)
            if blocked:
                if reason not in {'paper_off'}:
                    _v2109_note_fast_skip(reason, ticker)
                return False
            V2109_FAST_SKIP_STATS['passed_to_base'] = int(V2109_FAST_SKIP_STATS.get('passed_to_base', 0) or 0) + 1
            return bool(_BASE_PAPER_REGISTER_CANDIDATE_V2109(row, trigger=trigger))
        except Exception as e:
            try: append_runtime_error_log('v2109_paper_fast_register', str(e), exc=e, include_traceback=False)
            except Exception: pass

            try:
                return bool(_BASE_PAPER_REGISTER_CANDIDATE_V2109(row, trigger=trigger))
            except Exception:
                return False

