def _v2112_clean_text(txt: str) -> str:
    """출력 문자열에 남은 v2.10.1111/v2.10.91류 표시 꼬임만 보정한다."""
    t = str(txt or '')

    t = re.sub(r'수익형\s+v2\.10\.\d{3,}', BOT_VERSION, t)
    t = re.sub(r'수익형_v2\.10\.9\d+\.py', '수익형_v2.10.12.py', t)
    t = t.replace('수익형 v2.10.11', BOT_VERSION)
    t = t.replace('수익형 v2.10.10', BOT_VERSION)
    t = t.replace('v2.10.1111', 'v2.10.12')
    t = t.replace('v2.10.1000', 'v2.10.12')
    t = t.replace('v2.10.91', 'v2.10.12')
    t = t.replace('v2.10.90', 'v2.10.12')
    return t

def _v2105_normalize_text(txt: str) -> str:

    return _v2112_clean_text(txt)

def _v2112_line_find(txt: str, starts=(), contains=()):
    try:
        for ln in str(txt or '').splitlines():
            s = ln.strip()
            if starts and any(s.startswith(x) for x in starts):
                return s
            if contains and all(x in s for x in contains):
                return s
    except Exception:
        pass
    return ''

