def _v2112_classify(row) -> str:
    try:
        fn = globals().get('v210_classify_strategy')
        if callable(fn):
            key, _label, _why = fn(row)
            key = str(key or 'unknown')
            if key in {'main','main_guess','main_confirm','350','pullback'}:
                return 'main'
            if key in {'m2','low'}:
                return key
            return 'unknown'
    except Exception:
        pass
    txt = _v2112_text_blob(row)
    if any(w in txt for w in ('m2','눌림재확인','눌림 재확인','recheck','재확인')):
        return 'm2'
    if any(w in txt for w in ('저점선점','저점방어','low_preempt','low_defense')):
        return 'low'
    if any(w in txt for w in ('pullback','v313','v343','pullback_wait','good_pullback','factory_stage','central_missing','눌림')):
        return 'main'
    return 'unknown'

def _v2112_is_actual_closed(row) -> bool:
    try:
        fn = globals().get('_v210_is_actual_trade_closed')
        if callable(fn):
            return bool(fn(row))
    except Exception:
        pass
    if not isinstance(row, dict):
        return False
    txt = _v2112_text_blob(row)
    if any(w in txt for w in ('reject','active_duplicate','max_active_limit','pending_timeout','chase_over_before_entry','before_entry')):
        return False
    st = _v2112_status(row).upper()
    return st in {'CLOSED','EXIT','DONE','SELL','SOLD'} or bool(row.get('close_reason') or row.get('exit_reason'))

def _v2112_snapshot_groups() -> dict:
    try:
        snap_fn = globals().get('_v296_paper_snapshot')
        if not callable(snap_fn):
            return {'error': 'paper snapshot 함수 없음'}
        positions, logs, attempts, rejects = snap_fn()
        now_ts = _v2112_now()
        raw_closed = [r for r in list(logs or []) if isinstance(r, dict)]
        actual_closed = [r for r in raw_closed if _v2112_is_actual_closed(r)]
        actual_closed.sort(key=lambda r: _v2112_row_ts(r), reverse=True)
        active_statuses = {'PENDING','OPEN','WATCH','READY','?'}
        active_all = [r for r in list(positions or []) if isinstance(r, dict) and _v2112_status(r).upper() in active_statuses]
        out = {
            'now_ts': now_ts,
            'raw_closed': raw_closed,
            'actual_closed': actual_closed,
            'main_closed': [], 'm2_closed': [], 'low_closed': [], 'unknown_closed': [],
            'active_all': active_all,
            'main_active': [], 'm2_active': [], 'low_active': [], 'unknown_active': [],
            'attempts': list(attempts or []), 'rejects': list(rejects or []),
        }
        for r in actual_closed:
            k = _v2112_classify(r)
            out.setdefault(f'{k}_closed', out['unknown_closed']).append(r)
        for r in active_all:
            k = _v2112_classify(r)
            out.setdefault(f'{k}_active', out['unknown_active']).append(r)
        return out
    except Exception as e:
        return {'error': f'{e.__class__.__name__}: {str(e)[:160]}'}

def _v2112_window_rows(rows, hours: int, now_ts: float) -> list:
    out = []
    cut = float(hours) * 3600.0
    for r in list(rows or []):
        ts = _v2112_row_ts(r)
        if ts > 0 and now_ts - ts <= cut:
            out.append(r)
    return out

def _v2112_perf(rows) -> dict:
    arr = [r for r in list(rows or []) if isinstance(r, dict)]
    n = len(arr)
    wins = sum(1 for r in arr if _v2112_pnl(r) > 0)
    losses = sum(1 for r in arr if _v2112_pnl(r) < 0)
    flats = max(0, n - wins - losses)
    ret = sum(_v2112_pnl(r) for r in arr)
    wr = wins / n * 100.0 if n else 0.0
    return {'n':n,'wins':wins,'losses':losses,'flats':flats,'ret':ret,'wr':wr}

def _v2112_perf_line(label: str, rows, hours: int, now_ts: float) -> str:
    p = _v2112_perf(_v2112_window_rows(rows, hours, now_ts))
    icon = '✅' if p['ret'] > 0 else ('⚠️' if p['n'] == 0 else '❌')
    flat = f" / 보합 {p['flats']}" if p['flats'] else ''
    return f"{icon} 최근 {label}: {p['n']}전 {p['wins']}승 {p['losses']}패{flat} / 승률 {p['wr']:.1f}% / 수익률 {p['ret']:+.2f}%"

def _v2112_active_summary(rows, label: str) -> str:
    rows = [r for r in list(rows or []) if isinstance(r, dict)]
    open_n = sum(1 for r in rows if _v2112_status(r).upper() == 'OPEN')
    pending_n = sum(1 for r in rows if _v2112_status(r).upper() == 'PENDING')
    sample = ', '.join(_v2112_ticker(r) for r in rows[:5]) if rows else '-'
    return f"- {label}: OPEN {open_n} / PENDING {pending_n} / 전체 {len(rows)} / 예: {sample}"

def _v2112_recent_closed_lines(rows, limit=4):
    out = []
    for i, r in enumerate(list(rows or [])[:int(limit)], 1):
        out.append(f"{i}. {_v2112_ticker(r)} / {_v2112_pnl(r):+.2f}% / {_v2112_reason(r)} / {_v2112_rule(r)}")
    return out or ['- 최근 청산 표본 없음']

