def _v2118_json_ready(data):
    try:
        fn = globals().get("make_json_safe_snapshot")
        if callable(fn):
            return fn(data)
    except Exception:
        pass
    return data

def _v2118_save_json_compact_atomic(path, data, stage_key: str):
    """paper 전용 저장. 실주문/보유 상태에는 쓰지 않는다.
    - indent 제거로 파일 크기 축소
    - fsync 제거로 후보등록 중 디스크 대기 감소
    - tempfile + os.replace 원자교체는 유지
    """
    st = _v2118_now()
    tmp_path = ""
    byte_len = 0
    try:
        target_dir = os.path.dirname(os.path.abspath(path)) or "."
        safe = _v2118_json_ready(data)
        payload = json.dumps(safe, ensure_ascii=False, separators=(",", ":"), default=str)
        byte_len = len(payload.encode("utf-8", errors="ignore"))
        fd, tmp_path = tempfile.mkstemp(prefix=os.path.basename(path) + ".", suffix=".tmp", dir=target_dir)
        with os.fdopen(fd, "w", encoding="utf-8") as f:
            f.write(payload)
            f.flush()

        os.replace(tmp_path, path)
        tmp_path = ""
        V2118_PAPER_SAVE_STATS["bytes_written"] = int(V2118_PAPER_SAVE_STATS.get("bytes_written", 0) or 0) + int(byte_len)
        return byte_len
    except Exception as e:
        V2118_PAPER_SAVE_STATS["last_error"] = f"{e.__class__.__name__}: {str(e)[:120]}"
        try:
            if tmp_path and os.path.exists(tmp_path):
                os.remove(tmp_path)
        except Exception:
            pass
        raise
    finally:
        _v2118_record_stage(stage_key, _v2118_now() - st, add_total=True)

def _v2118_save_if_changed(path, data, stage_key: str, sig_key: str, new_sig):
    st = _v2118_now()
    try:
        old_sig = V2118_PAPER_SAVE_SIGS.get(sig_key)
        if old_sig == new_sig:
            V2118_PAPER_SAVE_STATS["skip_unchanged"] = int(V2118_PAPER_SAVE_STATS.get("skip_unchanged", 0) or 0) + 1
            skipped = str(V2118_PAPER_SAVE_STATS.get("last_skipped_files", "") or "")
            V2118_PAPER_SAVE_STATS["last_skipped_files"] = (skipped + "," + sig_key).strip(",")[-120:]
            _v2118_record_stage(stage_key + "_skip_unchanged", _v2118_now() - st, add_total=True)
            return False
        _v2118_save_json_compact_atomic(path, data, stage_key)
        V2118_PAPER_SAVE_SIGS[sig_key] = new_sig
        V2118_PAPER_SAVE_STATS["compact_file_saved"] = int(V2118_PAPER_SAVE_STATS.get("compact_file_saved", 0) or 0) + 1
        saved = str(V2118_PAPER_SAVE_STATS.get("last_saved_files", "") or "")
        V2118_PAPER_SAVE_STATS["last_saved_files"] = (saved + "," + sig_key).strip(",")[-120:]
        return True
    except Exception:
        raise

def save_paper_state_v258(force: bool = False, reason: str = "auto"):
    """v2.10.18: paper 저장을 compact/최근 중심으로 한다.
    - 판정 로직은 그대로 둔다.
    - 디스크 저장 방식만 줄인다.
    - 실주문 상태 저장 함수는 건드리지 않는다.
    """
    global paper_trade_log, paper_entry_attempts_v336, paper_reject_log_v336
    whole_st = _v2118_now()
    saved_any = False
    try:
        snap_st = _v2118_now()
        with PAPER_STATE_LOCK:
            pos_snapshot = {str(k): dict(v) for k, v in (paper_positions or {}).items() if isinstance(v, dict)}

            paper_trade_log = [dict(x) for x in list(paper_trade_log or []) if isinstance(x, dict)][-PAPER_V336_MAX_LOG:]
            paper_entry_attempts_v336 = [dict(x) for x in list(paper_entry_attempts_v336 or []) if isinstance(x, dict)][-PAPER_V336_MAX_ATTEMPTS:]
            paper_reject_log_v336 = [dict(x) for x in list(paper_reject_log_v336 or []) if isinstance(x, dict)][-PAPER_V336_MAX_REJECTS:]

            log_snapshot = list(paper_trade_log)[-V2118_PAPER_DISK_MAX_LOG:]
            attempts_snapshot = list(paper_entry_attempts_v336)[-V2118_PAPER_DISK_MAX_ATTEMPTS:]
            rejects_snapshot = list(paper_reject_log_v336)[-V2118_PAPER_DISK_MAX_REJECTS:]
        _v2118_record_stage("paper_save_snapshot", _v2118_now() - snap_st, add_total=True)

        pos_sig = _v2118_positions_signature(pos_snapshot)
        log_sig = _v2118_list_signature(log_snapshot)
        attempts_sig = _v2118_list_signature(attempts_snapshot)
        reject_sig = _v2118_list_signature(rejects_snapshot)

        now_ts = _v2118_now()
        last_save_ts = _v2118_safe_float(V2118_PAPER_SAVE_STATS.get("last_save_ts", 0), 0)
        pos_changed = V2118_PAPER_SAVE_SIGS.get("positions") != pos_sig
        log_changed = V2118_PAPER_SAVE_SIGS.get("trade_log") != log_sig
        attempts_changed = V2118_PAPER_SAVE_SIGS.get("attempts") != attempts_sig
        reject_changed = V2118_PAPER_SAVE_SIGS.get("reject") != reject_sig

        only_attempt_reject = (not pos_changed) and (not log_changed) and (attempts_changed or reject_changed)
        if (not force) and only_attempt_reject and (now_ts - last_save_ts < V2118_PAPER_SAVE_MIN_INTERVAL_SEC):
            V2118_PAPER_SAVE_STATS["skip_interval"] = int(V2118_PAPER_SAVE_STATS.get("skip_interval", 0) or 0) + 1
            V2118_PAPER_SAVE_STATS["last_reason"] = "attempt_reject_interval_skip"
            _v2118_record_stage("paper_save_interval_skip", _v2118_now() - whole_st, add_total=True)
            return

        V2118_PAPER_SAVE_STATS["save_calls"] = int(V2118_PAPER_SAVE_STATS.get("save_calls", 0) or 0) + 1
        V2118_PAPER_SAVE_STATS["last_saved_files"] = ""
        V2118_PAPER_SAVE_STATS["last_skipped_files"] = ""

        saved_any |= _v2118_save_if_changed(
            PAPER_V336_POSITIONS_FILE,
            {"schema": PAPER_V336_SCHEMA, "updated_ts": now_ts, "positions": pos_snapshot},
            "paper_save_positions_file",
            "positions",
            pos_sig,
        )
        saved_any |= _v2118_save_if_changed(PAPER_V336_TRADE_LOG_FILE, log_snapshot, "paper_save_trade_log_file", "trade_log", log_sig)
        saved_any |= _v2118_save_if_changed(PAPER_V336_ATTEMPTS_FILE, attempts_snapshot, "paper_save_attempts_file", "attempts", attempts_sig)
        saved_any |= _v2118_save_if_changed(PAPER_V336_REJECT_LOG_FILE, rejects_snapshot, "paper_save_reject_file", "reject", reject_sig)

        if saved_any:
            V2118_PAPER_SAVE_STATS["last_save_ts"] = _v2118_now()
            V2118_PAPER_SAVE_STATS["last_reason"] = "compact_changed_files"
            try:
                PAPER_V258_STATS["last_save_ts"] = _v2118_now()
                _v336_inc("save", "v2118 paper compact 저장")
            except Exception:
                pass
        else:
            V2118_PAPER_SAVE_STATS["last_reason"] = "all_unchanged"
            _v2118_record_stage("paper_save_all_unchanged", _v2118_now() - whole_st, add_total=True)
    except Exception as e:
        V2118_PAPER_SAVE_STATS["last_error"] = f"{e.__class__.__name__}: {str(e)[:120]}"
        try:
            append_runtime_error_log("save_paper_state_v2118", str(e), exc=e, include_traceback=False)
        except Exception:
            pass
        try:
            if callable(_BASE_SAVE_PAPER_STATE_V2118):
                return _BASE_SAVE_PAPER_STATE_V2118(force=force, reason=reason)
        except TypeError:
            try:
                return _BASE_SAVE_PAPER_STATE_V2118()
            except Exception:
                pass
        except Exception:
            pass
    finally:
        _v2118_record_stage("paper_save_total", _v2118_now() - whole_st, add_total=True)

