def _v2123_age(ts) -> str:
    try:
        fn = globals().get('_v2112_age_text') or globals().get('_v297_age_text') or globals().get('_v21020_age')
        if callable(fn):
            return str(fn(ts))
    except Exception:
        pass
    try:
        sec = max(0, int(_v2123_now() - float(ts or 0)))
        if sec < 60:
            return f"{sec}초 전"
        return f"{sec//60}분 {sec%60}초 전"
    except Exception:
        return "정보 없음"

def _v2123_safe_float(v, d=0.0):
    try:
        fn = globals().get('safe_float')
        if callable(fn):
            return float(fn(v, d))
        return float(v)
    except Exception:
        return float(d)

