def _v2123_market_line() -> str:
    try:
        cache = globals().get('shared_market_cache', None)
        if not isinstance(cache, dict) or not cache:
            cache = globals().get('market_cache', {})
        n = len(cache) if hasattr(cache, '__len__') else 0
        ts = globals().get('shared_market_cache_ts', 0) or globals().get('market_cache_ts', 0) or globals().get('last_market_cache_ts', 0)
        age = f" / {_v2123_age(ts)}" if _v2123_safe_float(ts, 0) > 0 else ""
        return f"- 시장캐시: {n}개{age}"
    except Exception:
        return "- 시장캐시: 확인필요"

