def _v2141_float(v, default=0.0):
    try:
        return float(v)
    except Exception:
        return default

def _v2141_int(v, default=0):
    try:
        return int(float(v))
    except Exception:
        return default

def _v2141_now():
    try:
        return time.time()
    except Exception:
        return 0.0

def _v2141_age(ts) -> str:
    try:
        ts = _v2141_float(ts, 0)
        if ts <= 0:
            return "수신 전"
        sec = max(0, int(_v2141_now() - ts))
        if sec < 60:
            return f"{sec}초 전"
        if sec < 3600:
            return f"{sec//60}분 {sec%60}초 전"
        return f"{sec//3600}시간 {(sec%3600)//60}분 전"
    except Exception:
        return "확인불가"

def _v2141_data_file(name: str) -> str:
    try:
        return data_file(name)
    except Exception:
        try:
            return os.path.join(BASE_DIR, name)
        except Exception:
            return name

def _v2141_read_text(path: str) -> str:
    try:
        with open(path, 'r', encoding='utf-8', errors='ignore') as f:
            return f.read().strip()
    except Exception:
        return ''

def _v2141_version_num(text: str) -> str:
    try:
        m = re.search(r"v(\d+\.\d+\.\d+)", str(text or ''))
        return m.group(1) if m else ''
    except Exception:
        return ''

def _v2141_deploy_state() -> dict:
    target = _v2141_read_text(_v2141_data_file('DEPLOY_TARGET.txt')) or _v2141_read_text(_v2141_data_file('.deploy_target'))
    deployed = _v2141_read_text(_v2141_data_file('.deployed_target')) or target
    rv = _v2141_version_num(BOT_VERSION)
    tv = _v2141_version_num(target)
    dv = _v2141_version_num(deployed)
    return {"target": target, "deployed": deployed, "rv": rv, "tv": tv, "dv": dv, "ok": bool(rv and tv and dv and rv == tv == dv)}

def _v2141_file_lines() -> int:
    try:
        path = globals().get('__file__') or ''
        if path and os.path.exists(path):
            with open(path, 'r', encoding='utf-8', errors='ignore') as f:
                return sum(1 for _ in f)
    except Exception:
        pass
    return 0

def _v2141_boot_error_text(max_lines: int = 20) -> str:
    try:
        fn = globals().get('read_runtime_error_log_current_boot')
        if callable(fn):
            return str(fn(max_lines=max_lines) or '').strip()
    except Exception:
        pass
    try:
        return str(globals().get('LAST_RUNTIME_ERROR', '') or '').strip()
    except Exception:
        return ''

def _v2141_save_stats() -> tuple:
    for name in ('V2118_PAPER_SAVE_STATS', 'PAPER_COMPACT_SAVE_STATS', 'PAPER_SAVE_STATS'):
        st = globals().get(name)
        if isinstance(st, dict):
            return name.replace('V2118_PAPER_SAVE_STATS', 'V2118'), _v2141_int(st.get('compact_file_saved', st.get('saved', 0))), _v2141_int(st.get('skip_unchanged', st.get('unchanged', 0))), _v2141_int(st.get('skip_interval', st.get('interval', 0)))
    return '없음', 0, 0, 0

def _v2141_ws_snapshot() -> dict:
    now_ts = _v2141_now()
    out = {"price_count": 0, "price_age": 999999, "price_status": "확인필요", "price_ok": False,
           "trade_count": 0, "trade_age": 999999, "trade_status": "확인필요", "trade_ok": False}
    try:
        fn = globals().get('get_ws_ticker_status_snapshot')
        st = fn() if callable(fn) else {}
        if isinstance(st, dict):
            cnt = _v2141_int(st.get('cache_count', st.get('live_count', st.get('price_count', 0))), 0)
            age = st.get('last_msg_age_sec')
            if age is None:
                age = max(0, int(now_ts - _v2141_float(st.get('last_msg_ts', 0), 0))) if _v2141_float(st.get('last_msg_ts', 0), 0) > 0 else 999999
            status = str(st.get('status', '대기') or '대기')
            out.update({"price_count": cnt, "price_age": _v2141_int(age, 999999), "price_status": status,
                        "price_ok": bool(cnt > 0 and _v2141_int(age, 999999) <= 90 and ('수신' in status or '연결' in status or status not in {'대기','확인필요'}) )})
    except Exception:
        pass
    try:
        fn = globals().get('get_ws_trade_status_snapshot')
        st = fn() if callable(fn) else {}
        if isinstance(st, dict):
            cnt = _v2141_int(st.get('cache_count', st.get('live_count', st.get('code_count', 0))), 0)
            age = st.get('last_msg_age_sec')
            if age is None:
                age = max(0, int(now_ts - _v2141_float(st.get('last_msg_ts', 0), 0))) if _v2141_float(st.get('last_msg_ts', 0), 0) > 0 else 999999
            status = str(st.get('status', '대기') or '대기')
            out.update({"trade_count": cnt, "trade_age": _v2141_int(age, 999999), "trade_status": status,
                        "trade_ok": bool(cnt > 0 and _v2141_int(age, 999999) <= 120 and ('수신' in status or '연결' in status or status not in {'대기','확인필요'}) )})
    except Exception:
        pass
    return out

def _v2141_ws_line(kind='price') -> str:
    ws = _v2141_ws_snapshot()
    if kind == 'trade':
        ok = ws.get('trade_ok'); cnt = ws.get('trade_count', 0); age = ws.get('trade_age', 999999); st = ws.get('trade_status', '확인필요')
        return f"{'✅' if ok else '⚠️'} WebSocket 체결: {cnt}종목 / 마지막 {_v2141_age(_v2141_now()-age) if age < 999999 else '수신 전'} / {st}"
    ok = ws.get('price_ok'); cnt = ws.get('price_count', 0); age = ws.get('price_age', 999999); st = ws.get('price_status', '확인필요')
    return f"{'✅' if ok else '⚠️'} WebSocket 현재가: {cnt}개 / 마지막 {_v2141_age(_v2141_now()-age) if age < 999999 else '수신 전'} / {st}"

def _v2141_market_count() -> int:
    try:
        cache = globals().get('shared_market_cache', {})
        return len(cache) if isinstance(cache, dict) else 0
    except Exception:
        return 0

def _v2141_paper_snapshot() -> dict:
    try:
        p = globals().get('V296_PAPER_COMMAND_CACHE', {})
        if not isinstance(p, dict):
            p = {}
        return {
            'active': _v2141_int(p.get('v210_main_active', p.get('active', 0)), 0),
            'closed': _v2141_int(p.get('v210_main_closed', p.get('closed_cache', 0)), 0),
            'ts': _v2141_float(p.get('created_ts', p.get('ts', 0)), 0),
        }
    except Exception:
        return {'active': 0, 'closed': 0, 'ts': 0}

def build_startup_auto_check_text() -> str:
    dep = _v2141_deploy_state(); ws = _v2141_ws_snapshot(); p = _v2141_paper_snapshot(); src, saved, unchanged, interval = _v2141_save_stats(); err = _v2141_boot_error_text(20)
    return '\n'.join([
        '🚀 코인봇 부팅 자동점검',
        f'- 버전: {BOT_VERSION}', '',
        '1. 실행 상태',
        f"{'✅' if dep.get('ok') else '⚠️'} 실행/목표/적용: {dep.get('rv') or '?'} / {dep.get('tv') or '?'} / {dep.get('dv') or '?'}",
        f"✅ 메인루프: {_v2141_age(globals().get('last_main_loop_heartbeat_ts', 0))} / 작업 {globals().get('last_main_loop_stage', '?')}",
        f"✅ 시장캐시: {_v2141_market_count()}개", '',
        '2. WebSocket',
        f"{'✅' if ws.get('price_ok') else '⚠️'} 현재가: {ws.get('price_count',0)}개 / 마지막 {ws.get('price_age',999999)}초 전 / {ws.get('price_status')}",
        f"{'✅' if ws.get('trade_ok') else '⚠️'} 체결: {ws.get('trade_count',0)}종목 / 마지막 {ws.get('trade_age',999999)}초 전 / {ws.get('trade_status')}", '',
        '3. paper/저장',
        f"✅ paper: 진행 {p.get('active',0)}개 / 실제청산 {p.get('closed',0)}개 / 캐시 {_v2141_age(p.get('ts',0))}",
        f"✅ 저장: compact {saved} / 변경없음 {unchanged} / interval {interval} ({src})", '',
        '4. 오류/감시',
        f"{'✅' if not err else '⚠️'} 오류: {'현재 부팅 새 오류 없음' if not err else '오류 있음 /errorlog 확인'}",
        f"✅ 자동감시: {'ON' if _v2141_monitor_enabled() else 'OFF'} / 문제 있을 때만 알림", '',
        '📌 확인: /main /monitor /errorlog /upgradestatus',
        '🔧 상세: /batch /prune_check /dev',
    ])

def _v2141_startup_stamp_path():
    return _v2141_data_file('.startup_auto_check_v2141.json')

def _v2141_startup_allowed() -> bool:
    try:
        p = _v2141_startup_stamp_path(); now = _v2141_now(); prev = {}
        if os.path.exists(p):
            with open(p, 'r', encoding='utf-8') as f:
                prev = json.load(f) or {}
        if now - _v2141_float(prev.get('ts', 0), 0) < V2141_STARTUP_CHECK_COOLDOWN_SEC:
            return False
        with open(p, 'w', encoding='utf-8') as f:
            json.dump({'ts': now, 'version': BOT_VERSION}, f, ensure_ascii=False)
        return True
    except Exception:
        return True

def _v2141_send_startup_auto_check():
    global V2141_STARTUP_CHECK_SENT
    try:
        if V2141_STARTUP_CHECK_SENT:
            return
        if not _v2141_startup_allowed():
            return
        V2141_STARTUP_CHECK_SENT = True
        send_text_chunks(build_startup_auto_check_text(), limit=2600)
    except Exception as e:
        try: append_runtime_error_log('v2141_startup_auto_check', str(e), exc=e, include_traceback=False)
        except Exception: pass

def _v2141_schedule_startup_auto_check():
    try:
        def _run():
            try:
                time.sleep(V2141_STARTUP_CHECK_DELAY_SEC)
                _v2141_send_startup_auto_check()
            except Exception:
                pass
        threading.Thread(target=_run, daemon=True, name='startup_auto_check_v2141').start()
    except Exception:
        pass

def _v2141_monitor_path():
    return _v2141_data_file('monitor_state_v2141.json')

def _v2141_load_monitor() -> dict:
    try:
        p = _v2141_monitor_path()
        if os.path.exists(p):
            with open(p, 'r', encoding='utf-8') as f:
                data = json.load(f) or {}
                return data if isinstance(data, dict) else {}
    except Exception:
        pass
    return {'enabled': True}

def _v2141_save_monitor(data: dict):
    try:
        with open(_v2141_monitor_path(), 'w', encoding='utf-8') as f:
            json.dump(data or {}, f, ensure_ascii=False, indent=2)
    except Exception:
        pass

def _v2141_monitor_enabled() -> bool:
    try:
        return bool(_v2141_load_monitor().get('enabled', True))
    except Exception:
        return True

def _v2141_collect_issues() -> list:
    issues = []
    try:
        dep = _v2141_deploy_state()
        if not dep.get('ok'):
            issues.append(f"실행/목표/적용 불일치 {dep.get('rv')}/{dep.get('tv')}/{dep.get('dv')}")
    except Exception:
        pass
    try:
        loop_age = _v2141_now() - _v2141_float(globals().get('last_main_loop_heartbeat_ts', 0), 0)
        if loop_age > 120:
            issues.append(f"메인루프 {int(loop_age)}초 지연")
    except Exception:
        pass
    try:
        ws = _v2141_ws_snapshot()
        if not ws.get('price_ok'):
            issues.append(f"WebSocket 현재가 확인필요 {ws.get('price_count',0)}개/{ws.get('price_age',999999)}초")
        if not ws.get('trade_ok'):
            issues.append(f"WebSocket 체결 확인필요 {ws.get('trade_count',0)}종목/{ws.get('trade_age',999999)}초")
    except Exception:
        pass
    try:
        if _v2141_market_count() <= 0:
            issues.append('시장캐시 0개')
    except Exception:
        pass
    try:
        p = _v2141_paper_snapshot()
        if p.get('ts', 0) > 0 and (_v2141_now() - p.get('ts', 0)) > 150:
            issues.append(f"paper 캐시 {int(_v2141_now()-p.get('ts',0))}초 지연")
    except Exception:
        pass
    try:
        if _v2141_boot_error_text(10):
            issues.append('현재 부팅 오류 있음')
    except Exception:
        pass
    return issues

def _v2141_monitor_sig(issues) -> str:
    try:
        return '|'.join(sorted(str(x) for x in issues or []))[:240]
    except Exception:
        return ''

def _v2141_monitor_alert_text(issues) -> str:
    lines = ['🚨 코인봇 자동감시 경고', f'- 버전: {BOT_VERSION}', '']
    for i, issue in enumerate(issues[:6], 1):
        lines.append(f'{i}. {issue}')
    lines += ['', '확인: /main /monitor /errorlog /upgradestatus', '상세: /dev']
    return '\n'.join(lines)

def _v2141_monitor_once(send_alert=True):
    global V2141_MONITOR_STATE
    issues = _v2141_collect_issues()
    sig = _v2141_monitor_sig(issues)
    now = _v2141_now()
    V2141_MONITOR_STATE.update({'last_check_ts': now, 'last_issues': list(issues)})
    if send_alert and issues:
        if sig != V2141_MONITOR_STATE.get('last_issue_sig') or now - _v2141_float(V2141_MONITOR_STATE.get('last_alert_ts', 0), 0) > 900:
            V2141_MONITOR_STATE['last_issue_sig'] = sig
            V2141_MONITOR_STATE['last_alert_ts'] = now
            try:
                send_text_chunks(_v2141_monitor_alert_text(issues), limit=2400)
            except Exception:
                pass
    return issues

def _v2141_monitor_loop():
    while True:
        try:
            if _v2141_monitor_enabled():
                _v2141_monitor_once(send_alert=True)
        except Exception as e:
            try: append_runtime_error_log('v2141_monitor_loop', str(e), exc=e, include_traceback=False)
            except Exception: pass
        try:
            time.sleep(V2141_MONITOR_INTERVAL_SEC)
        except Exception:
            time.sleep(300)

def _v2141_start_monitor_worker():
    global V2141_MONITOR_STARTED
    if V2141_MONITOR_STARTED:
        return
    V2141_MONITOR_STARTED = True
    try:
        threading.Thread(target=_v2141_monitor_loop, daemon=True, name='monitor_worker_v2141').start()
    except Exception:
        V2141_MONITOR_STARTED = False

def build_monitor_text() -> str:
    if _v2141_monitor_enabled():
        issues = _v2141_monitor_once(send_alert=False)
    else:
        issues = []
    last = _v2141_age(V2141_MONITOR_STATE.get('last_check_ts', 0)) if V2141_MONITOR_STATE.get('last_check_ts') else '아직 없음'
    alert = _v2141_age(V2141_MONITOR_STATE.get('last_alert_ts', 0)) if V2141_MONITOR_STATE.get('last_alert_ts') else '없음'
    lines = ['🛡 자동감시 /monitor', f'- 버전: {BOT_VERSION}', f"- 상태: {'✅ ON' if _v2141_monitor_enabled() else '⏸ OFF'}", '- 주기: 5분마다 확인 / 문제 있을 때만 알림', f'- 마지막 확인: {last}', f'- 마지막 알림: {alert}', '', '현재 판정:']
    if issues:
        lines += [f'⚠️ {x}' for x in issues[:6]]
    else:
        lines.append('✅ 현재 감시 기준 문제 없음')
    lines += ['', '명령어:', '- /monitor_on: 자동감시 켜기', '- /monitor_off: 자동감시 끄기', '- /startupcheck: 부팅점검 수동 확인']
    return '\n'.join(lines)

def _v2141_register_summary() -> str:
    return '- paper 등록: 최종함수·base chain·빠른차단·분류기 보존 / 구 작업지도 wrapper 삭제 유지'

def _v2141_update_next_summary() -> str:
    return '- paper 청산: slow/time/stop/protect는 성과판 연결이라 아직 삭제금지 / 다음판에서 사유별 호출경로만 인수인계서 기준으로 분리\n- 350 브릿지: scan 후보 일부를 internal_watch→v342/v343 눌림대기 소스로 제한 복구'

def build_dev_text() -> str:
    src, saved, unchanged, interval = _v2141_save_stats(); p = _v2141_paper_snapshot(); issues = _v2141_collect_issues()
    return '\n'.join([
        '🛠 내부 진단 /dev',
        f'- 버전: {BOT_VERSION}',
        '- 기준: 작업용 요약만 표시. 긴 지도/분리표는 인수인계서로 이동.', '',
        '1. 런타임',
        f"- 메인루프: {_v2141_age(globals().get('last_main_loop_heartbeat_ts', 0))} / 작업 {globals().get('last_main_loop_stage', '?')} / 시장캐시 {_v2141_market_count()}개",
        _v2141_ws_line('price'),
        _v2141_ws_line('trade'), '',
        '2. 자동감시',
        f"- monitor: {'ON' if _v2141_monitor_enabled() else 'OFF'} / {'✅ 문제 없음' if not issues else '⚠️ 확인필요'}", '',
        '3. paper/저장',
        f"- paper: 진행 {p.get('active',0)}개 / 실제청산 {p.get('closed',0)}개 / 캐시 {_v2141_age(p.get('ts',0))} / 저장 compact {saved}·변경없음 {unchanged}·interval {interval} ({src})",
        _v2141_register_summary(),
        _v2141_update_next_summary(), '',
        '4. 오류',
        f"- 오류: {'현재 부팅 새 오류 없음' if not _v2141_boot_error_text(20) else '오류 있음 /errorlog_full 확인'}", '',
        '5. 다음 작업',
        '- 다음판: v2.10.48 결과 확인 → /pullback 청산 표본 회복 여부 확인 → paper_update/scan 깊은 정리',
        '- 보류: 전략 조건·문턱·청산 로직·scan/watchlist 본체',
    ])

def build_prune_check_text() -> str:
    dep = _v2141_deploy_state(); boot = _v2141_boot_error_text(20); src, saved, unchanged, interval = _v2141_save_stats(); ws = _v2141_ws_snapshot(); cur = _v2141_file_lines()
    checks = [
        ('/main 출력', callable(globals().get('build_main_focus_text'))),
        ('/pullback 출력', callable(globals().get('build_pullback_focus_text'))),
        ('/errorlog 출력', callable(globals().get('build_errorlog_text'))),
        ('/dev 출력', callable(globals().get('build_dev_text'))),
        ('/monitor 출력', callable(globals().get('build_monitor_text'))),
        ('batch route', callable(globals().get('_v296_batch_text_for_command'))),
        ('manual route', callable(globals().get('handle_manual_command'))),
        ('자동감시 워커', callable(globals().get('_v2141_start_monitor_worker'))),
        ('paper 등록 최종함수', callable(globals().get('paper_register_candidate_v258'))),
        ('paper 청산 최종함수', callable(globals().get('paper_update_positions_once_v258'))),
    ]
    ok = bool(dep.get('ok')) and not boot and ws.get('price_ok') and ws.get('trade_ok') and all(v for _, v in checks)
    lines = ['🧹 가지치기 검수 /prune_check', f'- 버전: {BOT_VERSION}', f"- 종합: {'✅ 정상' if ok else '⚠️ 확인필요'}", '', '1. 배포/실행', f"{'✅' if dep.get('ok') else '❌'} 실행/목표/적용: 실행 {dep.get('rv') or '?'} / 목표 {dep.get('tv') or '?'} / 적용 {dep.get('dv') or '?'}", f"- 목표파일: {dep.get('target','정보 없음')}", f"- 적용파일: {dep.get('deployed','정보 없음')}", '', '2. 핵심 출력/연결']
    lines += [f"{'✅' if y else '❌'} {nm}" for nm, y in checks]
    lines += ['', '3. 오류/구버전 연결', f"{'✅' if not boot else '❌'} 현재 부팅 오류: {'0건' if not boot else '있음 /errorlog_full 확인'}", f"{'✅' if ws.get('price_ok') and ws.get('trade_ok') else '⚠️'} WebSocket 기준: 현재가 {ws.get('price_count',0)}개 / 체결 {ws.get('trade_count',0)}종목", f'✅ paper 저장: compact파일저장 {saved} / 변경없음 {unchanged} / interval생략 {interval} ({src})', '- v2.10.48: 350 기준 scan→내부감시→눌림대기 브릿지 복구', '', '4. 줄 수 변화', f'- 이전: {V2141_PREV_VERSION} / {V2141_PREV_LINES:,}줄', f'- 이번: v2.10.47 / {cur:,}줄' if cur else '- 이번: v2.10.47 / 확인불가', f'- 변화: {cur - V2141_PREV_LINES:+,}줄' if cur else '- 변화: 확인불가', '- 성격: 메뉴등록 최종고정 + zero-ref/scan 주변 helper 대삭제 + 지도는 인수인계서 중심', '', '5. 남은 작업량', '- 전체 정리: 4분의 3 조금 넘게 완료', '- 거의 끝난 쪽: 출력 wrapper / 배포·검수 / 자동점검·감시', '- 지금 할 쪽: paper 등록 남은 wrapper 실제 삭제', '- 많이 남은 쪽: paper 청산 체인 / scan-watchlist / 350 실전 흐름 비교', '- 다음판 목표: paper_update 청산 사유별 호출경로 분리 후 안전삭제 후보 추리기', '', '📌 확인 묶음', '- /batch /prune_check /main /monitor /dev /errorlog /upgradestatus', '', '🛡 삭제 안전판 v2.10.47', '- 350 전략 조건·문턱·paper 판정·청산 로직 변경 없음', '- 삭제한 것은 정적참조 0개 함수와 scan/review/rank 주변 미사용 출력·진단 helper 중심', '- 최종 등록/base chain/빠른차단/분류기/청산 성과판은 보존']
    return '\n'.join(lines)

def build_startup_message() -> str:
    return '\n'.join([f'🚀 {BOT_VERSION} 시작', '- v2.10.47: 메뉴최종고정 + zero-ref 대삭제 / 실사용 경로 유지', '- 전략 조건·350 본선·paper 판정 변경 없음', '- 확인: /main /monitor /errorlog /upgradestatus'])

def build_startup_notice_text() -> str:
    return build_startup_message()

def build_cache_status_text() -> str:
    return '🧩 캐시 상태\n- 평소 확인은 /main\n- 자동감시는 /monitor\n- 작업용 상세는 /dev'

def build_cache_status_full_text() -> str:
    return build_dev_text()

def build_errorlog_text(limit: int = 8, full: bool = False, batch_short: bool = False) -> str:
    try:
        fn = globals().get('build_errorlog_text_v250')
        if callable(fn):
            return fn(full=bool(full), batch_short=bool(batch_short))
    except Exception:
        pass
    cur = _v2141_boot_error_text(80 if full else 20)
    if cur:
        return '🧾 최근 런타임 오류 로그\n\n' + cur
    return '🧾 최근 런타임 오류 로그\n\n- 현재 부팅 이후 새 오류 없음\n- 과거 NameError tail은 기본 화면에서 접음\n- 과거 전체 원문은 /errorlog_full에서 확인'

def errorlog_command(update=None, context=None):
    send_text_chunks(build_errorlog_text(full=False), limit=2400)

def errorlog_full_command(update=None, context=None):
    send_text_chunks(build_errorlog_text(full=True), limit=3600)

def build_upgrade_status_text() -> str:
    dep = _v2141_deploy_state()
    return '\n'.join(['🧩 업그레이드 상태 /upgradestatus', f'- 버전: {BOT_VERSION}', f"- 목표파일: {dep.get('target','정보 없음')}", f"- 적용파일: {dep.get('deployed','정보 없음')}", f"- 상태: {'✅ 정상' if dep.get('ok') else '⚠️ 확인필요'} / 실행 {dep.get('rv') or '?'} · 목표 {dep.get('tv') or '?'} · 적용 {dep.get('dv') or '?'}", '- 긴 배포로그/과거 권한오류는 필요할 때만 서버 로그 확인', '', '명령어: /main /monitor /pullback /prune_check /errorlog /upgradestatus /upgradebot'])

