def _v2143_read_first_line(name: str) -> str:
    try:
        path = data_file(name) if callable(globals().get('data_file')) else str(name)
        if not os.path.exists(path):
            return ''
        with open(path, 'r', encoding='utf-8', errors='ignore') as f:
            return str(f.readline() or '').strip()
    except Exception:
        return ''

def upgrade_bot_command(update=None, context=None):
    """v2.10.45: 자동배포 경로와 메뉴 등록을 고정."""
    try:
        script = _v294_find_auto_deploy_script() if callable(globals().get('_v294_find_auto_deploy_script')) else ''
        if script:
            target = _v2143_read_first_line('DEPLOY_TARGET.txt') or 'DEPLOY_TARGET 확인불가'
            send('\n'.join([
                '📦 /upgradebot 배포 요청 접수',
                f'- 목표: {target}',
                '- 방식: 기존 자동배포 스크립트 실행',
                '- 완료 확인: 5~10초 뒤 /upgradestatus',
            ]))
            ok, msg = _v294_trigger_auto_deploy_script(script) if callable(globals().get('_v294_trigger_auto_deploy_script')) else (False, '자동배포 함수 없음')
            if ok:
                send('✅ 배포 스크립트 실행 요청 완료\n- /upgradestatus 로 적용 여부 확인')
            else:
                send('❌ 배포 요청 실패\n- ' + str(msg)[:220])
            return
        base = globals().get('_BASE_V2115_UPGRADE_BOT_COMMAND') or globals().get('_BASE_V294_UPGRADE_BOT_COMMAND')
        if callable(base):
            return base(update, context)
        send('⚠️ /upgradebot 사용 불가: 자동배포 스크립트 확인 필요')
    except Exception as e:
        try: append_runtime_error_log('v2143_upgradebot', str(e), exc=e, include_traceback=True)
        except Exception: pass
        send(f'❌ /upgradebot 오류: {e.__class__.__name__}: {str(e)[:180]}')

