# v2.10.49: 350 흐름 기준 paper 저장 I/O 다이어트 + 표시 최신화
# - 350 코드를 통째 이식하지 않는다. 현재 v2.10.x의 허브/worker/factory 구조는 유지한다.
# - paper 저장은 CLOSED/상태변경/주기 스냅샷 중심으로 줄인다.
# - 전략 조건·scan 본체·청산 조건은 변경하지 않는다.
# =========================================================
try:
    BOT_VERSION = "수익형 v2.10.49"
except Exception:
    pass

V2149_PREV_VERSION = "v2.10.48"
V2149_PREV_LINES = 39932
V2149_ACTIVE_POSITION_DISK_BUCKET_SEC = 60
V2149_PATCH_NOTE = "paper 저장 I/O 다이어트 + 350 흐름 기준 paper_update 확인"

try:
    _BASE_V2149_POSITIONS_SIGNATURE = globals().get('_v2118_positions_signature')
except Exception:
    _BASE_V2149_POSITIONS_SIGNATURE = None

try:
    _BASE_V2149_PRUNE_CHECK_TEXT = globals().get('build_prune_check_text')
except Exception:
    _BASE_V2149_PRUNE_CHECK_TEXT = None
try:
    _BASE_V2149_DEV_TEXT = globals().get('build_dev_text')
except Exception:
    _BASE_V2149_DEV_TEXT = None


def _v2149_now_bucket(sec: int = None):
    try:
        s = int(sec or V2149_ACTIVE_POSITION_DISK_BUCKET_SEC or 60)
        if s <= 0:
            s = 60
        return int(time.time() // s)
    except Exception:
        return 0


def _v2149_pos_get(v: dict, *keys, default=""):
    try:
        for k in keys:
            if isinstance(v, dict) and k in v and v.get(k) not in (None, ""):
                return v.get(k)
    except Exception:
        pass
    return default


def _v2149_num(v, nd=8, default=0.0):
    try:
        return round(_v2118_safe_float(v, default), nd)
    except Exception:
        return default


def _v2149_position_signature_item(k, v: dict, active_bucket: int):
    """디스크 저장용 안정 시그니처.
    OPEN/PENDING의 현재가·순간 pnl 변화는 매 틱 저장하지 않고 1분 버킷으로만 저장한다.
    CLOSED/상태변경/청산사유는 즉시 시그니처가 바뀌게 보존한다.
    """
    if not isinstance(v, dict):
        return (str(k), "invalid")
    st = str(v.get('status', '') or '').upper()
    ticker = str(v.get('ticker', '') or '').upper()
    base = [
        str(k), ticker, st,
        str(_v2149_pos_get(v, 'lane', 'route', 'strategy', default=''))[:80],
        str(_v2149_pos_get(v, 'signal_grade', 'grade', default=''))[:60],
        str(_v2149_pos_get(v, 'trigger', 'register_trigger', default=''))[:80],
        _v2149_num(_v2149_pos_get(v, 'entry_price', 'entry', 'buy_price', default=0), 8),
        _v2149_num(_v2149_pos_get(v, 'planned_high', 'pullback_high', 'tp1', default=0), 8),
        _v2149_num(_v2149_pos_get(v, 'planned_low', 'pullback_low', 'stop', 'stop_loss_price', default=0), 8),
        int(_v2118_safe_float(_v2149_pos_get(v, 'created_ts', 'register_ts', 'entry_ts', 'open_ts', default=0), 0)),
    ]
    if st in {'CLOSED', 'CANCELLED', 'EXPIRED', 'DEAD', 'STALE'}:
        base += [
            str(_v2149_pos_get(v, 'exit_reason', 'close_reason', 'reason', 'result_reason', default=''))[:120],
            _v2149_num(_v2149_pos_get(v, 'exit_price', 'close_price', 'sell_price', default=0), 8),
            _v2149_num(_v2149_pos_get(v, 'pnl_pct', 'profit_pct', 'return_pct', 'current_pnl', default=0), 6),
            int(_v2118_safe_float(_v2149_pos_get(v, 'closed_ts', 'exit_ts', 'close_ts', default=0), 0)),
        ]
    else:
        # 살아있는 paper는 현재가/pnl 틱마다 저장하지 않는다.
        # 단, 재시작 복구용으로 1분에 한 번은 전체 snapshot 저장이 가능하게 버킷만 포함한다.
        base += [active_bucket]
    return tuple(base)


def _v2118_positions_signature(pos_snapshot):
    """v2.10.49 override: paper OPEN/PENDING 순간 변동 저장 폭주 억제."""
    try:
        bucket = _v2149_now_bucket()
        rows = []
        for k, v in (pos_snapshot or {}).items():
            rows.append(_v2149_position_signature_item(k, v, bucket))
        return tuple(sorted(rows))
    except Exception:
        try:
            if callable(_BASE_V2149_POSITIONS_SIGNATURE):
                return _BASE_V2149_POSITIONS_SIGNATURE(pos_snapshot)
        except Exception:
            pass
        return ("pos_sig_error_v2149", time.time())


def _v2149_save_policy_line():
    try:
        return f"- paper 저장정책: OPEN/PENDING 틱변화는 {int(V2149_ACTIVE_POSITION_DISK_BUCKET_SEC)}초 버킷 저장 / CLOSED·상태변경은 즉시 저장"
    except Exception:
        return "- paper 저장정책: OPEN/PENDING 틱변화 저장폭주 억제 / CLOSED·상태변경 즉시 저장"


