# =========================================================
# v2.10.50: 350 흐름 이식 1차 - route 표준화 + register 재연결
# =========================================================
# 목표:
# - 350 코드를 통째 복붙하지 않고, 350의 시작점→분류→대기→paper 등록 흐름만 현재 구조에 맞게 붙인다.
# - pullback / M2 눌림 재확인 / 저점선점 보조 route 흔적을 paper 등록 전에 표준 필드로 박아 둔다.
# - 조건·문턱·청산 로직은 바꾸지 않는다.
try:
    BOT_VERSION = "수익형 v2.10.50"
except Exception:
    pass

V2150_PREV_VERSION = "v2.10.49"
V2150_PREV_LINES = 40127
V2150_PATCH_NOTE = "350 흐름 이식 1차: route 표준화 + paper 등록 재연결"
V2150_FLOW_STATS = {
    "route_pullback": 0,
    "route_m2": 0,
    "route_low": 0,
    "route_unknown": 0,
    "register_try": 0,
    "register_ok": 0,
    "bridge_rows": 0,
    "last_note": "대기",
}

try:
    _BASE_V2150_PAPER_REGISTER = globals().get('paper_register_candidate_v258')
except Exception:
    _BASE_V2150_PAPER_REGISTER = None
try:
    _BASE_V2150_INTERNAL_BRIDGE = globals().get('_v2148_restore_350_internal_watch_bridge')
except Exception:
    _BASE_V2150_INTERNAL_BRIDGE = None


def _v2150_txt(row) -> str:
    try:
        if not isinstance(row, dict):
            return str(row or "").lower()
        keys = [
            "ticker", "strategy", "strategy_key", "strategy_label", "route", "paper_route", "watch_route", "lane", "mode",
            "trigger", "source", "grade", "signal_grade", "decision", "entry_rule", "paper_entry_rule_v259",
            "primary_reason", "one_liner", "label_text", "rank_watch_action", "rank_watch_chart_state", "rank_watch_low_route",
            "low_structure_route_v244", "low_structure_summary_v2", "low_defense_v2_label", "low_rising_label_v2",
            "v210_strategy_key", "v210_strategy_label", "v342_good_pullback_reason", "v343_pullback_reason",
            "pattern_tag", "pattern_tags", "tags", "final_class", "final_judgement",
        ]
        parts = []
        for k in keys:
            v = row.get(k)
            if isinstance(v, dict):
                parts.extend([str(x) for x in v.values()])
            elif isinstance(v, (list, tuple, set)):
                parts.extend([str(x) for x in v])
            elif v is not None:
                parts.append(str(v))
        return " ".join(parts).lower()
    except Exception:
        return ""


def _v2150_get_low_route(row: dict) -> str:
    try:
        fn = globals().get('get_low_structure_route_label_v244')
        if callable(fn):
            val = str(fn(row if isinstance(row, dict) else {}) or "").strip()
            if val and val != "저점 구조 확인중":
                return val
    except Exception:
        pass
    try:
        return str((row or {}).get('low_structure_route_v244') or (row or {}).get('rank_watch_low_route') or "").strip()
    except Exception:
        return ""


def _v2150_detect_route(row: dict):
    """350에서 가져갈 세 갈래만 표준화한다.
    반환: (key, label, why)
    key: pullback / m2 / low / ""
    """
    try:
        txt = _v2150_txt(row)
        low_route = _v2150_get_low_route(row if isinstance(row, dict) else {})
        m2_words = ("m2", "눌림재확인", "눌림 재확인", "pullback_recheck", "recheck_pullback", "m2_pullback", "m2-recheck")
        low_words = ("저점선점", "저점방어 재출발", "저점높임 재출발", "저점방어 관찰", "low_preempt", "low_first", "low_defense", "low_rising", "low_structure", "restart_low")
        pullback_words = ("pullback_wait", "good_pullback", "pullback", "눌림", "v342", "v343", "pending_pullback")
        if any(w in txt for w in m2_words):
            return "m2", "M2 눌림 재확인", "M2/눌림 재확인 route 흔적"
        if low_route in {"저점높임 재출발형", "저점방어 재출발형", "저점방어 관찰형"} or any(w in txt for w in low_words):
            return "low", "저점선점 보조", low_route or "저점방어/저점높임 route 흔적"
        if bool((row or {}).get('v342_good_pullback_ok')) or bool((row or {}).get('v343_good_pullback_ok')):
            return "pullback", "350 pullback 본선", "v342/v343 good pullback 통과"
        try:
            pullback_pct = float((row or {}).get('recent_pullback_pct', (row or {}).get('pullback_pct_18', 0)) or 0)
        except Exception:
            pullback_pct = 0.0
        if any(w in txt for w in pullback_words) or pullback_pct > 0:
            return "pullback", "350 pullback 본선", "pullback/PULLBACK_WAIT route 흔적"
        return "", "", "350 route 근거 부족"
    except Exception as e:
        return "", "", f"route감지오류:{e.__class__.__name__}"


def _v2150_enrich_350_route(row: dict, source: str = "") -> dict:
    """paper 등록 전 route 표준 필드를 보강한다.
    - 새 조건을 만들지 않고, 이미 계산된 350 흔적을 같은 이름으로 맞춰 준다.
    - 원본 row를 직접 망가뜨리지 않기 위해 copy를 반환한다.
    """
    try:
        rr = dict(row or {}) if isinstance(row, dict) else {}
        key, label, why = _v2150_detect_route(rr)
        if not key:
            V2150_FLOW_STATS["route_unknown"] = int(V2150_FLOW_STATS.get("route_unknown", 0) or 0) + 1
            rr.setdefault('v2150_route_key', '')
            rr.setdefault('v2150_route_reason', why)
            return rr
        V2150_FLOW_STATS[f"route_{key}"] = int(V2150_FLOW_STATS.get(f"route_{key}", 0) or 0) + 1
        entry_rule = 'pullback'
        if key == 'm2':
            route_text = 'M2 눌림 재확인'
            strategy_key = 'm2'
        elif key == 'low':
            route_text = '저점선점 보조'
            strategy_key = 'low'
        else:
            route_text = '350 pullback 본선'
            strategy_key = 'main_guess'
        rr['v2150_route_key'] = key
        rr['v2150_route_label'] = label
        rr['v2150_route_reason'] = why
        rr.setdefault('v210_strategy_key', strategy_key)
        rr.setdefault('v210_strategy_label', label)
        rr.setdefault('v210_strategy_reason', why)
        rr.setdefault('strategy_key', strategy_key)
        rr.setdefault('strategy_label', label)
        rr.setdefault('paper_strategy', label)
        rr.setdefault('route', route_text)
        rr.setdefault('paper_route', route_text)
        rr.setdefault('watch_route', route_text)
        rr.setdefault('lane', route_text)
        rr.setdefault('mode', 'pullback')
        rr.setdefault('paper_type', 'pullback')
        rr.setdefault('entry_rule', entry_rule)
        rr.setdefault('paper_entry_rule_v259', entry_rule)
        rr.setdefault('grade', 'PULLBACK_WAIT')
        rr.setdefault('signal_grade', rr.get('grade') or 'PULLBACK_WAIT')
        rr.setdefault('paper_original_grade', rr.get('grade') or 'PULLBACK_WAIT')
        rr.setdefault('decision', label)
        rr.setdefault('v2150_flow_source', source or 'route_standardize')
        V2150_FLOW_STATS["last_note"] = f"{rr.get('ticker','?')}/{key}/{why}"
        return rr
    except Exception as e:
        try: append_runtime_error_log('v2150_enrich_350_route', str(e), exc=e, include_traceback=False)
        except Exception: pass
        return dict(row or {}) if isinstance(row, dict) else {}


def _v2148_restore_350_internal_watch_bridge(items, now_ts=None):
    """v2.10.50: internal_watch 브릿지에 들어가기 전 route 필드를 표준화한다."""
    try:
        rows = []
        for r in list(items or []):
            if isinstance(r, dict):
                rows.append(_v2150_enrich_350_route(r, source='scan_internal_watch_bridge'))
            else:
                rows.append(r)
        V2150_FLOW_STATS['bridge_rows'] = int(V2150_FLOW_STATS.get('bridge_rows', 0) or 0) + len(rows)
        if callable(_BASE_V2150_INTERNAL_BRIDGE):
            return _BASE_V2150_INTERNAL_BRIDGE(rows, now_ts=now_ts)
        return 0
    except Exception as e:
        try: append_runtime_error_log('v2150_internal_bridge', str(e), exc=e, include_traceback=False)
        except Exception: pass
        return 0


def paper_register_candidate_v258(row: dict, trigger: str = "auto") -> bool:
    """v2.10.50: 350 route 표준화 후 기존 최종 register chain으로 넘긴다."""
    try:
        V2150_FLOW_STATS['register_try'] = int(V2150_FLOW_STATS.get('register_try', 0) or 0) + 1
        rr = _v2150_enrich_350_route(row if isinstance(row, dict) else {}, source=f'paper_register:{trigger}')
        ok = _BASE_V2150_PAPER_REGISTER(rr, trigger=trigger) if callable(_BASE_V2150_PAPER_REGISTER) else False
        if ok:
            V2150_FLOW_STATS['register_ok'] = int(V2150_FLOW_STATS.get('register_ok', 0) or 0) + 1
        return bool(ok)
    except Exception as e:
        try: append_runtime_error_log('v2150_paper_register', str(e), exc=e, include_traceback=False)
        except Exception: pass
        return False


